// The Library rail and grid are by far the largest renderer subtree. Keep their
// last committed DOM while a dedicated Photos destination is visible, then
// reveal that exact tree before reconciling fresh props on a later frame. The
// render callback is intentional: unlike a `children` prop, it lets hidden and
// first-reveal renders avoid constructing thousands of React elements at all.
function CachedPhotoSurface({
  active,
  render,
}: {
  active: boolean;
  render: () => ReactNode;
}) {
  const cached = useRef<ReactNode>(null);
  const pendingRender = useRef(render);
  const committedActive = useRef(active);
  const deferRefresh = useRef(false);
  const [, setRefreshVersion] = useState(0);
  pendingRender.current = render;

  const revealing = active && !committedActive.current && cached.current !== null;
  if (revealing) deferRefresh.current = true;
  if (active && (cached.current === null || !deferRefresh.current)) {
    cached.current = render();
  }

  useLayoutEffect(() => {
    const becameActive = active && !committedActive.current;
    committedActive.current = active;
    if (!active) {
      deferRefresh.current = false;
      return;
    }
    if (!becameActive || !deferRefresh.current) return;

    // Give the preserved surface one complete visible frame, then reconcile
    // current callbacks and state outside the navigation interaction.
    let refreshFrame = 0;
    const visibleFrame = window.requestAnimationFrame(() => {
      refreshFrame = window.requestAnimationFrame(() => {
        if (!committedActive.current) return;
        deferRefresh.current = false;
        setRefreshVersion((version) => version + 1);
      });
    });
    return () => {
      window.cancelAnimationFrame(visibleFrame);
      if (refreshFrame) window.cancelAnimationFrame(refreshFrame);
    };
  }, [active]);

  if (cached.current === null) return null;
  return (
    <div className="photos-library-surface" hidden={!active} aria-hidden={!active || undefined}>
      {cached.current}
    </div>
  );
}

