  async function saveImportHistoryProvenanceEdit(importId: string = importHistoryEditId) {
    const { payload, error } = photoImportHistoryProvenancePayload({
      importId,
      sourceKind: importHistoryEditKind,
      sourceLabel: importHistoryEditLabel,
      sourceDetail: importHistoryEditDetail,
    });
    if (!payload) {
      if (error) setImportHistoryEditError(uiText(error));
      return;
    }
    setImportHistoryEditSaving(true);
    setImportHistoryEditError("");
    setImportHistoryEditStatus("");
    try {
      const result = await props.updatePhotoImportSessionProvenance(payload);
      const updatedAssets = Number(result.value?.updatedAssets || 0);
      setImportHistoryEditId("");
      setImportHistoryEditLabel("");
      setImportHistoryEditDetail("");
      setImportHistoryEditStatus(photoImportHistoryProvenanceStatusLabel(updatedAssets, { formatCount, text: uiText }));
      await loadFolders();
      await loadPage(currentPageRequest({ offset: 0 }));
      if (activeRecoveredCollection) {
        await loadRecoveredFailures();
      }
    } catch (error) {
      setImportHistoryEditError(errorMessage(error));
    } finally {
      setImportHistoryEditSaving(false);
    }
  }

