  async function refreshSensitiveAuthStatus() {
    if (!getSensitiveAuthStatus) {
      setSensitiveAuthStatus(null);
      setSensitiveAuthStatusMessage(uiText("Device authentication is not available in this build."));
      return null;
    }
    setSensitiveAuthLoading(true);
    try {
      const status = await getSensitiveAuthStatus();
      setSensitiveAuthStatus(status);
      setSensitiveAuthStatusMessage(status?.reason || "");
      return status;
    } catch (error) {
      setSensitiveAuthStatus(null);
      setSensitiveAuthStatusMessage(errorMessage(error));
      return null;
    } finally {
      setSensitiveAuthLoading(false);
    }
  }

  async function verifySensitiveDeviceAuth() {
    const currentStatus = sensitiveAuthStatus?.available ? sensitiveAuthStatus : await refreshSensitiveAuthStatus();
    if (!currentStatus?.available || !authenticateSensitiveAccess) {
      setSensitiveUnlockError(sensitiveOsAuthUnavailableMessage);
      return false;
    }
    setSensitiveAuthPrompting(true);
    try {
      const result = await authenticateSensitiveAccess("Unlock Hidden and Recently Deleted in Vintrace.");
      if (result?.ok) {
        setSensitiveAuthStatus(result);
        setSensitiveAuthStatusMessage("");
        return true;
      }
      const message = result?.error || result?.reason || uiText("Device authentication did not complete.");
      setSensitiveAuthStatus(result || currentStatus);
      setSensitiveAuthStatusMessage(message);
      setSensitiveUnlockError(message);
      return false;
    } catch (error) {
      const message = errorMessage(error);
      setSensitiveUnlockError(message);
      setSensitiveAuthStatusMessage(message);
      return false;
    } finally {
      setSensitiveAuthPrompting(false);
    }
  }

  async function unlockSensitiveCollections(passcode = "") {
    const settings = photoSettingsRef.current;
    const passcodeConfigured = photoSensitivePasscodeConfigured(settings);
    let verifiedWithDevice = false;
    if (sensitiveUnlockRequirements(settings, { passcodeProvided: Boolean(passcode), verifiedWithDevice, passcodeConfigured }).deviceAuthRequired) {
      verifiedWithDevice = await verifySensitiveDeviceAuth();
      if (!verifiedWithDevice) return false;
    }
    if (sensitiveUnlockRequirements(settings, { passcodeProvided: Boolean(passcode), verifiedWithDevice, passcodeConfigured }).passcodeRequired) {
      const candidate = passcode || sensitiveUnlockPasscode;
      if (!candidate) {
        setSensitiveUnlockError(uiText("Enter the sensitive collection passcode."));
        return false;
      }
      let verified = false;
      try {
        verified = await verifyPhotoSensitivePasscode(settings, candidate);
      } catch {
        setSensitiveUnlockError(uiText("Passcode verification is unavailable in this browser context."));
        return false;
      }
      if (!verified) {
        setSensitiveUnlockError(uiText("Passcode did not match."));
        setSensitiveCollectionsUnlocked(false);
        return false;
      }
    }
    setPhotoRailDisplayPreference("showSensitiveCollections", true);
    setSensitiveCollectionsUnlocked(true);
    setSensitiveUnlockPasscode("");
    setSensitiveUnlockError("");
    return true;
  }

  function lockSensitiveCollections() {
    setSensitiveCollectionsUnlocked(false);
    setSensitiveUnlockPasscode("");
    setSensitiveUnlockError("");
    if (activeSensitiveCollection) clearLockedSensitiveItems();
  }

  useEffect(() => {
    if (sensitiveSessionTimerRef.current !== null) {
      window.clearTimeout(sensitiveSessionTimerRef.current);
      sensitiveSessionTimerRef.current = null;
    }
    const timeoutMs = sensitiveSessionLockTimeoutMs(photoSettings, sensitiveCollectionsUnlocked);
    if (timeoutMs === null) return undefined;
    const refreshSensitiveSessionTimer = () => {
      if (sensitiveSessionTimerRef.current !== null) window.clearTimeout(sensitiveSessionTimerRef.current);
      sensitiveSessionTimerRef.current = window.setTimeout(() => {
        lockSensitiveCollections();
      }, timeoutMs);
    };
    const onVisibilityChange = () => {
      if (document.visibilityState === "hidden") refreshSensitiveSessionTimer();
    };
    refreshSensitiveSessionTimer();
    window.addEventListener("focus", refreshSensitiveSessionTimer);
    window.addEventListener("pointerdown", refreshSensitiveSessionTimer);
    window.addEventListener("keydown", refreshSensitiveSessionTimer);
    document.addEventListener("visibilitychange", onVisibilityChange);
    return () => {
      if (sensitiveSessionTimerRef.current !== null) {
        window.clearTimeout(sensitiveSessionTimerRef.current);
        sensitiveSessionTimerRef.current = null;
      }
      window.removeEventListener("focus", refreshSensitiveSessionTimer);
      window.removeEventListener("pointerdown", refreshSensitiveSessionTimer);
      window.removeEventListener("keydown", refreshSensitiveSessionTimer);
      document.removeEventListener("visibilitychange", onVisibilityChange);
    };
  }, [
    activeSensitiveCollection,
    clearLockedSensitiveItems,
    photoSettings.lockSensitiveCollections,
    photoSettings.sensitiveSessionLockMinutes,
    sensitiveCollectionsUnlocked,
  ]);

  function persistPhotoLocalSettings(nextValue: PhotoLocalSettings) {
    const next = normalizePhotoLocalSettings(nextValue);
    photoSettingsRef.current = next;
    setPhotoSettings(next);
    storePhotoLocalSettings(PHOTO_LOCAL_SETTINGS_KEY, next);
    storeLegacyPhotoRailPreferences(next.railPreferences);
    return next;
  }

  function applyPhotoRailPreferences(nextValue: PhotoRailPreferences) {
    const next = normalizePhotoRailPreferences(nextValue);
    setShowUtilityCollections(next.showUtilityCollections);
    setShowSensitiveCollections(next.showSensitiveCollections);
    setShowScreenshotCollections(next.showScreenshotCollections);
    setShowSharedCollections(next.showSharedCollections);
    setShowLowValueCollections(next.showLowValueCollections);
    setPinnedRailIds(new Set(next.pinnedIds));
    setCollapsedRailSections(new Set(next.collapsedSections));
    setRailSectionOrder(normalizePhotoRailSectionOrder(next.sectionOrder));
    setRailItemOrder(normalizePhotoRailItemOrderPreference(next.itemOrder));
    storeLegacyPhotoRailPreferences(next);
  }

  function applyWorkspacePhotoLocalSettings(nextValue: unknown) {
    const next = persistPhotoLocalSettings(normalizePhotoLocalSettingsWithLegacyRail(nextValue));
    applyPhotoRailPreferences(next.railPreferences);
    if (next.lockSensitiveCollections) {
      lockSensitiveCollections();
    } else {
      void unlockSensitiveCollections();
    }
    setExportStripLocation(next.stripLocationOnExport);
    setLightboxVideoMuted(shouldMuteAutoplayPhotoVideo(photoEffectiveMediaSettings(next, activeLibraryRootRef.current)));
    return next;
  }

  function updatePhotoLocalSettings(patch: Partial<PhotoLocalSettings>) {
    const next = persistPhotoLocalSettings({ ...photoSettingsRef.current, ...patch });
    if (Object.prototype.hasOwnProperty.call(patch, "lockSensitiveCollections")) {
      if (next.lockSensitiveCollections) {
        lockSensitiveCollections();
      } else {
        void unlockSensitiveCollections();
      }
    }
    if (Object.prototype.hasOwnProperty.call(patch, "stripLocationOnExport")) {
      setExportStripLocation(next.stripLocationOnExport);
    }
    if (
      Object.prototype.hasOwnProperty.call(patch, "videoAutoplay")
      || Object.prototype.hasOwnProperty.call(patch, "mediaSettingsByLibraryRoot")
    ) {
      setLightboxVideoMuted(shouldMuteAutoplayPhotoVideo(photoEffectiveMediaSettings(next, activeLibraryRootRef.current)));
    }
    if (Object.prototype.hasOwnProperty.call(patch, "recentActivityRetentionDays")) {
      refreshCurrentPhotoPage();
    }
    if (Object.prototype.hasOwnProperty.call(patch, "visionModelTier")) {
      void refreshPhotoVlmStatus();
    }
    setPhotoLibraryProfileError("");
    void savePhotoLibrarySettings({ localSettings: next })
      .then((result) => setPhotoLibraryProfile(result.value || null))
      .catch((error) => setPhotoLibraryProfileError(errorMessage(error)));
  }

  function updatePhotoRailPreferences(patch: Partial<PhotoRailPreferences>) {
    const next = normalizePhotoRailPreferences({
      ...photoSettingsRef.current.railPreferences,
      ...patch,
    });
    updatePhotoLocalSettings({ railPreferences: next });
  }

  function setPhotoRailDisplayPreference(key: PhotoRailDisplayPreferenceKey, value: boolean) {
    if (key === "showUtilityCollections") setShowUtilityCollections(value);
    if (key === "showSensitiveCollections") setShowSensitiveCollections(value);
    if (key === "showScreenshotCollections") setShowScreenshotCollections(value);
    if (key === "showSharedCollections") setShowSharedCollections(value);
    if (key === "showLowValueCollections") setShowLowValueCollections(value);
    updatePhotoRailPreferences({ [key]: value } as Partial<PhotoRailPreferences>);
  }

  function updatePhotoLibraryMediaSettings(patch: PhotoLibraryMediaSettingsOverride) {
    const root = activeLibraryRootRef.current;
    if (!root) return;
    updatePhotoLocalSettings(photoMediaSettingsOverridePatch(photoSettingsRef.current, root, patch));
  }

  function resetPhotoLibraryMediaSettings() {
    const root = activeLibraryRootRef.current;
    if (!root) return;
    updatePhotoLocalSettings(photoMediaSettingsOverridePatch(photoSettingsRef.current, root, null));
  }

  async function saveSensitivePasscode() {
    const passcode = sensitivePasscodeDraft;
    if (passcode.length < 4) {
      setSensitivePasscodeStatus(uiText("Use at least 4 characters."));
      return;
    }
    if (passcode !== sensitivePasscodeConfirmDraft) {
      setSensitivePasscodeStatus(uiText("Passcodes do not match."));
      return;
    }
    setSensitivePasscodeSaving(true);
    try {
      const record = await createPhotoSensitivePasscodeRecord(passcode);
      updatePhotoLocalSettings({
        ...record,
        lockSensitiveCollections: true,
      });
      setSensitivePasscodeDraft("");
      setSensitivePasscodeConfirmDraft("");
      setSensitivePasscodeStatus(uiText("Sensitive passcode saved."));
      lockSensitiveCollections();
    } catch (error) {
      setSensitivePasscodeStatus(errorMessage(error));
    } finally {
      setSensitivePasscodeSaving(false);
    }
  }

  function clearSensitivePasscode() {
    updatePhotoLocalSettings({
      sensitivePasscodeEnabled: false,
      sensitivePasscodeSalt: "",
      sensitivePasscodeHash: "",
    });
    setSensitivePasscodeDraft("");
    setSensitivePasscodeConfirmDraft("");
    setSensitivePasscodeStatus(uiText("Sensitive passcode cleared."));
  }

  function applyPhotoIndexingMetadataUpdates(value: Record<string, unknown>) {
    const rows = Array.isArray(value.items) ? value.items : [];
    const updates = new Map<string, Record<string, unknown>>();
    rows.forEach((row) => {
      if (!row || typeof row !== "object") return;
      const record = row as Record<string, unknown>;
      const sourcePath = String(record.sourcePath || "");
      const assetMetadata = record.assetMetadata && typeof record.assetMetadata === "object" ? record.assetMetadata as Record<string, unknown> : null;
      if (sourcePath && assetMetadata) updates.set(sourcePath, assetMetadata);
    });
    if (!updates.size) return;
    setItems((current) => current.map((item) => (
      updates.has(item.sourcePath)
        ? { ...item, assetMetadata: { ...(item.assetMetadata || {}), ...(updates.get(item.sourcePath) || {}) } }
        : item
    )));
  }

  async function refreshPhotoIndexingQueue() {
    try {
      const result = await photoIndexingJobs({ limit: 8 });
      setPhotoIndexingQueueValue(result.value || null);
      setPhotoIndexingQueueError("");
    } catch (error) {
      setPhotoIndexingQueueError(errorMessage(error));
    }
  }

  async function refreshPhotoAudioRuntimeStatus() {
    setPhotoAudioRuntimeBusy(true);
    try {
      const [audioResult, runtimeResult] = await Promise.all([
        window.crossAge.invoke<{ value: Record<string, unknown> }>("photo_audio_status", {}),
        window.crossAge.getPhotoIndexingRuntimeStatus(),
      ]);
      setPhotoAudioStatusValue(audioResult.value || null);
      setPhotoIndexingRuntimeStatus(runtimeResult || null);
      setPhotoAudioStatusError("");
    } catch (error) {
      setPhotoAudioStatusError(errorMessage(error));
    } finally {
      setPhotoAudioRuntimeBusy(false);
    }
  }

  function openPhotoIndexingQueue() {
    setPhotoSettingsOpen(true);
    void refreshPhotoIndexingQueue();
    window.requestAnimationFrame(() => {
      document.getElementById("photos-local-settings")?.scrollIntoView({ block: "start", behavior: "smooth" });
    });
  }

  async function enqueuePhotoLocalIndexingJob(jobKind: "ocr" | "barcode" | "objects" | "audio", scope: Record<string, unknown>) {
    if (!photoSettings.localIntelligenceEnabled) {
      setPhotoIndexingQueueError(uiText("Local intelligence is disabled."));
      return;
    }
    setPhotoIndexingQueueBusy(true);
    setPhotoIndexingQueueError("");
    setPhotoIndexingQueueNotice("");
    try {
      const result = await enqueuePhotoIndexingJob({ jobKind, scope, limit: 8 });
      setPhotoIndexingQueueValue(result.value || null);
      setPhotoIndexingQueueNotice(
        jobKind === "ocr"
          ? uiText("OCR job queued.")
          : jobKind === "objects"
            ? uiText("Detected items job queued.")
            : jobKind === "audio"
              ? uiText("Audio intelligence job queued.")
              : uiText("Barcode job queued."),
      );
    } catch (error) {
      setPhotoIndexingQueueError(errorMessage(error));
    } finally {
      setPhotoIndexingQueueBusy(false);
    }
  }

  async function enqueueLoadedPhotoIndexingJob(jobKind: "ocr" | "barcode" | "objects" | "audio") {
    const sourcePaths = items
      .filter((item) => jobKind !== "audio" || item.mediaKind === "video")
      .map((item) => item.sourcePath)
      .filter(Boolean);
    if (!sourcePaths.length) {
      setPhotoIndexingQueueError(
        jobKind === "ocr"
          ? uiText("Load photos before queuing OCR.")
          : jobKind === "objects"
            ? uiText("Load photos before queuing detected items.")
            : jobKind === "audio"
              ? uiText("Load videos before queuing audio intelligence.")
              : uiText("Load photos before queuing barcodes."),
      );
      return;
    }
    await enqueuePhotoLocalIndexingJob(jobKind, {
      sourcePaths,
      ...(jobKind === "ocr" ? { language: "eng", useExternalEngine: true } : {}),
      ...(jobKind === "objects" ? { useModel: true, modelTier: photoSettingsRef.current.visionModelTier } : {}),
      ...(jobKind === "audio" ? { transcribe: true, soundEvents: true, language: "auto" } : {}),
    });
  }

  async function enqueuePendingPhotoIndexingJob(jobKind: "ocr" | "barcode" | "objects" | "audio") {
    await enqueuePhotoLocalIndexingJob(jobKind, {
      allPhotos: true,
      pendingOnly: true,
      limit: 100000,
      ...(jobKind === "ocr" ? { language: "eng", useExternalEngine: true } : {}),
      ...(jobKind === "objects" ? { useModel: true, modelTier: photoSettingsRef.current.visionModelTier } : {}),
      ...(jobKind === "audio" ? { transcribe: true, soundEvents: true, language: "auto" } : {}),
    });
  }

  async function enqueuePhotoCatalogIndexingJob(jobKind: "generated_collections" | "smart_albums") {
    setPhotoIndexingQueueBusy(true);
    setPhotoIndexingQueueError("");
    setPhotoIndexingQueueNotice("");
    try {
      const libraryRoot = activeLibraryRootRef.current;
      const scope = {
        ...(libraryRoot ? { libraryRoot } : {}),
        ...(jobKind === "smart_albums" ? { force: true } : {}),
      };
      const result = await enqueuePhotoIndexingJob({ jobKind, scope, limit: 8 });
      setPhotoIndexingQueueValue(result.value || null);
      setPhotoIndexingQueueNotice(jobKind === "smart_albums" ? uiText("Smart album refresh queued.") : uiText("Generated collection refresh queued."));
    } catch (error) {
      setPhotoIndexingQueueError(errorMessage(error));
    } finally {
      setPhotoIndexingQueueBusy(false);
    }
  }

  function applyPhotoIndexingJobRunResult(job: Record<string, unknown>) {
    const jobResult = job.result && typeof job.result === "object" ? job.result as Record<string, unknown> : {};
    if (jobResult.items) applyPhotoIndexingMetadataUpdates(jobResult);
    if (job.jobKind === "ocr" && Object.keys(jobResult).length) setPhotoOcrIndexStatusValue(jobResult);
    if (job.jobKind === "barcode" && Object.keys(jobResult).length) setPhotoBarcodeIndexStatusValue(jobResult);
    if (job.jobKind === "objects" && Object.keys(jobResult).length) setPhotoObjectIndexStatusValue(jobResult);
    if (job.jobKind === "audio") void refreshPhotoAudioRuntimeStatus();
  }

  function applyPhotoIndexingQueueRunResult(value: Record<string, unknown>) {
    const jobs = [
      ...(Array.isArray(value.jobsRun) ? value.jobsRun : []),
      ...(value.job && typeof value.job === "object" ? [value.job] : []),
    ].filter((job): job is Record<string, unknown> => Boolean(job && typeof job === "object"));
    jobs.forEach(applyPhotoIndexingJobRunResult);
    return jobs;
  }

  async function runNextPhotoIndexingJob() {
    setPhotoIndexingQueueBusy(true);
    setPhotoIndexingQueueError("");
    setPhotoIndexingQueueNotice("");
    try {
      const result = await runPhotoIndexingQueue({ limit: 8, maxJobs: 1 });
      const value = result.value || {};
      setPhotoIndexingQueueValue(value);
      const jobs = applyPhotoIndexingQueueRunResult(value);
      const job = jobs[0] || {};
      const ranCount = Number(value.ran || jobs.length || 0) || 0;
      if (value.skipped || !ranCount) {
        setPhotoIndexingQueueError(String(value.message || uiText("No queued Photo indexing jobs.")));
      } else if (job.status === "paused") {
        setPhotoIndexingQueueError(String(job.error || uiText("Photo indexing is paused.")));
      } else if (job.status === "failed") {
        setPhotoIndexingQueueError(String(job.error || uiText("Photo indexing job failed.")));
      } else {
        setPhotoIndexingQueueNotice(uiText("Photo indexing queue ran next job."));
      }
      void refreshPhotoOcrIndexStatus();
      void refreshPhotoBarcodeIndexStatus();
      void refreshPhotoObjectIndexStatus();
      void refreshPhotoAudioRuntimeStatus();
    } catch (error) {
      setPhotoIndexingQueueError(errorMessage(error));
    } finally {
      setPhotoIndexingQueueBusy(false);
    }
  }

  async function runPhotoIndexingQueueJob(jobId: string, rerun = false) {
    const cleanJobId = String(jobId || "").trim();
    if (!cleanJobId) return;
    setPhotoIndexingQueueBusy(true);
    setPhotoIndexingActiveJobId(cleanJobId);
    setPhotoIndexingQueueError("");
    setPhotoIndexingQueueNotice("");
    try {
      const result = await runPhotoIndexingJob({ jobId: cleanJobId, rerun, limit: 8 });
      const value = result.value || {};
      setPhotoIndexingQueueValue(value);
      const jobs = applyPhotoIndexingQueueRunResult(value);
      const job = jobs[0] || {};
      if (value.ran === false) {
        setPhotoIndexingQueueError(String(value.message || uiText("Photo indexing job is not queued.")));
      } else if (job.status === "failed") {
        setPhotoIndexingQueueError(String(job.error || uiText("Photo indexing job failed.")));
      } else if (job.status === "paused") {
        setPhotoIndexingQueueError(String(job.error || uiText("Photo indexing is paused.")));
      } else {
        setPhotoIndexingQueueNotice(rerun ? uiText("Photo indexing job retried.") : uiText("Photo indexing job ran."));
      }
      void refreshPhotoOcrIndexStatus();
      void refreshPhotoBarcodeIndexStatus();
      void refreshPhotoObjectIndexStatus();
      void refreshPhotoAudioRuntimeStatus();
    } catch (error) {
      setPhotoIndexingQueueError(errorMessage(error));
    } finally {
      setPhotoIndexingActiveJobId("");
      setPhotoIndexingQueueBusy(false);
    }
  }

  async function cancelPhotoIndexingQueueJob(jobId: string) {
    const cleanJobId = String(jobId || "").trim();
    if (!cleanJobId) return;
    setPhotoIndexingQueueBusy(true);
    setPhotoIndexingQueueError("");
    setPhotoIndexingQueueNotice("");
    try {
      const result = await cancelPhotoIndexingJob({ jobId: cleanJobId, limit: 8 });
      const value = result.value || {};
      setPhotoIndexingQueueValue(value);
      if (value.jobCancelled === false) {
        setPhotoIndexingQueueError(String(value.message || uiText("Photo indexing job was not cancelled.")));
      } else {
        setPhotoIndexingQueueNotice(uiText("Photo indexing job cancelled."));
      }
    } catch (error) {
      setPhotoIndexingQueueError(errorMessage(error));
    } finally {
      setPhotoIndexingQueueBusy(false);
    }
  }

  async function dismissPhotoIndexingQueueJob(jobId: string) {
    const cleanJobId = String(jobId || "").trim();
    if (!cleanJobId) return;
    setPhotoIndexingQueueBusy(true);
    setPhotoIndexingQueueError("");
    setPhotoIndexingQueueNotice("");
    try {
      const result = await dismissPhotoIndexingJob({ jobId: cleanJobId, limit: 8 });
      const value = result.value || {};
      setPhotoIndexingQueueValue(value);
      if (value.dismissed === false) {
        setPhotoIndexingQueueError(String(value.message || uiText("Photo indexing job was not dismissed.")));
      } else {
        setPhotoIndexingQueueNotice(uiText("Photo indexing job dismissed."));
      }
    } catch (error) {
      setPhotoIndexingQueueError(errorMessage(error));
    } finally {
      setPhotoIndexingQueueBusy(false);
    }
  }

  async function runPhotoIndexingQueueBatch(automatic = false, includeFailed = false) {
    let runtimeStatus: PhotoIndexingRuntimeStatus | null = null;
    if (automatic) {
      try {
        runtimeStatus = await window.crossAge.getPhotoIndexingRuntimeStatus();
        setPhotoIndexingRuntimeStatus(runtimeStatus);
        if (!runtimeStatus?.allowed || runtimeStatus.maxCostClass === "none") return;
      } catch {
        return;
      }
    }
    setPhotoIndexingQueueBusy(true);
    if (!automatic) {
      setPhotoIndexingQueueError("");
      setPhotoIndexingQueueNotice("");
    }
    try {
      const result = await runPhotoIndexingQueue({
        limit: 8,
        maxJobs: automatic ? 2 : 5,
        automatic,
        includeFailed,
        ...(runtimeStatus
          ? { maxCostClass: runtimeStatus.maxCostClass, runtimeState: runtimeStatus }
          : {}),
      });
      const value = result.value || {};
      setPhotoIndexingQueueValue(value);
      const jobs = applyPhotoIndexingQueueRunResult(value);
      const ranCount = Number(value.ran || jobs.length || 0) || 0;
      if (value.skipped) {
        if (!automatic) setPhotoIndexingQueueError(String(value.message || uiText("Photo indexing queue skipped.")));
      } else if (!ranCount) {
        if (!automatic) setPhotoIndexingQueueError(String(value.message || uiText("No queued Photo indexing jobs.")));
      } else if (!automatic) {
        setPhotoIndexingQueueNotice(`${includeFailed ? uiText("Photo indexing retry ran") : uiText("Photo indexing queue ran")} ${formatCount(ranCount)} ${ranCount === 1 ? uiText("job") : uiText("jobs")}.`);
      }
      void refreshPhotoOcrIndexStatus();
      void refreshPhotoBarcodeIndexStatus();
      void refreshPhotoObjectIndexStatus();
      void refreshPhotoAudioRuntimeStatus();
    } catch (error) {
      if (!automatic) setPhotoIndexingQueueError(errorMessage(error));
    } finally {
      setPhotoIndexingQueueBusy(false);
    }
  }

  async function refreshPhotoOcrIndexStatus() {
    try {
      const result = await photoOcrIndexStatus({});
      setPhotoOcrIndexStatusValue(result.value || null);
      setPhotoOcrIndexError("");
    } catch (error) {
      setPhotoOcrIndexError(errorMessage(error));
    }
  }

  async function runPhotoOcrIndex(force = false, failedOnly = false, pendingOnly = false) {
    if (photoSettings.backgroundIndexingPaused) {
      setPhotoOcrIndexError(uiText("Photo indexing is paused."));
      return;
    }
    const sourcePaths = items.map((item) => item.sourcePath).filter(Boolean);
    if (!failedOnly && !pendingOnly && !sourcePaths.length) {
      setPhotoOcrIndexError(uiText("Load photos before indexing OCR."));
      return;
    }
    setPhotoOcrIndexing(true);
    setPhotoOcrIndexError("");
    setPhotoIndexingQueueNotice("");
    try {
      const result = await indexPhotoOcr({
        ...(failedOnly
          ? { failedOnly: true, limit: 100000 }
          : pendingOnly
            ? { allPhotos: true, pendingOnly: true, limit: 100000 }
            : { sourcePaths }),
        force: failedOnly ? true : force,
        language: "eng",
        useExternalEngine: true,
      });
      const value = result.value || {};
      setPhotoOcrIndexStatusValue(value);
      if (value.paused) {
        setPhotoOcrIndexError(String(value.message || uiText("Photo indexing is paused.")));
        return;
      }
      const rows = Array.isArray(value.items) ? value.items : [];
      const updates = new Map<string, Record<string, unknown>>();
      rows.forEach((row) => {
        if (!row || typeof row !== "object") return;
        const record = row as Record<string, unknown>;
        const sourcePath = String(record.sourcePath || "");
        const assetMetadata = record.assetMetadata && typeof record.assetMetadata === "object" ? record.assetMetadata as Record<string, unknown> : null;
        if (sourcePath && assetMetadata) updates.set(sourcePath, assetMetadata);
      });
      if (updates.size) {
        setItems((current) => current.map((item) => (
          updates.has(item.sourcePath)
            ? { ...item, assetMetadata: { ...(item.assetMetadata || {}), ...(updates.get(item.sourcePath) || {}) } }
            : item
        )));
      }
      const progress = value.progress && typeof value.progress === "object" ? value.progress as Record<string, unknown> : {};
      const deferred = Number(progress.deferred || 0) || 0;
      const deferredText = deferred > 0 ? ` · ${uiText("deferred")} ${formatCount(deferred)}` : "";
      setPhotoIndexingQueueNotice(`${uiText("OCR indexed")}: ${formatCount(Number(progress.updated || 0) || 0)} · ${uiText("failed")} ${formatCount(Number(progress.failed || 0) || 0)}${deferredText}`);
      void refreshPhotoOcrIndexStatus();
    } catch (error) {
      setPhotoOcrIndexError(errorMessage(error));
    } finally {
      setPhotoOcrIndexing(false);
    }
  }

