  const slideshowTemplateFrameClass = slideshowPlaybackThemeTemplateFrameStyle === "auto"
    ? "template-frame-auto"
    : `template-frame-${slideshowPlaybackThemeTemplateFrameStyle}`;
  const slideshowTemplateChromeClass = slideshowPlaybackThemeTemplateChromeDensity === "auto"
