  const slideshowCurrentDurationMs = Math.max(500, Math.min(60000, slideshowCurrentTimelineItem?.durationMs || slideshowIntervalMs));
  const slideshowCurrentKeyframes = slideshowCurrentTimelineItem?.keyframes || null;
