    const endPath = slideshowPlaybackAudioPlacementEndSourcePath.trim();
    if (!startPath && !endPath) return true;
    const startIndex = startPath ? slideshowItems.findIndex((item) => item.sourcePath === startPath) : 0;
    const endIndex = endPath ? slideshowItems.findIndex((item) => item.sourcePath === endPath) : slideshowItems.length - 1;
    if ((startPath && startIndex < 0) || (endPath && endIndex < 0)) return true;
