  const lightItemLiveTextRegions = useMemo(() => buildPhotoLiveTextRegions(lightItem), [lightItem]);
  const selectedLiveTextRegion = useMemo(
    () => lightItemLiveTextRegions.find((region) => region.id === selectedLiveTextRegionId) || null,
    [lightItemLiveTextRegions, selectedLiveTextRegionId]
  );
