    setDuplicatingAlbumId("");
    setAlbumKindDraft(folder.albumKind === "manual" ? "manual" : "smart");
    setAlbumName(folder.name);
    setAlbumDescription(folder.description || "");
    setAlbumFolderDraft(folder.folderId || "");
    setIncludePeople(folder.includePeople || []);
    setExcludePeople(folder.excludePeople || []);
