    setEditingAlbumId("");
    setDuplicatingAlbumId(folder.albumKind === "manual" ? folder.albumId || folder.id.replace(/^album:/, "") : "");
    setAlbumKindDraft(folder.albumKind === "manual" ? "manual" : "smart");
    setAlbumName(`${folder.name} copy`);
    setAlbumDescription(folder.description || "");
    setAlbumFolderDraft(folder.folderId || "");
    setIncludePeople(folder.includePeople || []);
    setExcludePeople(folder.excludePeople || []);
    setAlbumRules(folder.rules || EMPTY_PHOTO_ALBUM_RULES);
    setSmartQueryEditorDraft(null);
    setAlbumRulePreview(null);
