  async function renameActivePerson() {
    const oldName = activePerson?.name || "";
    const newName = personRenameDraft.trim();
    const oldKey = oldName.toLowerCase();
    const newKey = newName.toLowerCase();
    if (!oldName || !newName || oldKey === newKey) return;
    const mergeTarget = people.some((person) => person.toLowerCase() === newKey && person.toLowerCase() !== oldKey);
    if (!await confirmPhotoAction({
      title: mergeTarget ? uiText("Merge person") : uiText("Rename person"),
      message: mergeTarget
        ? `${uiText("Merge")} ${oldName} ${uiText("into")} ${newName}?`
        : `${uiText("Rename")} ${oldName} ${uiText("to")} ${newName}?`,
      confirmLabel: mergeTarget ? uiText("Merge") : uiText("Rename"),
      danger: false,
    })) return;
    setPersonRenameSaving(true);
    setPersonRenameError("");
    try {
      await renamePerson(oldName, newName, { confirm: false });
      const nextId = `person:${newName}`;
      setSelectedSources(new Set());
      setActiveId(nextId);
      setPersonRenameDraft(newName);
      await loadFolders();
      await loadSuggestions();
      await loadDuplicatePeople();
      await loadPhotoOperations();
      await loadPage(currentPageRequest({ folderId: nextId, offset: 0 }));
    } catch (error) {
      setPersonRenameError(error instanceof Error ? error.message : String(error));
    } finally {
      setPersonRenameSaving(false);
    }
  }

