  async function reassignLightboxPersonMatch(person: PhotoPersonPresence) {
    const candidateId = String(person.candidateId || "");
    const target = String(personMatchDrafts[candidateId] || "").trim();
    if (!candidateId || !target || target.toLowerCase() === person.personName.toLowerCase()) return;
    if (!await confirmPhotoAction({
      title: uiText("Move match"),
      message: `${uiText("Move this match from")} ${person.personName} ${uiText("to")} ${target}?`,
      confirmLabel: uiText("Move match"),
      danger: false,
    })) return;
    setPersonMatchSavingId(candidateId);
    setPersonMatchError("");
    try {
      await reassignCandidatePerson(candidateId, target);
      const nextActiveId = activeId === `person:${person.personName}` ? `person:${target}` : activeId;
      if (nextActiveId !== activeId) setActiveId(nextActiveId);
      setPersonMatchDrafts((current) => ({ ...current, [candidateId]: "" }));
      refreshCurrentPhotoPage(nextActiveId);
      await loadPhotoOperations();
    } catch (error) {
      setPersonMatchError(error instanceof Error ? error.message : String(error));
    } finally {
      setPersonMatchSavingId("");
    }
  }

  async function openSuggestedReviewMore(
    params: Record<string, unknown>,
    label: string,
    scope: "person" | "group",
    fallbackCandidateIds: string[]
  ) {
    setReviewMoreLoading(scope);
    setReviewMoreError("");
    try {
      const result = await suggestPhotoReviewMoreCandidates({ limit: 120, ...params });
      const candidateIds = (result.value?.candidateIds || []).map((candidateId) => String(candidateId || "")).filter(Boolean);
      const nextIds = candidateIds.length ? candidateIds : fallbackCandidateIds;
      if (!nextIds.length) {
        setReviewMoreError(uiText("No suggested matches yet."));
        return;
      }
      openReviewForCandidates(nextIds, { label, refreshState: true });
    } catch (error) {
      setReviewMoreError(error instanceof Error ? error.message : String(error));
    } finally {
      setReviewMoreLoading("");
    }
  }

