  async function reviewInlineCandidate(candidate: ReviewCandidate, status: CandidateStatus) {
    if (!candidate.candidateId) return;
    const previousStatus = candidate.status;
    setInlineReviewSavingId(candidate.candidateId);
    try {
      await reviewCandidate(status, candidate);
      setInlineReviewDecisions((current) => {
        const next = normalizePhotoInlineReviewDecisions([
          {
            id: `${candidate.candidateId}:${Date.now()}`,
            candidateId: candidate.candidateId,
            personName: candidate.personName,
            sourcePath: candidate.sourcePath,
            previousStatus,
            status,
            score: candidate.score,
            decidedAt: new Date().toISOString(),
          },
          ...current.filter((item) => item.candidateId !== candidate.candidateId),
        ]);
        storePhotoInlineReviewDecisions(PHOTO_INLINE_REVIEW_DECISIONS_KEY, next);
        return next;
      });
      await loadPhotoOperations();
    } finally {
      setInlineReviewSavingId((current) => current === candidate.candidateId ? "" : current);
    }
  }

  function clearInlineReviewDecisionHistory() {
    setInlineReviewDecisions([]);
    storePhotoInlineReviewDecisions(PHOTO_INLINE_REVIEW_DECISIONS_KEY, []);
  }

