  function reviewCandidatesForManagedGroup(folder: PhotoFolder): ReviewCandidate[] {
    const memberPeople = folder.groupProfile?.memberPeople || folder.groupPeople || [];
    const excludePeople = folder.groupProfile?.excludePeople || folder.excludePeople || [];
    return buildPhotoGroupReviewCandidates({
      candidates: reviewCandidates,
      memberPeople,
      excludePeople,
      minScore: activeReviewMoreMinScore,
    });
  }

  function reviewMoreForManagedGroup(folder: PhotoFolder) {
    const memberPeople = folder.groupProfile?.memberPeople || folder.groupPeople || [];
    const memberPets = folder.groupProfile?.memberPets || folder.groupPets || [];
    if (memberPeople.length + memberPets.length < 1) return;
    const excludePeople = folder.groupProfile?.excludePeople || folder.excludePeople || [];
    const excludePets = folder.groupProfile?.excludePets || folder.excludePets || [];
    const fallbackCandidateIds = reviewCandidatesForManagedGroup(folder).map((candidate) => candidate.candidateId);
    void openSuggestedReviewMore(
      {
        personNames: memberPeople,
        excludePeople,
        memberPets,
        excludePets,
        statuses: ["pending", "uncertain"],
        minScore: activeReviewMoreMinScore,
      },
      `${folder.name} ${uiText("Review More")}`,
      "group",
      fallbackCandidateIds
    );
  }

