  function rootRepairKey(rootPath: string) {
    return sourceFolderKey(rootPath);
  }

  function setPhotoRootRepairState(rootPath: string, patch: Partial<PhotoRootRepairState>) {
    const key = rootRepairKey(rootPath);
    if (!key) return;
    setPhotoRootRepairStates((current) => ({
      ...current,
      [key]: {
        ...(current[key] || {}),
        ...patch,
      },
    }));
  }

  function setPhotoRootBusy(rootPath: string, busyAction: PhotoRootRepairAction | "") {
    setPhotoRootRepairState(rootPath, { busyAction, error: busyAction ? "" : undefined });
  }

  async function runManagedRootBackupCheck(rootPath: string, rootName: string) {
    const cleanRoot = String(rootPath || "").trim();
    if (!cleanRoot) return;
    setPhotoRootBusy(cleanRoot, "backup");
    try {
      const result = await photoLibraryBackupCheck({ sampleLimit: 8, libraryRoot: cleanRoot });
      const value = result.value || null;
      const counts = value?.counts || {};
      setPhotoRootRepairState(cleanRoot, {
        busyAction: "",
        backupCheck: value,
        message: `${uiText("Checked")} ${rootName || fileName(cleanRoot) || uiText("root")}: ${formatCount(Number(counts.assets || 0))} ${uiText("assets")}, ${formatCount(Number(counts.missingOriginals || 0))} ${uiText("missing originals")}.`,
        error: "",
        updatedAt: value?.generatedAt || new Date().toISOString(),
      });
      if (activeLibraryRootRef.current === cleanRoot) {
        setPhotoBackupCheck(value);
        setPhotoBackupCheckError("");
      }
      await loadPhotoRepairHistory();
    } catch (error) {
      setPhotoRootRepairState(cleanRoot, { busyAction: "", error: errorMessage(error), updatedAt: new Date().toISOString() });
    }
  }

  async function runManagedRootPreviewSweep(rootPath: string, rootName: string) {
    const cleanRoot = String(rootPath || "").trim();
    if (!cleanRoot) return;
    if (!(await confirmPhotoAction({
      title: uiText("Sweep root previews"),
      message: `${uiText("Generate missing cached previews for")} ${rootName || fileName(cleanRoot) || uiText("this root")}?`,
      confirmLabel: uiText("Sweep previews"),
      danger: false,
    }))) return;
    setPhotoRootBusy(cleanRoot, "previewSweep");
    try {
      const result = await photoLibraryPreviewSweep({
        missingOnly: true,
        force: false,
        limit: 1000,
        sampleLimit: 8,
        libraryRoot: cleanRoot,
      });
      const value = result.value || null;
      const counts = value?.counts || {};
      setPhotoRootRepairState(cleanRoot, {
        busyAction: "",
        previewSweep: value,
        message: `${uiText("Preview sweep")} ${rootName || fileName(cleanRoot) || uiText("root")}: ${formatCount(Number(counts.generatedPreviews || 0))} ${uiText("generated")}, ${formatCount(Number(counts.remainingMissingCachedPreviews || 0))} ${uiText("remaining")}.`,
        error: "",
        updatedAt: value?.generatedAt || new Date().toISOString(),
      });
      if (activeLibraryRootRef.current === cleanRoot) {
        const check = await photoLibraryBackupCheck({ sampleLimit: 8, libraryRoot: cleanRoot });
        setPhotoBackupCheck(check.value || null);
        setPhotoBackupCheckError("");
      }
      await loadPhotoRepairHistory();
      await loadPage(currentPageRequest({ offset: 0 }));
    } catch (error) {
      setPhotoRootRepairState(cleanRoot, { busyAction: "", error: errorMessage(error), updatedAt: new Date().toISOString() });
    }
  }

  async function runManagedRootOrphanScan(rootPath: string, rootName: string, dryRun = true) {
    const cleanRoot = String(rootPath || "").trim();
    if (!cleanRoot) return;
    setPhotoRootBusy(cleanRoot, dryRun ? "orphanPreview" : "orphanScan");
    try {
      const result = await scanPhotoRecoveredOrphans({
        roots: [cleanRoot],
        libraryRoot: cleanRoot,
        limit: 500,
        dryRun,
      });
      const value = result.value || null;
      setPhotoRootRepairState(cleanRoot, {
        busyAction: "",
        orphanScan: value,
        message: dryRun
          ? `${uiText("Orphan preview")} ${rootName || fileName(cleanRoot) || uiText("root")}: ${formatCount(Number(value?.orphanCandidates || 0))} ${uiText("candidate(s)")}.`
          : `${uiText("Orphan scan")} ${rootName || fileName(cleanRoot) || uiText("root")}: ${formatCount(Number(value?.recorded || 0))} ${uiText("recorded")}.`,
        error: "",
        updatedAt: value?.generatedAt || new Date().toISOString(),
      });
      if (!dryRun) {
        await loadRecoveredFailures();
        await loadFolders();
      }
      await loadPhotoRepairHistory();
    } catch (error) {
      setPhotoRootRepairState(cleanRoot, { busyAction: "", error: errorMessage(error), updatedAt: new Date().toISOString() });
    }
  }

  async function previewPhotoCatalogCleanup() {
    setPhotoCatalogCleanupPreviewing(true);
    setPhotoRepairError("");
    try {
      const cleanup = (await photoLibraryCatalogCleanup({ apply: false, sampleLimit: 8 })).value;
      setPhotoCatalogCleanupPreview(cleanup || null);
      const candidates = Number(cleanup?.counts?.cleanupCandidates || 0);
      setPhotoRepairStatus(candidates > 0
        ? `${uiText("Cleanup preview found")} ${formatCount(candidates)} ${uiText("catalog row")}${candidates === 1 ? "" : "s"}.`
        : uiText("Cleanup preview found no catalog drift."));
      await loadPhotoRepairHistory();
    } catch (error) {
      setPhotoRepairError(errorMessage(error));
    } finally {
      setPhotoCatalogCleanupPreviewing(false);
    }
  }

  async function runPhotoCatalogCleanup() {
    const libraryRoot = activeLibraryRootRef.current;
    const libraryRootProfileId = activeLibraryRootProfileIdRef.current;
    const previewCandidates = Number(photoCatalogCleanupPreview?.counts?.cleanupCandidates || 0);
    if (!photoCatalogCleanupPreview) {
      await previewPhotoCatalogCleanup();
      return;
    }
    if (previewCandidates <= 0) {
      setPhotoRepairStatus(uiText("Cleanup preview found no catalog drift."));
      return;
    }
    if (!(await confirmPhotoAction({
      title: uiText("Clean catalog"),
      message: `${uiText("Remove broken album, search, cover, and metadata rows that point at missing catalog records? Originals and valid photos will not be changed.")} ${formatCount(previewCandidates)} ${uiText("candidate row(s) will be checked.")}`,
      confirmLabel: uiText("Clean catalog"),
      danger: false,
    }))) return;
    setPhotoCatalogCleaning(true);
    setPhotoRepairError("");
    try {
      const cleanup = (await photoLibraryCatalogCleanup({ apply: true, sampleLimit: 8 })).value;
      const cleaned = Number(cleanup?.counts?.cleanedRows || 0);
      const remaining = Number(cleanup?.counts?.remainingCandidates || 0);
      setPhotoCatalogCleanupPreview(cleanup || null);
      const check = await photoLibraryBackupCheck({ sampleLimit: 8, libraryRoot, libraryRootProfileId });
      setPhotoBackupCheck(check.value || null);
      setPhotoBackupCheckError("");
      setPhotoRepairStatus(remaining > 0
        ? `${uiText("Cleaned")} ${formatCount(cleaned)} ${uiText("catalog row")}${cleaned === 1 ? "" : "s"}; ${formatCount(remaining)} ${uiText("remain")}.`
        : `${uiText("Cleaned")} ${formatCount(cleaned)} ${uiText("catalog row")}${cleaned === 1 ? "" : "s"}.`);
      await loadPhotoRepairHistory();
    } catch (error) {
      setPhotoRepairError(errorMessage(error));
    } finally {
      setPhotoCatalogCleaning(false);
    }
  }

  async function runPhotoRestoreRehearsal() {
    setPhotoRestoreRehearsing(true);
    setPhotoRestoreRehearsalError("");
    try {
      const result = await photoRestoreRehearsal({ limit: 6 });
      setPhotoRestoreRehearsalValue(result.value || null);
      await loadPhotoRepairHistory();
      return result.value || null;
    } catch (error) {
      setPhotoRestoreRehearsalError(errorMessage(error));
      return null;
    } finally {
      setPhotoRestoreRehearsing(false);
    }
  }

  async function runPhotoBackupRestoreRehearsal(createBackup = true, scheduled = false) {
    setPhotoBackupRestoreRehearsing(true);
    setPhotoBackupRestoreRehearsalError("");
    try {
      const result = await props.photoBackupRestoreRehearsal({
        sampleLimit: 8,
        createBackup,
        includeGenerated: Boolean(photoLibraryProfile?.backupPolicy?.includeGenerated),
        scheduled,
        recordPolicy: true,
      });
      const value = result.value || null;
      setPhotoBackupRestoreRehearsalValue(value);
      if (value?.policyStatus) {
        setPhotoLibraryProfile((current) => current ? {
          ...current,
          backupPolicy: value.policyStatus?.policy || current.backupPolicy,
          backupPolicyStatus: value.policyStatus,
        } : current);
      }
      await loadPhotoRepairHistory();
      return value;
    } catch (error) {
      setPhotoBackupRestoreRehearsalError(errorMessage(error));
      return null;
    } finally {
      setPhotoBackupRestoreRehearsing(false);
    }
  }

  async function runPhotoRepairScan() {
    const libraryRoot = activeLibraryRootRef.current;
    const libraryRootProfileId = activeLibraryRootProfileIdRef.current;
    setPhotoRepairScanning(true);
    setPhotoRepairError("");
    setPhotoRepairStatus("");
    try {
      const [backupResult, recoveredResult, restoreResult, backupRestoreResult] = await Promise.all([
        photoLibraryBackupCheck({ sampleLimit: 8, libraryRoot, libraryRootProfileId }),
        props.listPhotoImportFailures({ limit: 100, libraryRoot, libraryRootProfileId }),
        photoRestoreRehearsal({ limit: 6 }),
        props.photoBackupRestoreRehearsal({
          sampleLimit: 8,
          createBackup: false,
          includeGenerated: Boolean(photoLibraryProfile?.backupPolicy?.includeGenerated),
          recordPolicy: true,
        }),
      ]);
      const backup = backupResult.value || null;
      const restore = restoreResult.value || null;
      const backupRestore = backupRestoreResult.value || null;
      const failures = recoveredResult.value?.failures || [];
      const recoveredCount = Number(recoveredResult.value?.activeTotal ?? recoveredResult.value?.total ?? failures.length) || 0;
      setPhotoBackupCheck(backup);
      setPhotoBackupCheckError("");
      setPhotoRestoreRehearsalValue(restore);
      setPhotoRestoreRehearsalError("");
      setPhotoBackupRestoreRehearsalValue(backupRestore);
      setPhotoBackupRestoreRehearsalError("");
      if (backupRestore?.policyStatus) {
        setPhotoLibraryProfile((current) => current ? {
          ...current,
          backupPolicy: backupRestore.policyStatus?.policy || current.backupPolicy,
          backupPolicyStatus: backupRestore.policyStatus,
        } : current);
      }
      setRecoveredFailures(failures);
      setRecoveredFailuresError("");
      setPhotoRepairRecoveredCount(recoveredCount);
      const issues = buildPhotoRepairIssues({
        backupCheck: backup,
        restoreRehearsal: restore,
        backupRestoreRehearsal: backupRestore,
        recoveredCount,
        visiblePhotoCount: items.length,
      });
      setPhotoRepairStatus(issues.length
        ? `${formatCount(issues.length)} repair issue${issues.length === 1 ? "" : "s"} found.`
        : uiText("No repair issues found."));
      await loadPhotoRepairHistory();
    } catch (error) {
      setPhotoRepairError(errorMessage(error));
    } finally {
      setPhotoRepairScanning(false);
    }
  }

