  async function permanentlyDeletePhoto(item: PhotoItem) {
    if (!item.deletedAt) return;
    const payload = photoInfoPermanentDeletePayload([item.sourcePath]);
    if (!payload) return;
    if (!await confirmPhotoAction({
      title: uiText("Delete permanently"),
      message: uiText("Permanently remove this photo from the local Photos catalog? Managed-library originals move to app trash; referenced originals stay on disk."),
      confirmLabel: uiText("Delete permanently"),
    })) return;
    setSavingMetadata(true);
    setMetadataError("");
    try {
      await permanentlyDeletePhotos(payload);
      await refreshAfterVisibilityChange();
    } catch (error) {
      setMetadataError(error instanceof Error ? error.message : String(error));
    } finally {
      setSavingMetadata(false);
    }
  }

  async function mergeDuplicateGroup(item: PhotoItem, keepAssetId?: string) {
    const groupId = item.duplicateGroup?.groupId || "";
    if (!groupId) return;
    if (item.duplicateGroup?.algorithm === "perceptual_dhash" && !await confirmPhotoAction({
      title: uiText("Merge near duplicates"),
      message: uiText("These photos are visually similar, not byte-identical. Move the non-kept items to Recently Deleted?"),
      confirmLabel: uiText("Merge near duplicates"),
      danger: false,
    })) return;
    setSavingMetadata(true);
    setMetadataError("");
    try {
      await mergePhotoDuplicates({
        groupId,
        keepAssetId: keepAssetId ?? item.assetId ?? "",
      });
      await refreshAfterVisibilityChange();
    } catch (error) {
      setMetadataError(error instanceof Error ? error.message : String(error));
    } finally {
      setSavingMetadata(false);
    }
  }

  async function dismissDuplicateGroup(item: PhotoItem) {
    const groupId = item.duplicateGroup?.groupId || "";
    if (!groupId) return;
    if (!await confirmPhotoAction({
      title: uiText("Dismiss duplicate group"),
      message: item.duplicateGroup?.algorithm === "perceptual_dhash"
        ? uiText("Stop showing this near-duplicate group? The photos stay in your library.")
        : uiText("Stop showing this duplicate group? The photos stay in your library."),
      confirmLabel: uiText("Dismiss group"),
      danger: false,
    })) return;
    setSavingMetadata(true);
    setMetadataError("");
    try {
      await dismissPhotoDuplicateGroup({ groupId });
      await refreshAfterVisibilityChange();
    } catch (error) {
      setMetadataError(error instanceof Error ? error.message : String(error));
    } finally {
      setSavingMetadata(false);
    }
  }

