  function patchReverseGeocodeItems(rows: Array<Partial<PhotoItem> & Record<string, unknown>> | undefined) {
    photoReverseGeocodeMetadataPatches(rows).forEach(({ sourcePath, patch }) => patchItemMetadata(sourcePath, patch));
  }

