  async function reverseGeocodePhotoLocationSettled(params: Record<string, unknown>) {
    return photoReverseGeocodeSettledResult({
      params,
      reverseGeocodePhotoLocation,
      pendingMessage: uiText("Place lookup is still running."),
      wait: (delayMs) => new Promise((resolve) => window.setTimeout(resolve, delayMs)),
    });
  }

  async function lookupLightboxPlaceName(item: PhotoItem, apply = false) {
    const coordinates = lightboxLookupCoordinates(item);
    setReverseGeocodeScope("lightbox");
    setReverseGeocodeResult(null);
    setReverseGeocodeError("");
    if (photoSettings.noNetworkIntelligence) {
      setReverseGeocodeError(uiText("Network lookups disabled"));
      return;
    }
    if (!coordinates) {
      setReverseGeocodeError(uiText("Add latitude and longitude first."));
      return;
    }
    setReverseGeocodeLoading(true);
    try {
      const payload = photoReverseGeocodeLocationPayload({
        sourcePath: item.sourcePath,
        assetId: item.assetId,
        latitude: coordinates.latitude,
        longitude: coordinates.longitude,
        apply,
      });
      if (!payload) {
        setReverseGeocodeError(uiText("Add latitude and longitude first."));
        return;
      }
      const value = await reverseGeocodePhotoLocationSettled(payload);
      setReverseGeocodeResult(value);
      if (!value.ok) {
        setReverseGeocodeError(value.message || uiText("Place lookup failed."));
        return;
      }
      if (apply) {
        patchReverseGeocodeItems(value.items);
        const appliedDraft = photoReverseGeocodeAppliedLocationDraft(value, coordinates);
        setLocationLabelDraft(appliedDraft.label);
        setLocationLatitudeDraft(appliedDraft.latitude);
        setLocationLongitudeDraft(appliedDraft.longitude);
        setLocationHiddenDraft(appliedDraft.locationHidden);
        await loadPhotoOperations();
        await loadFolders();
      }
    } catch (error) {
      setReverseGeocodeError(errorMessage(error));
    } finally {
      setReverseGeocodeLoading(false);
    }
  }

  async function lookupActivePlaceName(apply = false) {
    if (!activePlace?.place) return;
    const placeLookup = photoReverseGeocodePlaceLookupState(activePlace.place);
    const { latitude, longitude, assetIds } = placeLookup;
    setReverseGeocodeScope("place");
    setReverseGeocodeResult(null);
    setReverseGeocodeError("");
    if (photoSettings.noNetworkIntelligence) {
      setReverseGeocodeError(uiText("Network lookups disabled"));
      return;
    }
    if (latitude === null || longitude === null) {
      setReverseGeocodeError(uiText("No coordinates available."));
      return;
    }
    if (apply && !assetIds.length) {
      setReverseGeocodeError(uiText("No photos to update."));
      return;
    }
    setReverseGeocodeLoading(true);
    try {
      const payload = photoReverseGeocodeLocationPayload({
        latitude,
        longitude,
        assetIds,
        apply,
      });
      if (!payload) {
        setReverseGeocodeError(uiText("No coordinates available."));
        return;
      }
      const value = await reverseGeocodePhotoLocationSettled(payload);
      setReverseGeocodeResult(value);
      if (!value.ok) {
        setReverseGeocodeError(value.message || uiText("Place lookup failed."));
        return;
      }
      if (apply) {
        patchReverseGeocodeItems(value.items);
        await loadPhotoOperations();
        await loadFolders();
        await loadPage(currentPageRequest({ offset: 0 }));
      }
    } catch (error) {
      setReverseGeocodeError(errorMessage(error));
    } finally {
      setReverseGeocodeLoading(false);
    }
  }

  async function saveLightboxInfo(item: PhotoItem) {
    const nextOriginalCaptureDate = composePhotoDateTimeOverride(originalDateDraft, originalTimeDraft, originalTimezoneDraft);
    const nextDateOverride = composePhotoDateTimeOverride(dateDraft, timeDraft, timezoneDraft);
    const originalDateChanged = nextOriginalCaptureDate !== normalizePhotoDateTimeOverride(item.originalCaptureDate || "");
    const dateChanged = nextDateOverride !== normalizePhotoDateTimeOverride(item.dateOverride || "");
    const locationDraft: PhotoInfoLocationDraft = {
      label: locationLabelDraft,
      latitude: locationLatitudeDraft,
      longitude: locationLongitudeDraft,
      hidden: locationHiddenDraft,
    };
    const locationChanged = photoInfoLocationDraftChanged(item, locationDraft);
    const patch = photoInfoMetadataPatchFromDraft({
      title: titleDraft,
      caption: captionDraft,
      accessibilityDescription: accessibleDescriptionDraft,
      descriptionRegions: descriptionRegionsDraft,
      keywords: keywordsDraft,
      dateOverride: nextDateOverride,
      location: locationDraft,
      localDepthControls: {
        mode: depthModeDraft,
        aperture: depthApertureDraft,
        focusDistance: depthFocusDistanceDraft,
        effect: depthEffectDraft,
      },
      ...(originalDateChanged ? { captureDate: nextOriginalCaptureDate } : {}),
    });
    const saved = await savePhotoMetadata(item, patch);
    if (saved) {
      if (originalDateChanged) {
        applyLightboxOriginalDateDraft(photoInfoOriginalDateDraftFromItem(saved));
      }
      await loadKeywords();
      if (dateChanged || originalDateChanged || locationChanged) {
        setDateBucketRefreshToken((token) => token + 1);
        await loadFolders();
      }
    }
  }

