  async function saveSuggestion(suggestion: PhotoAlbumSuggestion) {
    const suggestionKey = suggestion.id || suggestion.name;
    if (props.busy || savingAlbum) return;
    const albumDraft = photoAlbumEditorPayloadDraft({
      name: suggestion.name,
      albumKind: "smart",
      description: suggestion.description,
      includePeople: suggestion.includePeople,
      excludePeople: suggestion.excludePeople,
      rules: suggestion.rules,
      coverSourcePath: "",
    });
    if (!albumDraft) return;
    setSavingAlbum(true);
    setSavingSuggestionId(suggestionKey);
    setAlbumError("");
    try {
      const result = await savePhotoAlbum(albumDraft);
      const value = result.value && typeof result.value === "object" ? result.value as { albumId?: unknown } : {};
      await loadFolders({ railMode: "full" });
      await loadSuggestions();
      if (value.albumId) setActiveId(`album:${String(value.albumId)}`);
      notifyToast({ tone: "ok", message: `${uiText("Created album")} "${albumDraft.name}".` });
    } catch (error) {
      setAlbumError(error instanceof Error ? error.message : String(error));
    } finally {
      setSavingAlbum(false);
      setSavingSuggestionId((current) => (current === suggestionKey ? "" : current));
    }
  }

