  function openVisualLookupRelatedPhoto(item: PhotoItem) {
    const index = items.findIndex((candidate) => candidate.sourcePath === item.sourcePath);
    if (index < 0) return;
    setLightboxBurstOverrideSource("");
    setLightbox(index);
  }

  function copyVisualLookupLabel(row: PhotoObjectTagReviewRow) {
    copyText(row.label, "Detected item label");
  }

  function copyPhotoUtilityMatch(match: NonNullable<PhotoItem["utilityMatch"]>) {
    copyText(match.value || match.term, `${match.classifierName || "Utility"} match`);
  }

  function renderSearchHighlight(value: unknown) {
    return buildPhotoSearchHighlightParts(value, searchQuery).map((part, index) => (
      part.match
        ? <mark key={`${index}:${part.text}`} className="photo-search-highlight">{part.text}</mark>
        : <span key={`${index}:${part.text}`}>{part.text}</span>
    ));
  }

  function togglePageSelection() {
    setSelectedSources((current) => {
      const next = new Set(current);
      if (allPageSelected) {
        items.forEach((item) => next.delete(item.sourcePath));
      } else {
        items.forEach((item) => next.add(item.sourcePath));
      }
      return next;
    });
  }

  function focusPhotoSearch() {
    if (lightbox !== null) setLightbox(null);
    window.requestAnimationFrame(() => {
      searchInputRef.current?.focus();
      searchInputRef.current?.select();
    });
  }

  function openSelectedInfo() {
    pendingInfoFocusRef.current = true;
    if (lightbox !== null) {
      window.requestAnimationFrame(() => {
        if (lightboxInfoDisclosureRef.current) lightboxInfoDisclosureRef.current.open = true;
        lightboxInfoRef.current?.focus();
      });
      return;
    }
    if (selectedItems.length !== 1) return;
    const selectedIndex = items.findIndex((item) => item.sourcePath === selectedItems[0].sourcePath);
    if (selectedIndex >= 0) setLightbox(selectedIndex);
  }

  async function toggleSelectedFavorites() {
    if (props.busy || savingMetadata) return;
    if (lightItem) {
      await toggleFavorite(lightItem);
      return;
    }
    if (!selectedItems.length) return;
    const favoriteBatch = photoInfoFavoriteBatchUpdates(selectedItems);
    setSavingMetadata(true);
    setMetadataError("");
    try {
      const result = await updatePhotoAssetsMetadata({
        label: favoriteBatch.favorite ? uiText("Marked selected favorites") : uiText("Removed selected favorites"),
        items: favoriteBatch.updates,
      });
      setItems((current) => photoInfoApplyFavoriteBatchResult(current, selectedItems, result.value || {}, favoriteBatch.favorite));
      await loadFolders();
      await loadPhotoOperations();
    } catch (error) {
      setMetadataError(error instanceof Error ? error.message : String(error));
    } finally {
      setSavingMetadata(false);
    }
  }

  async function hideSelectedShortcut() {
    if (props.busy || savingMetadata || activeDeletedCollection) return;
    if (lightItem && !lightItem.deletedAt) {
      await hidePhoto(lightItem, !lightItem.hidden);
      return;
    }
    if (selectedSourcePaths.length) await updateSelectedVisibility("hide");
  }

  async function deleteSelectedShortcut() {
    if (props.busy || savingMetadata) return;
    if (lightItem) {
      if (lightItem.deletedAt) await permanentlyDeletePhoto(lightItem);
      else await deletePhoto(lightItem);
      return;
    }
    if (!selectedSourcePaths.length) return;
    if (activeDeletedCollection) await permanentlyDeleteSelected();
    else await updateSelectedVisibility("delete");
  }

  async function loadCurrentSlideshowItems(): Promise<PhotoItem[]> {
    // Keep slideshow/creation shortcuts page-bounded. Project playback can
    // fetch explicit source paths, but a generic "current view" click should
    // not materialize a 50k-photo filtered result set in the renderer.
    return items;
  }

  async function loadLibraryCreationSuggestionCandidates(): Promise<{ items: PhotoItem[]; total: number }> {
    const libraryRoot = activeLibraryRootRef.current;
    const libraryRootProfileId = activeLibraryRootProfileIdRef.current;
    const page = await itemsFnRef.current({
      folderId: "all",
      offset: 0,
      limit: PHOTO_CREATION_LIBRARY_CANDIDATE_LIMIT,
      previewBudget: 0,
      sort: "quality",
      mediaKind: "image",
      visibility: "visible",
      libraryRoot,
      libraryRootProfileId,
      detectMissingOriginals: true,
    });
    const pageItems = Array.isArray(page.items) ? page.items : [];
    return {
      items: pageItems,
      total: Math.max(pageItems.length, Number(page.total || 0)),
    };
  }

  async function refreshPhotoCreationSuggestions() {
    setCreationSuggestionLoadingScope("view");
    setCreationSuggestionError("");
    try {
      const allItems = await loadCurrentSlideshowItems();
      setCreationSuggestionItems(allItems);
      setCreationSuggestionScope("view");
      if (!buildPhotoCreationExportSuggestions(allItems, {
        favoritePeople: favoritePeopleForCreation,
        memoryContextSourcePaths: memoryContextSourcePathsForCreation,
        maxCollageItems: 6,
      }).length) {
        setCreationSuggestionError(uiText("No creation suggestions found in this view."));
      }
    } catch (error) {
      setCreationSuggestionError(error instanceof Error ? error.message : uiText("Could not load this view for suggestions."));
    } finally {
      setCreationSuggestionLoadingScope("");
    }
  }

  async function refreshPhotoLibraryCreationSuggestions() {
    const stored = readStoredPhotoCreationSuggestionCache(PHOTO_CREATION_SUGGESTIONS_CACHE_KEY, creationLibraryCacheSignature);
    const cached = photoCreationSuggestionCacheIsFresh(stored) ? stored : validCreationSuggestionLibraryCache;
    if (cached?.suggestions.length) {
      setCreationSuggestionItems([]);
      setCreationSuggestionLibraryCache(cached);
      setCreationSuggestionScope("library-cache");
      setCreationSuggestionError("");
      return;
    }
    const storedRefreshState = readStoredPhotoCreationSuggestionRefreshState(PHOTO_CREATION_SUGGESTIONS_REFRESH_KEY, creationLibraryCacheSignature) || matchingCreationSuggestionRefreshState;
    if (!photoCreationSuggestionRefreshCanRun(storedRefreshState)) {
      if (storedRefreshState) setCreationSuggestionRefreshState(storedRefreshState);
      setCreationSuggestionError(uiText("Library suggestions will retry later."));
      return;
    }
    setCreationSuggestionLoadingScope("library");
    setCreationSuggestionError("");
    try {
      const { items: candidateItems, total: candidateTotal } = await loadLibraryCreationSuggestionCandidates();
      const suggestions = buildPhotoCreationExportSuggestions(candidateItems, {
        favoritePeople: favoritePeopleForCreation,
        maxCollageItems: 6,
      });
      const cache = buildPhotoCreationSuggestionCacheRecord({
        signature: creationLibraryCacheSignature,
        sourceCount: candidateTotal,
        candidateCount: candidateItems.length,
        suggestions,
      });
      if (cache) {
        setCreationSuggestionLibraryCache(cache);
        storePhotoCreationSuggestionCache(PHOTO_CREATION_SUGGESTIONS_CACHE_KEY, cache);
      }
      setCreationSuggestionItems([]);
      setCreationSuggestionScope(cache?.suggestions.length ? "library-cache" : "loaded");
      const successState = buildPhotoCreationSuggestionRefreshSuccessState({
        signature: creationLibraryCacheSignature,
        previous: matchingCreationSuggestionRefreshState,
      });
      setCreationSuggestionRefreshState(successState);
      storePhotoCreationSuggestionRefreshState(PHOTO_CREATION_SUGGESTIONS_REFRESH_KEY, successState);
      if (!suggestions.length) {
        setCreationSuggestionError(uiText("No creation suggestions found in the library."));
      }
    } catch (error) {
      const failureState = buildPhotoCreationSuggestionRefreshFailureState({
        signature: creationLibraryCacheSignature,
        previous: matchingCreationSuggestionRefreshState,
        error: error instanceof Error ? error.message : error,
      });
      setCreationSuggestionRefreshState(failureState);
      storePhotoCreationSuggestionRefreshState(PHOTO_CREATION_SUGGESTIONS_REFRESH_KEY, failureState);
      setCreationSuggestionError(error instanceof Error ? error.message : uiText("Could not load the library for suggestions."));
    } finally {
      setCreationSuggestionLoadingScope("");
    }
  }

  async function loadPhotoSlideshowProjectItems(project: PhotoSlideshowProject): Promise<PhotoItem[]> {
    const sourcePaths = project.sourcePaths || [];
    if (!sourcePaths.length) return [];
    const bySource = new Map<string, PhotoItem>();
    items.forEach((item) => {
      if (sourcePaths.includes(item.sourcePath)) bySource.set(item.sourcePath, item);
    });
    if (bySource.size < sourcePaths.length) {
      const page = await itemsFnRef.current({
        folderId: "all",
        offset: 0,
        limit: Math.min(500, Math.max(1, sourcePaths.length)),
        previewBudget: 0,
        sort: "filename",
        sourcePaths,
        libraryRoot: activeLibraryRootRef.current,
        libraryRootProfileId: activeLibraryRootProfileIdRef.current,
        detectMissingOriginals: true,
      });
      (page.items || []).forEach((item) => {
        if (sourcePaths.includes(item.sourcePath)) bySource.set(item.sourcePath, item);
      });
    }
    return sourcePaths.map((sourcePath) => bySource.get(sourcePath)).filter((item): item is PhotoItem => Boolean(item));
  }

  async function startPhotoSlideshow(preferredSourcePath = "", project?: PhotoSlideshowProject) {
    setSlideshowLoading(true);
    setSlideshowError("");
    try {
      const queueSourceItems = project ? await loadPhotoSlideshowProjectItems(project) : selectedSources.size ? items : await loadCurrentSlideshowItems();
      const queueSources = project ? new Set(project.sourcePaths) : selectedSources;
      const queue = buildPhotoSlideshowQueue(queueSourceItems, queueSources, preferredSourcePath || currentLightboxSource || project?.sourcePaths[0] || "");
      if (!queue.items.length) {
        setSlideshowError(uiText("No playable photos in this view."));
        return;
      }
      const memoryPlayback = !project && !selectedSources.size && active?.kind === "memory" ? active : null;
      const playbackSource = project ? "project" : memoryPlayback ? "memory" : queue.source;
      const playbackIntervalMs = project?.intervalMs || slideshowIntervalMs;
      const playbackTheme = project?.theme || photoSlideshowProjectTheme;
      const playbackThemeTimelinePreset = project?.themeTimelinePreset || photoSlideshowProjectThemeTimelinePreset;
      const playbackThemeTemplateName = project?.themeTemplateName || photoSlideshowProjectThemeTemplateName;
      const playbackThemeTemplatePalette = project?.themeTemplatePalette || photoSlideshowProjectThemeTemplatePalette;
      const playbackThemeTemplateTypography = project?.themeTemplateTypography || photoSlideshowProjectThemeTemplateTypography;
      const playbackThemeTemplateBackdrop = project?.themeTemplateBackdrop || photoSlideshowProjectThemeTemplateBackdrop;
      const playbackThemeTemplateLayout = project?.themeTemplateLayout || photoSlideshowProjectThemeTemplateLayout;
      const playbackThemeTemplateBackdropIntensity = project?.themeTemplateBackdropIntensity ?? photoSlideshowProjectThemeTemplateBackdropIntensity;
      const playbackThemeTemplateStageWidth = project?.themeTemplateStageWidth ?? photoSlideshowProjectThemeTemplateStageWidth;
      const playbackThemeTemplateFrameStyle = project?.themeTemplateFrameStyle || photoSlideshowProjectThemeTemplateFrameStyle;
      const playbackThemeTemplateChromeDensity = project?.themeTemplateChromeDensity || photoSlideshowProjectThemeTemplateChromeDensity;
      const playbackThemeTemplateCaptionPreset = project?.themeTemplateCaptionPreset || photoSlideshowProjectThemeTemplateCaptionPreset;
      const nextTransitionEffect = project?.transitionEffect || photoSlideshowProjectTransitionEffect;
      const nextTransitionDurationMs = nextTransitionEffect === "cut" ? 0 : Math.max(0, Math.min(3000, project?.transitionDurationMs ?? photoSlideshowProjectTransitionDurationMs));
      const rawPlaybackTimelineItems = project?.timelineItems || cleanPhotoSlideshowTimelineItems(photoSlideshowProjectTimelineItems, queue.items.map((item) => item.sourcePath), playbackIntervalMs);
      const playbackTimelineItems = buildPhotoSlideshowThemeTimeline(
        rawPlaybackTimelineItems,
        queue.items.map((item) => item.sourcePath),
        playbackIntervalMs,
        playbackTheme,
        nextTransitionEffect,
        nextTransitionDurationMs,
        playbackThemeTimelinePreset,
      );
      const playbackChapters = memoryPlayback && queue.items.length > 1
        ? buildPhotoSlideshowChapters(queue.items, playbackTimelineItems, playbackIntervalMs, itemLabel)
        : [];
      if (project) {
        setSlideshowIntervalMs(project.intervalMs);
        setSlideshowFitMode(project.fitMode);
      }
      const nextMusic = project?.music || photoSlideshowProjectMusic;
      const nextAudioPath = nextMusic === "custom" ? project?.musicPath || photoSlideshowProjectMusicPath : "";
      const nextAudioVolume = Math.max(0, Math.min(1, project?.audioVolume ?? photoSlideshowProjectAudioVolume / 100));
      const nextAudioStartMs = Math.max(0, Math.min(3_600_000, project?.audioStartMs ?? photoSlideshowProjectAudioStartMs));
      const rawAudioEndMs = Math.max(0, Math.min(3_600_000, project?.audioEndMs ?? photoSlideshowProjectAudioEndMs));
      const nextAudioEndMs = rawAudioEndMs > nextAudioStartMs ? rawAudioEndMs : 0;
      const queueSourcePaths = queue.items.map((item) => item.sourcePath);
      const queueSourceSet = new Set(queueSourcePaths);
      const rawAudioPlacementStartSourcePath = String(project?.audioPlacementStartSourcePath ?? photoSlideshowProjectAudioPlacementStartSourcePath).trim();
      const rawAudioPlacementEndSourcePath = String(project?.audioPlacementEndSourcePath ?? photoSlideshowProjectAudioPlacementEndSourcePath).trim();
      const nextAudioPlacementStartSourcePath = queueSourceSet.has(rawAudioPlacementStartSourcePath) ? rawAudioPlacementStartSourcePath : "";
      let nextAudioPlacementEndSourcePath = queueSourceSet.has(rawAudioPlacementEndSourcePath) ? rawAudioPlacementEndSourcePath : "";
      if (nextAudioPlacementStartSourcePath && nextAudioPlacementEndSourcePath) {
        const startIndex = queueSourcePaths.indexOf(nextAudioPlacementStartSourcePath);
        const endIndex = queueSourcePaths.indexOf(nextAudioPlacementEndSourcePath);
        if (startIndex >= 0 && endIndex >= 0 && endIndex < startIndex) {
          nextAudioPlacementEndSourcePath = nextAudioPlacementStartSourcePath;
        }
      }
      let nextAudioUrl = "";
      if (nextAudioPath) {
        const prepared = await props.prepareImportPaths([nextAudioPath]);
        const matched = prepared.find((item) => item.path === nextAudioPath) || prepared[0];
        nextAudioUrl = matched?.url || "";
      }
      setSlideshowItems(queue.items);
      setSlideshowIndex(queue.startIndex);
      setSlideshowTransitionSourceIndex(queue.startIndex);
      setSlideshowSource(playbackSource);
      setSlideshowPlaybackTitle(project?.title || photoSlideshowProjectTitle.trim() || memoryPlayback?.memory?.name || memoryPlayback?.name || "");
      setSlideshowPlaybackTheme(playbackTheme);
      setSlideshowPlaybackThemeTimelinePreset(playbackThemeTimelinePreset);
      setSlideshowPlaybackThemeTemplateName(playbackThemeTemplateName);
      setSlideshowPlaybackThemeTemplatePalette(playbackThemeTemplatePalette);
      setSlideshowPlaybackThemeTemplateTypography(playbackThemeTemplateTypography);
      setSlideshowPlaybackThemeTemplateBackdrop(playbackThemeTemplateBackdrop);
      setSlideshowPlaybackThemeTemplateLayout(playbackThemeTemplateLayout);
      setSlideshowPlaybackThemeTemplateBackdropIntensity(playbackThemeTemplateBackdropIntensity);
      setSlideshowPlaybackThemeTemplateStageWidth(playbackThemeTemplateStageWidth);
      setSlideshowPlaybackThemeTemplateFrameStyle(playbackThemeTemplateFrameStyle);
      setSlideshowPlaybackThemeTemplateChromeDensity(playbackThemeTemplateChromeDensity);
      setSlideshowPlaybackThemeTemplateCaptionPreset(playbackThemeTemplateCaptionPreset);
      setSlideshowPlaybackMusic(nextAudioPath && nextAudioUrl ? "custom" : nextMusic === "custom" ? "none" : nextMusic);
      setSlideshowPlaybackAudioPath(nextAudioPath && nextAudioUrl ? nextAudioPath : "");
      setSlideshowPlaybackAudioUrl(nextAudioUrl);
      setSlideshowPlaybackAudioVolume(nextAudioVolume);
      setSlideshowPlaybackAudioStartMs(nextAudioStartMs);
      setSlideshowPlaybackAudioEndMs(nextAudioEndMs);
      setSlideshowPlaybackAudioPlacementStartSourcePath(nextAudioPlacementStartSourcePath);
      setSlideshowPlaybackAudioPlacementEndSourcePath(nextAudioPlacementEndSourcePath);
      setSlideshowPlaybackTimelineItems(playbackTimelineItems);
      setSlideshowPlaybackTransitionEffect(nextTransitionEffect);
      setSlideshowPlaybackTransitionDurationMs(nextTransitionDurationMs);
      setSlideshowPlaybackSourceLabel(project?.sourceLabel || (playbackSource === "selection" ? uiText("Selection") : memoryPlayback?.name || active?.name || uiText("Current view")));
      setSlideshowPlaybackChapters(playbackChapters);
      setSlideshowAudioMuted(false);
      setSlideshowPlaying(true);
      setLightbox(null);
    } catch (error) {
      setSlideshowError(error instanceof Error ? error.message : String(error));
    } finally {
      setSlideshowLoading(false);
    }
  }

  function closePhotoSlideshow() {
    setSlideshowPlaying(false);
    setSlideshowItems([]);
    setSlideshowIndex(0);
    setSlideshowTransitionSourceIndex(0);
    setSlideshowPlaybackTitle("");
    setSlideshowPlaybackSourceLabel("");
    setSlideshowPlaybackThemeTemplateName("");
    setSlideshowPlaybackThemeTemplatePalette("auto");
    setSlideshowPlaybackThemeTemplateTypography("auto");
    setSlideshowPlaybackThemeTemplateBackdrop("auto");
    setSlideshowPlaybackThemeTemplateLayout("auto");
    setSlideshowPlaybackThemeTemplateBackdropIntensity(100);
    setSlideshowPlaybackThemeTemplateStageWidth(100);
    setSlideshowPlaybackThemeTemplateFrameStyle("auto");
    setSlideshowPlaybackThemeTemplateChromeDensity("auto");
    setSlideshowPlaybackThemeTemplateCaptionPreset("auto");
    setSlideshowPlaybackAudioPath("");
    setSlideshowPlaybackAudioUrl("");
    setSlideshowPlaybackAudioVolume(1);
    setSlideshowPlaybackAudioStartMs(0);
    setSlideshowPlaybackAudioEndMs(0);
    setSlideshowPlaybackAudioPlacementStartSourcePath("");
    setSlideshowPlaybackAudioPlacementEndSourcePath("");
    setSlideshowPlaybackTimelineItems([]);
    setSlideshowPlaybackTransitionEffect("auto");
    setSlideshowPlaybackTransitionDurationMs(650);
    setSlideshowPlaybackChapters([]);
    setSlideshowAudioMuted(false);
  }

  function stepPhotoSlideshow(direction: "next" | "previous") {
    setSlideshowIndex((index) => {
      setSlideshowTransitionSourceIndex(index);
      return nextPhotoSlideshowIndex(index, slideshowItems.length, direction);
    });
  }

  function jumpPhotoSlideshowChapter(chapter: PhotoSlideshowChapter) {
    setSlideshowTransitionSourceIndex(slideshowIndex);
    setSlideshowIndex(Math.max(0, Math.min(slideshowItems.length - 1, chapter.startIndex)));
    setSlideshowPlaying(true);
  }

  useEffect(() => {
    if (!slideshowItems.length || !slideshowPlaying) return;
    const sourcePath = slideshowItems[slideshowIndex]?.sourcePath || "";
    const timelineItem = slideshowPlaybackTimelineItems.find((item) => item.sourcePath === sourcePath);
    const delay = Math.max(500, Math.min(60000, timelineItem?.durationMs || slideshowIntervalMs));
    const timer = window.setTimeout(() => {
      setSlideshowIndex((index) => {
        setSlideshowTransitionSourceIndex(index);
        return nextPhotoSlideshowIndex(index, slideshowItems.length, "next");
      });
    }, delay);
    return () => window.clearTimeout(timer);
  }, [slideshowIndex, slideshowIntervalMs, slideshowItems, slideshowPlaybackTimelineItems, slideshowPlaying]);

  useEffect(() => {
    function stopSlideshowAudio() {
      const current = slideshowAudioRef.current;
      slideshowAudioRef.current = null;
      if (!current) return;
      try {
        current.gain.gain.cancelScheduledValues(current.context.currentTime);
        current.gain.gain.setTargetAtTime(0, current.context.currentTime, 0.02);
      } catch {
        // Best effort fade-out before closing the generated local music context.
      }
      try {
        current.oscillator.stop(current.context.currentTime + 0.04);
      } catch {
        // The oscillator may already be stopped when React cleans up effects.
      }
      window.setTimeout(() => {
        void current.context.close().catch(() => undefined);
      }, 80);
    }

    stopSlideshowAudio();
    if (!slideshowItems.length || !slideshowPlaying || slideshowAudioMuted || !slideshowAudioPlacementActive || slideshowMusicFrequency <= 0) return stopSlideshowAudio;
    const AudioContextConstructor = window.AudioContext || (window as Window & { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!AudioContextConstructor) return stopSlideshowAudio;
    try {
      const context = new AudioContextConstructor();
      const oscillator = context.createOscillator();
      const gain = context.createGain();
      oscillator.type = slideshowPlaybackMusic === "cinematic" ? "triangle" : "sine";
      oscillator.frequency.setValueAtTime(slideshowMusicFrequency, context.currentTime);
      gain.gain.setValueAtTime(0.043 * slideshowPlaybackAudioVolume, context.currentTime);
      oscillator.connect(gain);
      gain.connect(context.destination);
      oscillator.start();
      slideshowAudioRef.current = { context, oscillator, gain };
      void context.resume().catch(() => undefined);
    } catch {
      slideshowAudioRef.current = null;
    }
    return stopSlideshowAudio;
  }, [slideshowAudioMuted, slideshowAudioPlacementActive, slideshowItems.length, slideshowMusicFrequency, slideshowPlaybackAudioVolume, slideshowPlaybackMusic, slideshowPlaying]);

  useEffect(() => {
    const audio = slideshowCustomAudioRef.current;
    if (!audio) return;
    const startSeconds = Math.max(0, slideshowPlaybackAudioStartMs / 1000);
    const endSeconds = slideshowPlaybackAudioEndMs > slideshowPlaybackAudioStartMs ? slideshowPlaybackAudioEndMs / 1000 : 0;
    const hasTrimEnd = endSeconds > startSeconds;
    const primeAudio = () => {
      if (audio.currentTime < startSeconds || (hasTrimEnd && audio.currentTime >= endSeconds)) {
        audio.currentTime = startSeconds;
      }
    };
    const onTimeUpdate = () => {
      if (!slideshowPlaying || !hasTrimEnd || audio.currentTime < endSeconds) return;
      audio.currentTime = startSeconds;
      void audio.play().catch(() => undefined);
    };
    audio.muted = slideshowAudioMuted;
    audio.loop = !hasTrimEnd;
    audio.volume = slideshowPlaybackAudioVolume;
    audio.addEventListener("timeupdate", onTimeUpdate);
    if (!slideshowItems.length || slideshowPlaybackMusic !== "custom" || !slideshowPlaybackAudioUrl || !slideshowAudioPlacementActive) {
      audio.pause();
      if (!slideshowAudioPlacementActive) {
        return () => audio.removeEventListener("timeupdate", onTimeUpdate);
      }
      audio.currentTime = startSeconds;
      return () => audio.removeEventListener("timeupdate", onTimeUpdate);
    }
    if (slideshowPlaying) {
      primeAudio();
      void audio.play().catch(() => undefined);
    } else {
      audio.pause();
    }
    return () => audio.removeEventListener("timeupdate", onTimeUpdate);
  }, [slideshowAudioMuted, slideshowAudioPlacementActive, slideshowItems.length, slideshowPlaybackAudioEndMs, slideshowPlaybackAudioStartMs, slideshowPlaybackAudioUrl, slideshowPlaybackAudioVolume, slideshowPlaybackMusic, slideshowPlaying]);

  useEffect(() => {
    if (!slideshowItems.length) return;
    const onKey = (event: KeyboardEvent) => {
      if (event.defaultPrevented) return;
      if (event.key === "Escape") {
        event.preventDefault();
        closePhotoSlideshow();
        return;
      }
      if (isPhotoShortcutTypingTarget(event.target)) return;
      if (event.key === " " || event.code === "Space") {
        event.preventDefault();
        setSlideshowPlaying((playing) => !playing);
      } else if (event.key === "ArrowRight") {
        event.preventDefault();
        stepPhotoSlideshow("next");
      } else if (event.key === "ArrowLeft") {
        event.preventDefault();
        stepPhotoSlideshow("previous");
      } else if (event.key.toLowerCase() === "f") {
        event.preventDefault();
        setSlideshowFitMode((mode) => mode === "fit" ? "fill" : "fit");
      } else if (event.key.toLowerCase() === "m" && slideshowPlaybackMusic !== "none") {
        event.preventDefault();
        setSlideshowAudioMuted((muted) => !muted);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [slideshowItems.length, slideshowPlaybackMusic]);

  function runPhotoShortcut(shortcut: PhotoKeyboardShortcut, source: "keyboard" | "app-command" = "keyboard"): boolean {
    if (source === "app-command" && shortcut !== "focusSearch" && isPhotoShortcutTypingTarget(document.activeElement)) {
      return false;
    }
    const now = performance.now();
    const recent = recentPhotoShortcutRef.current;
    const nativeForwardedShortcut = shortcut === "selectPage" || shortcut === "delete";
    if (nativeForwardedShortcut && recent.shortcut === shortcut && now - recent.at < 180) {
      return true;
    }
    recentPhotoShortcutRef.current = { shortcut, at: now };
    if (shortcut === "toggleShortcutDiscovery") {
      setPhotoShortcutPanelOpen((open) => !open);
      return true;
    }
    if (
      shortcut === "mergeDuplicateGroups"
      && (activeId !== "duplicates" || lightbox !== null || !selectedDuplicateGroupIds.length)
    ) return false;
    if (shortcut !== "focusSearch" && props.busy) return false;
    if (shortcut === "focusSearch") focusPhotoSearch();
    else if (shortcut === "selectPage") togglePageSelection();
    else if (shortcut === "openInfo") openSelectedInfo();
    else if (shortcut === "toggleFavorite") void toggleSelectedFavorites();
    else if (shortcut === "toggleHidden") void hideSelectedShortcut();
    else if (shortcut === "delete") void deleteSelectedShortcut();
    else if (shortcut === "mergeDuplicateGroups") void mergeSelectedDuplicateGroups();
    return true;
  }

  useEffect(() => {
    const command = props.appShortcutCommand;
    if (!command?.id) return;
    runPhotoShortcut(command.shortcut, "app-command");
  }, [props.appShortcutCommand]);

  photoShortcutKeyHandlerRef.current = (event: KeyboardEvent) => {
    if (event.defaultPrevented || event.repeat) return;
    if (photoCompareOpen) {
      if (event.key === "Escape") {
        event.preventDefault();
        closePhotoCompare();
        return;
      }
      const visibleCompareItems = photoCompareItems.slice(0, photoCompareMode === "compare" ? 2 : 12);
      const activeCompareIndex = Math.max(0, visibleCompareItems.findIndex((item) => item.sourcePath === photoCompareActiveSource));
      if (["ArrowLeft", "ArrowUp", "ArrowRight", "ArrowDown"].includes(event.key) && visibleCompareItems.length > 1) {
        event.preventDefault();
        const direction = event.key === "ArrowLeft" || event.key === "ArrowUp" ? -1 : 1;
        const nextIndex = (activeCompareIndex + direction + visibleCompareItems.length) % visibleCompareItems.length;
        setPhotoCompareActiveSource(visibleCompareItems[nextIndex]?.sourcePath || "");
        return;
      }
      const compareCurationShortcut = photoCurationShortcutForKeyboardEvent(event);
      const activeCompareItem = visibleCompareItems[activeCompareIndex];
      if (compareCurationShortcut && activeCompareItem) {
        event.preventDefault();
        void applyPhotoProCuration([activeCompareItem], compareCurationShortcut);
      }
      return;
    }
    const selectedCurationShortcut = photoCurationShortcutForKeyboardEvent(event);
    if (selectedCurationShortcut && lightbox === null && selectedItems.length) {
      event.preventDefault();
      void applyPhotoProCuration(selectedItems, selectedCurationShortcut);
      return;
    }
    const shortcut = photoShortcutForKeyboardEvent(event);
    if (shortcut) {
      if (runPhotoShortcut(shortcut)) {
        event.preventDefault();
      }
      return;
    }
    const keyword = resolvePhotoKeywordShortcut(keywordOptions, event) as PhotoKeyword | null;
    if (!keyword || props.busy || savingMetadata) return;
    if (lightbox === null && !selectedItems.length) return;
    event.preventDefault();
    void applyKeywordShortcut(keyword);
  };

  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      photoShortcutKeyHandlerRef.current?.(event);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  function setLightboxZoomLevel(next: number | ((current: number) => number)) {
    setLightboxZoom((current) => clampLightboxZoom(typeof next === "function" ? next(current) : next));
  }

  function beginLightboxPinch() {
    const pinch = lightboxPinchState(lightboxGesturePoints(lightboxPointersRef.current.values()), lightboxZoom, lightboxPan);
    if (!pinch) return;
    lightboxPinchRef.current = pinch;
    lightboxDragRef.current = null;
    setLightboxDragging(false);
  }

  function resetLightboxView() {
    setLightboxZoom(1);
    setLightboxFitMode("fit");
    setLightboxPan({ x: 0, y: 0 });
    setLightboxDragging(false);
    lightboxDragRef.current = null;
    lightboxPinchRef.current = null;
    lightboxPointersRef.current.clear();
  }

  function lightboxImagePointFromClient(clientX: number, clientY: number): LightboxImageSamplePoint | null {
    const stage = lightboxStageRef.current;
    const image = lightboxImageRef.current;
    if (!stage || !image) return null;
    const mediaWidth = image.naturalWidth || Number(lightItem?.width || lightItem?.assetMetadata?.width || 0) || 0;
    const mediaHeight = image.naturalHeight || Number(lightItem?.height || lightItem?.assetMetadata?.height || 0) || 0;
    if (mediaWidth <= 0 || mediaHeight <= 0) return null;
    const rect = stage.getBoundingClientRect();
    if (rect.width <= 0 || rect.height <= 0) return null;
    return lightboxImageSamplePointFromClient({
      clientX,
      clientY,
      stageRect: rect,
      mediaSize: { width: mediaWidth, height: mediaHeight },
      pan: lightboxPan,
      zoom: lightboxZoom,
      fitMode: lightboxFitMode,
    });
  }

  // Safe Mode Stage-2: toggle the on-demand explainer. Runs the optional NudeNet/
  // Freepik detector on the revealed original and overlays the returned boxes.
  async function toggleSafetyExplain() {
    if (explainOpen) {
      setExplainOpen(false);
      return;
    }
    setExplainOpen(true);
    setExplainResult(null);
    const path = lightItem?.sourcePath;
    if (!path) return;
    setExplainLoading(true);
    try {
      const result = await window.crossAge.invoke<ExplainSafetyResult>("explain_safety", { path });
      setExplainResult(result);
    } catch {
      setExplainResult({ available: false, detections: [], reason: "Could not analyze this image." });
    } finally {
      setExplainLoading(false);
    }
  }

  // The absolutely-positioned box layer over the lightbox image. Positioned to the
  // image's rendered content rect (letterbox-aware) and given the same pan/zoom
  // transform as the <img>, so boxes track the image under zoom. See safetyOverlay.ts.
  function renderSafetyExplainOverlay() {
    if (!explainOpen || !explainResult?.available || explainResult.detections.length === 0) return null;
    const image = lightboxImageRef.current;
    const mediaWidth = image?.naturalWidth || Number(lightItem?.width || lightItem?.assetMetadata?.width || 0) || 0;
    const mediaHeight = image?.naturalHeight || Number(lightItem?.height || lightItem?.assetMetadata?.height || 0) || 0;
    if (mediaWidth <= 0 || mediaHeight <= 0) return null;
    const rect = containRenderRect({ width: mediaWidth, height: mediaHeight }, lightboxStageSize, lightboxFitMode);
    if (rect.width <= 0 || rect.height <= 0) return null;
    return (
      <div
        className="photos-explain-overlay"
        aria-hidden="true"
        style={{
          left: rect.left,
          top: rect.top,
          width: rect.width,
          height: rect.height,
          transformOrigin: "center center",
          transform: `translate3d(${lightboxPan.x}px, ${lightboxPan.y}px, 0) scale(${lightboxZoom})`,
        }}
      >
        {explainResult.detections.map((detection, index) => {
          const b = clampUnitBox(toUnitBox(detection.box));
          if (b.w <= 0 || b.h <= 0) return null;
          return (
            <div
              key={index}
              className="photos-explain-box"
              style={{ left: `${b.x * 100}%`, top: `${b.y * 100}%`, width: `${b.w * 100}%`, height: `${b.h * 100}%` }}
            >
              <span className="photos-explain-box-label">
                {formatDetectionLabel(detection.label)} · {Math.round((detection.score || 0) * 100)}%
              </span>
            </div>
          );
        })}
      </div>
    );
  }

  function lightboxImageCropPointFromClient(clientX: number, clientY: number): PhotoManualCropPoint | null {
    const image = lightboxImageRef.current;
    const point = lightboxImagePointFromClient(clientX, clientY);
    if (!image) return null;
    return photoManualCropPointFromImageSample(point, image.naturalWidth, image.naturalHeight);
  }

  function beginImageManualCropOverlayDrag(event: ReactPointerEvent<HTMLDivElement>): boolean {
    if (!imageManualCropOverlayActive) return false;
    const point = lightboxImageCropPointFromClient(event.clientX, event.clientY);
    if (!point) {
      setMetadataError(uiText("Drag directly on the photo to crop."));
      return true;
    }
    const box = normalizePhotoManualCropBox(imageManualCropBox);
    const mode = photoManualCropHitTest(box, point, 3);
    imageManualCropDragRef.current = {
      pointerId: event.pointerId,
      mode,
      start: point,
      box,
    };
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
    event.currentTarget.setPointerCapture(event.pointerId);
    setImageManualCropDragging(true);
    if (mode === "create") {
      setImageManualCropBox(photoManualCropBoxFromDrag(mode, point, point, box));
    }
    return true;
  }

  function updateImageManualCropOverlayDrag(event: ReactPointerEvent<HTMLDivElement>): boolean {
    const drag = imageManualCropDragRef.current;
    if (!drag || drag.pointerId !== event.pointerId) return false;
    const point = lightboxImageCropPointFromClient(event.clientX, event.clientY);
    if (!point) return true;
    setImageManualCropBox(photoManualCropBoxFromDrag(drag.mode, drag.start, point, drag.box));
    return true;
  }

  function endImageManualCropOverlayDrag(event: ReactPointerEvent<HTMLDivElement>): boolean {
    const drag = imageManualCropDragRef.current;
    if (!drag || drag.pointerId !== event.pointerId) return false;
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
    imageManualCropDragRef.current = null;
    setImageManualCropDragging(false);
    return true;
  }

  function beginImageMarkupStrokeDraw(event: ReactPointerEvent<HTMLDivElement>): boolean {
    if (!imageMarkupDrawingActive || imageManualCropOverlayActive || !imageMarkupOverlayActive) return false;
    const point = lightboxImageCropPointFromClient(event.clientX, event.clientY);
    if (!point) {
      setMetadataError(uiText("Draw directly on the photo."));
      return true;
    }
    const kind = imageMarkupSelectedAnnotation.kind === "signature" ? "signature" : "freehand";
    const points = [point];
    imageMarkupStrokeRef.current = {
      pointerId: event.pointerId,
      points,
      index: imageMarkupSelectedDraftIndex,
    };
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
    event.currentTarget.setPointerCapture(event.pointerId);
    setImageMarkupAnnotationsDraft((annotations) => {
      return photoImageMarkupUpdateAnnotationDraft(annotations, imageMarkupSelectedDraftIndex, { kind, points });
    });
    return true;
  }

  function updateImageMarkupStrokeDraw(event: ReactPointerEvent<HTMLDivElement>): boolean {
    const stroke = imageMarkupStrokeRef.current;
    if (!stroke || stroke.pointerId !== event.pointerId) return false;
    const point = lightboxImageCropPointFromClient(event.clientX, event.clientY);
    if (!point) return true;
    const previous = stroke.points[stroke.points.length - 1];
    if (previous && Math.hypot(previous.x - point.x, previous.y - point.y) < 0.35) return true;
    stroke.points = [...stroke.points, point].slice(-320);
    setImageMarkupAnnotationsDraft((annotations) => {
      return photoImageMarkupUpdateAnnotationDraft(annotations, stroke.index, { points: stroke.points });
    });
    return true;
  }

  function endImageMarkupStrokeDraw(event: ReactPointerEvent<HTMLDivElement>): boolean {
    const stroke = imageMarkupStrokeRef.current;
    if (!stroke || stroke.pointerId !== event.pointerId) return false;
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
    imageMarkupStrokeRef.current = null;
    return true;
  }

  function beginImageMarkupOverlayDrag(event: ReactPointerEvent<HTMLDivElement>): boolean {
    if (!imageMarkupOverlayActive) return false;
    const point = lightboxImageCropPointFromClient(event.clientX, event.clientY);
    if (!point) {
      setMetadataError(uiText("Drag directly on the photo to adjust markup."));
      return true;
    }
    const annotation = imageMarkupSelectedAnnotation;
    const mode = photoImageMarkupHitTest(annotation, point, 3);
    if (!mode) return false;
    imageMarkupDragRef.current = {
      pointerId: event.pointerId,
      mode,
      start: point,
      annotation,
      index: imageMarkupSelectedDraftIndex,
    };
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
    event.currentTarget.setPointerCapture(event.pointerId);
    setImageMarkupDragging(true);
    return true;
  }

  function updateImageMarkupOverlayDrag(event: ReactPointerEvent<HTMLDivElement>): boolean {
    const drag = imageMarkupDragRef.current;
    if (!drag || drag.pointerId !== event.pointerId) return false;
    const point = lightboxImageCropPointFromClient(event.clientX, event.clientY);
    if (!point) return true;
    const next = photoImageMarkupAnnotationFromDrag(drag.mode, drag.start, point, drag.annotation);
    setImageMarkupAnnotationsDraft((annotations) => {
      return photoImageMarkupUpdateAnnotationDraft(annotations, drag.index, next);
    });
    return true;
  }

  function endImageMarkupOverlayDrag(event: ReactPointerEvent<HTMLDivElement>): boolean {
    const drag = imageMarkupDragRef.current;
    if (!drag || drag.pointerId !== event.pointerId) return false;
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
    imageMarkupDragRef.current = null;
    setImageMarkupDragging(false);
    return true;
  }

  function sampleLightboxImagePoint(point: LightboxImageSamplePoint): PhotoImageRgbSample | null {
    const image = lightboxImageRef.current;
    if (!image || !image.complete || image.naturalWidth <= 0 || image.naturalHeight <= 0) return null;
    const canvas = document.createElement("canvas");
    canvas.width = image.naturalWidth;
    canvas.height = image.naturalHeight;
    const context = canvas.getContext("2d", { willReadFrequently: true });
    if (!context) return null;
    context.drawImage(image, 0, 0, canvas.width, canvas.height);
    const rect = photoImageSampleRectAroundPoint(point, canvas.width, canvas.height);
    if (!rect) return null;
    const pixels = context.getImageData(rect.left, rect.top, rect.width, rect.height).data;
    return photoImageRgbSampleFromPixels(pixels);
  }

  function photoImageAutoEnhanceStatsFromImageElement(image: HTMLImageElement | null) {
    if (!image || !image.complete || image.naturalWidth <= 0 || image.naturalHeight <= 0) return null;
    const sampleSize = photoImageAutoEnhanceSampleSize(image.naturalWidth, image.naturalHeight);
    if (!sampleSize) return null;
    const { width, height } = sampleSize;
    const canvas = document.createElement("canvas");
    canvas.width = width;
    canvas.height = height;
    const context = canvas.getContext("2d", { willReadFrequently: true });
    if (!context) return null;
    context.drawImage(image, 0, 0, width, height);
    const pixels = context.getImageData(0, 0, width, height).data;
    return photoImageAutoEnhanceStatsFromPixels(pixels);
  }

  function loadPhotoImageForAutoEnhance(url: string): Promise<HTMLImageElement | null> {
    return new Promise((resolve) => {
      const image = new Image();
      image.onload = () => resolve(image);
      image.onerror = () => resolve(null);
      image.src = url;
      if (image.complete && image.naturalWidth > 0 && image.naturalHeight > 0) resolve(image);
    });
  }

  async function sampleLightboxImageAutoEnhanceStats() {
    const analysisUrl = lightItemOriginalSourceUrl || lightItem?.sourceUrl || lightboxImageSourceUrl;
    const displayedImage = lightboxImageRef.current;
    const displayedUrl = String(displayedImage?.currentSrc || displayedImage?.src || "");
    if (analysisUrl && displayedImage && displayedUrl === analysisUrl) {
      const displayedStats = photoImageAutoEnhanceStatsFromImageElement(displayedImage);
      if (displayedStats) return displayedStats;
    }
    if (analysisUrl) {
      const originalImage = await loadPhotoImageForAutoEnhance(analysisUrl);
      const originalStats = photoImageAutoEnhanceStatsFromImageElement(originalImage);
      if (originalStats) return originalStats;
    }
    return photoImageAutoEnhanceStatsFromImageElement(displayedImage);
  }

  function applyWhiteBalanceSample(sample: PhotoImageRgbSample) {
    const next = photoImageWhiteBalanceAdjustments(imageAdjustments, sample);
    setImageAdjustments(next);
    setImageAdjustmentsOpen(true);
    setImageWhiteBalancePickerActive(false);
    setMetadataError(`${uiText("White balance sampled")}: W${next.warmth > 0 ? "+" : ""}${next.warmth} / T${next.tint > 0 ? "+" : ""}${next.tint}`);
  }

  function sampleLightboxWhiteBalance(event: ReactPointerEvent<HTMLDivElement>) {
    const point = lightboxImagePointFromClient(event.clientX, event.clientY);
    if (!point) {
      setMetadataError(uiText("Click directly on the photo to sample white balance."));
      return;
    }
    try {
      const sample = sampleLightboxImagePoint(point);
      if (!sample) {
        setMetadataError(uiText("Could not sample this image yet."));
        return;
      }
      applyWhiteBalanceSample(sample);
    } catch {
      setMetadataError(uiText("Could not sample this image for white balance."));
    }
  }

  function captureLightboxVideoPosition(video = lightboxVideoRef.current) {
    const currentMs = photoVideoCurrentMs(video);
    const durationMs = photoVideoDurationMs(video);
    lightboxVideoCurrentMsRef.current = currentMs;
    lightboxVideoDurationMsRef.current = durationMs;
    return { currentMs, durationMs };
  }

  function syncLightboxVideoState(video = lightboxVideoRef.current) {
    if (!video) {
      lightboxVideoCurrentMsRef.current = 0;
      lightboxVideoDurationMsRef.current = 0;
      setLightboxVideoPaused((current) => (current ? current : true));
      setLightboxVideoDurationMs((current) => (current === 0 ? current : 0));
      return;
    }
    const pendingSeek = pendingLightboxVideoSeekRef.current;
    if (
      pendingSeek
      && pendingSeek.sourcePath === currentLightboxSource
      && Number.isFinite(video.duration)
      && video.duration > 0
    ) {
      const durationMs = Math.max(0, Math.round(video.duration * 1000));
      const targetMs = Math.min(Math.max(0, pendingSeek.timestampMs), Math.max(0, durationMs - 1));
      try {
        video.currentTime = targetMs / 1000;
        lightboxVideoCurrentMsRef.current = targetMs;
        pendingLightboxVideoSeekRef.current = null;
      } catch {
        // A later duration or metadata event retries this one-shot seek.
      }
    }
    const { durationMs } = captureLightboxVideoPosition(video);
    setLightboxVideoPaused((current) => (current === video.paused ? current : video.paused));
    setLightboxVideoMuted((current) => (current === video.muted ? current : video.muted));
    setLightboxVideoDurationMs((current) => (current === durationMs ? current : durationMs));
  }

  function pauseLightboxVideoElement(video: HTMLVideoElement | null) {
    if (!video) return;
    try {
      video.pause();
    } catch {
      // Browser media teardown should not interrupt lightbox navigation.
    }
  }

  function pauseLightboxVideoForBackground() {
    if (!photoEffectiveMediaSettings(photoSettingsRef.current, activeLibraryRootRef.current).pauseVideoWhenBackgrounded) return;
    const video = lightboxVideoRef.current;
    pauseLightboxVideoElement(video);
    syncLightboxVideoState(video);
  }

  useEffect(() => {
    setVideoTrimStartMs(0);
    setVideoTrimEndMs(0);
    setVideoRotateDegrees(0);
    setVideoCropAspect("none");
    setImageRotateDegrees(0);
    setImageStraightenDegrees(0);
    setImageCropAspect("none");
    setImageManualCropEnabled(false);
    setImageManualCropBox(DEFAULT_PHOTO_MANUAL_CROP_BOX);
    setImageManualCropDragging(false);
    imageManualCropDragRef.current = null;
    setImageMarkupDragging(false);
    imageMarkupDragRef.current = null;
    setImageMarkupDrawingActive(false);
    imageMarkupStrokeRef.current = null;
    setImageRetouchOpen(false);
    setImageRetouchSpotsDraft([DEFAULT_PHOTO_IMAGE_RETOUCH_SPOT]);
    setImageRetouchSelectedIndex(0);
    clearImageRetouchPointerModes();
    setImageAdjustmentsOpen(false);
    setImageAdjustments(DEFAULT_PHOTO_IMAGE_ADJUSTMENTS);
    setImageWhiteBalancePickerActive(false);
    setImageFilterPreset("none");
    setImageFilterIntensity(100);
    setImageFlipHorizontal(false);
    setImageFlipVertical(false);
    setLightboxShowingOriginal(false);
    setSpatialViewMode("flat");
  }, [currentLightboxSource]);

  useEffect(() => {
    const video = lightboxVideoRef.current;
    return () => pauseLightboxVideoElement(video);
  }, [currentLightboxSource]);

  useEffect(() => {
    const onVisibilityChange = () => {
      if (document.visibilityState === "hidden") pauseLightboxVideoForBackground();
    };
    window.addEventListener("blur", pauseLightboxVideoForBackground);
    window.addEventListener("pagehide", pauseLightboxVideoForBackground);
    document.addEventListener("visibilitychange", onVisibilityChange);
    return () => {
      window.removeEventListener("blur", pauseLightboxVideoForBackground);
      window.removeEventListener("pagehide", pauseLightboxVideoForBackground);
      document.removeEventListener("visibilitychange", onVisibilityChange);
    };
  }, []);

  useEffect(() => {
    if (lightboxVideoScrubMaxMs > 0 && videoTrimEndMs > lightboxVideoScrubMaxMs) {
      setVideoTrimEndMs(lightboxVideoScrubMaxMs);
    }
  }, [lightboxVideoScrubMaxMs, videoTrimEndMs]);

  useEffect(() => {
    const video = lightboxVideoRef.current;
    setLightboxVideoMuted(shouldMuteAutoplayPhotoVideo(effectivePhotoMediaSettings));
    if (!video) return;
    video.muted = shouldMuteAutoplayPhotoVideo(effectivePhotoMediaSettings);
    if (shouldAutoplayPhotoVideo(effectivePhotoMediaSettings)) {
      void video.play().catch(() => {
        syncLightboxVideoState(video);
      });
    } else {
      video.pause();
    }
    syncLightboxVideoState(video);
  }, [effectivePhotoMediaSettings.videoAutoplay, currentLightboxSource]);

  async function toggleLightboxVideoPlayback() {
    const video = lightboxVideoRef.current;
    if (!video) return;
    try {
      if (video.paused) await video.play();
      else video.pause();
    } catch {
      setMetadataError(uiText("Could not play video."));
    } finally {
      syncLightboxVideoState(video);
    }
  }

  function toggleLightboxVideoMuted() {
    const video = lightboxVideoRef.current;
    if (!video) return;
    video.muted = !video.muted;
    syncLightboxVideoState(video);
  }

  function scrubLightboxVideo(nextMs: number) {
    const video = lightboxVideoRef.current;
    if (!video) return;
    const durationSeconds = Number.isFinite(video.duration) && video.duration > 0 ? video.duration : 0;
    const nextSeconds = Math.max(0, Math.min(durationSeconds || Number.MAX_SAFE_INTEGER, nextMs / 1000));
    video.currentTime = nextSeconds;
    syncLightboxVideoState(video);
  }

  function currentLightboxVideoPositionMs() {
    const video = lightboxVideoRef.current;
    return Math.max(0, Math.round((video && Number.isFinite(video.currentTime) ? video.currentTime * 1000 : lightboxVideoCurrentMsRef.current) || 0));
  }

  function markVideoTrimStart() {
    const current = Math.min(currentLightboxVideoPositionMs(), lightboxVideoScrubMaxMs || Number.MAX_SAFE_INTEGER);
    setVideoTrimStartMs(current);
    if (videoTrimEndMs && videoTrimEndMs <= current) {
      setVideoTrimEndMs(Math.max(current + 250, Math.min(lightboxVideoScrubMaxMs || current + 1000, current + 1000)));
    }
  }

  function markVideoTrimEnd() {
    const current = Math.min(currentLightboxVideoPositionMs(), lightboxVideoScrubMaxMs || Number.MAX_SAFE_INTEGER);
    setVideoTrimEndMs(Math.max(current, videoTrimStartMs + 250));
  }

  function updateVideoTrimStartHandle(nextMs: number) {
    const maxMs = Math.max(lightboxVideoScrubMaxMs, videoTrimEffectiveEndMs, 0);
    if (maxMs <= 0) return;
    const endMs = Math.max(videoTrimEffectiveEndMs || maxMs, 250);
    const next = Math.max(0, Math.min(Math.round(nextMs), Math.max(0, endMs - 250)));
    setVideoTrimStartMs(next);
    if (videoTrimEndMs && videoTrimEndMs <= next) {
      setVideoTrimEndMs(Math.min(maxMs, next + 250));
    }
  }

  function updateVideoTrimEndHandle(nextMs: number) {
    const maxMs = Math.max(lightboxVideoScrubMaxMs, videoTrimEffectiveEndMs, 0);
    if (maxMs <= 0) return;
    setVideoTrimEndMs(Math.max(videoTrimStartMs + 250, Math.min(Math.round(nextMs), maxMs)));
  }

  function cycleVideoRotateExport() {
    setVideoRotateDegrees((value) => {
      if (value === 0) return 90;
      if (value === 90) return 180;
      if (value === 180) return 270;
      return 0;
    });
  }

  function resetVideoExportTransform() {
    setVideoRotateDegrees(0);
    setVideoCropAspect("none");
  }

  function cycleImageRotateEdit() {
    setImageRotateDegrees((value) => {
      if (value === 0) return 90;
      if (value === 90) return 180;
      if (value === 180) return 270;
      return 0;
    });
  }

  function cycleImageCropAspectEdit() {
    setImageCropAspect((value) => nextPhotoImageCropAspect(value));
  }

  function clearImageRetouchPointerModes() {
    imageRetouchBrushRef.current = null;
    setImageRetouchBrushActive(false);
    setImageRetouchBrushDrawing(false);
    setImageRetouchCloneSourcePickerActive(false);
  }

  function toggleImageManualCrop() {
    setImageManualCropEnabled((enabled) => {
      const next = !enabled;
      if (next) {
        clearImageRetouchPointerModes();
        setImageWhiteBalancePickerActive(false);
        setImageManualCropBox((box) => (
          photoManualCropBoxActive(box) ? normalizePhotoManualCropBox(box) : { left: 10, top: 10, width: 80, height: 80 }
        ));
      }
      return next;
    });
  }

  function updateImageManualCropBox(key: keyof PhotoManualCropBox, value: unknown) {
    const number = Number(value);
    setImageManualCropBox((box) => normalizePhotoManualCropBox({
      ...box,
      [key]: Number.isFinite(number) ? number : box[key],
    }));
  }

  function updateImageAdjustment(key: keyof PhotoImageAdjustmentDraft, value: unknown) {
    const number = Number(value);
    setImageAdjustments((adjustments) => normalizePhotoImageAdjustments({
      ...adjustments,
      [key]: Number.isFinite(number) ? number : adjustments[key],
    }));
  }

  async function applyImageAutoEnhance() {
    if (!lightItem?.sourcePath || lightItemMissing) return;
    const sourcePath = lightItem.sourcePath;
    let stats: Awaited<ReturnType<typeof sampleLightboxImageAutoEnhanceStats>> = null;
    try {
      stats = await sampleLightboxImageAutoEnhanceStats();
    } catch {
      stats = null;
    }
    if (currentLightboxSourceRef.current !== sourcePath) return;
    setImageAdjustmentsOpen(true);
    setImageAdjustments((adjustments) => photoImageAutoEnhanceAdjustments(adjustments, stats));
    setMetadataError(uiText("Auto enhance applied."));
  }

  function updateImageManualCurveFromPointer(event: ReactPointerEvent<SVGSVGElement>) {
    if (!lightItem?.sourcePath) return;
    const graph = imageManualCurveGraphRef.current;
    if (!graph) return;
    const rect = graph.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    const key = photoImageManualCurveKeyForGraphX(x, rect.width);
    const value = photoImageManualCurveGraphYToValue(y, rect.height, 5);
    updateImageAdjustment(key, value);
  }

  function beginImageManualCurveGraphDrag(event: ReactPointerEvent<SVGSVGElement>) {
    if (!lightItem?.sourcePath) return;
    event.preventDefault();
    event.currentTarget.setPointerCapture(event.pointerId);
    updateImageManualCurveFromPointer(event);
  }

  function continueImageManualCurveGraphDrag(event: ReactPointerEvent<SVGSVGElement>) {
    if ((event.buttons & 1) !== 1) return;
    event.preventDefault();
    updateImageManualCurveFromPointer(event);
  }

  function imageMarkupDraftLabel(annotation: PhotoImageMarkupAnnotation, index: number) {
    const kindLabel = annotation.kind === "highlight"
      ? uiText("Highlight")
      : annotation.kind === "rectangle"
        ? uiText("Rectangle")
        : annotation.kind === "ellipse"
          ? uiText("Ellipse")
          : annotation.kind === "line"
            ? uiText("Line")
            : annotation.kind === "arrow"
              ? uiText("Arrow")
              : annotation.kind === "freehand"
                ? uiText("Freehand")
                : annotation.kind === "signature"
                  ? uiText("Signature")
                  : uiText("Text");
    const text = String(annotation.text || "").trim();
    return text ? `${index + 1}. ${kindLabel}: ${text.slice(0, 28)}` : `${index + 1}. ${kindLabel}`;
  }

  function toggleImageMarkupPanel() {
    setImageMarkupOpen((open) => {
      const next = !open;
      if (next) {
        clearImageRetouchPointerModes();
        setImageWhiteBalancePickerActive(false);
      }
      return next;
    });
    if (!imageMarkupDraftAnnotations.length) {
      setImageMarkupAnnotationsDraft([DEFAULT_PHOTO_IMAGE_MARKUP_ANNOTATION]);
      setImageMarkupSelectedIndex(0);
    }
  }

  function addImageMarkupAnnotation() {
    setImageMarkupOpen(true);
    clearImageRetouchPointerModes();
    setImageWhiteBalancePickerActive(false);
    setImageMarkupAnnotationsDraft((annotations) => {
      const draft = photoImageMarkupAddAnnotationDraft(annotations);
      setImageMarkupSelectedIndex(draft.selectedIndex);
      return draft.annotations;
    });
  }

  function deleteSelectedImageMarkupAnnotation() {
    setImageMarkupDrawingActive(false);
    imageMarkupStrokeRef.current = null;
    setImageMarkupAnnotationsDraft((annotations) => {
      const draft = photoImageMarkupDeleteAnnotationDraft(annotations, imageMarkupSelectedIndex);
      if (draft.closePanel) setImageMarkupOpen(false);
      setImageMarkupSelectedIndex(draft.selectedIndex);
      return draft.annotations;
    });
  }

  function toggleImageMarkupDrawing() {
    setImageMarkupOpen(true);
    setImageMarkupDrawingActive((active) => {
      const next = !active;
      if (next) {
        clearImageRetouchPointerModes();
        setImageWhiteBalancePickerActive(false);
      }
      if (next && imageMarkupSelectedAnnotation.kind !== "freehand" && imageMarkupSelectedAnnotation.kind !== "signature") {
        updateImageMarkupAnnotation({ kind: "freehand", points: [] });
      }
      if (!next) imageMarkupStrokeRef.current = null;
      return next;
    });
  }

  function commitImageSignaturePresets(values: unknown) {
    const normalized = normalizePhotoImageSignaturePresets(values);
    setImageSignaturePresets(normalized);
    storePhotoImageSignaturePresets(PHOTO_IMAGE_SIGNATURE_PRESETS_KEY, normalized);
    return normalized;
  }

  function saveSelectedImageSignaturePreset() {
    const draft = photoImageSignaturePresetSaveDraft(imageMarkupSelectedAnnotation, imageSignaturePresets, {
      id: `signature-${Date.now().toString(36)}`,
      name: `${uiText("Signature")} ${imageSignaturePresets.length + 1}`,
      createdAt: new Date().toISOString(),
    });
    if (!draft) {
      setMetadataError(uiText("Draw a signature before saving it."));
      return;
    }
    commitImageSignaturePresets(draft.presets);
    setMetadataError(uiText("Signature saved."));
  }

  function insertImageSignaturePreset(presetId: string) {
    const preset = imageSignaturePresets.find((item) => item.id === presetId);
    const annotation = photoImageMarkupSignatureAnnotationFromPreset(preset || null);
    if (!annotation) return;
    setImageMarkupOpen(true);
    setImageMarkupDrawingActive(false);
    imageMarkupStrokeRef.current = null;
    setImageMarkupAnnotationsDraft((annotations) => {
      const draft = photoImageMarkupInsertAnnotationDraft(annotations, annotation);
      if (!draft) return annotations;
      setImageMarkupSelectedIndex(draft.selectedIndex);
      return draft.annotations;
    });
  }

  function deleteImageSignaturePreset(presetId: string) {
    commitImageSignaturePresets(photoImageSignaturePresetDeleteDraft(imageSignaturePresets, presetId));
  }

  function updateImageMarkupAnnotation(patch: Partial<PhotoImageMarkupAnnotation>) {
    setImageMarkupAnnotationsDraft((annotations) => {
      return photoImageMarkupUpdateAnnotationDraft(annotations, imageMarkupSelectedIndex, patch);
    });
  }

  function imageRetouchSpotDraftLabel(spot: PhotoImageRetouchSpot, index: number) {
    const kindLabel = spot.kind === "red_eye"
      ? uiText("Red-eye")
      : spot.kind === "clone"
        ? uiText("Clone")
        : uiText("Retouch");
    return `${index + 1}. ${kindLabel} ${Math.round(spot.width)}x${Math.round(spot.height)}`;
  }

  function toggleImageRetouchPanel() {
    setImageRetouchOpen((open) => {
      const nextOpen = !open;
      if (!nextOpen) {
        clearImageRetouchPointerModes();
      } else {
        setImageWhiteBalancePickerActive(false);
      }
      return nextOpen;
    });
    if (!imageRetouchDraftSpots.length) {
      setImageRetouchSpotsDraft([DEFAULT_PHOTO_IMAGE_RETOUCH_SPOT]);
      setImageRetouchSelectedIndex(0);
    }
  }

  function addImageRetouchSpot(kind: PhotoImageRetouchSpot["kind"] = imageRetouchSelectedSpot.kind || "blemish") {
    setImageRetouchOpen(true);
    setImageWhiteBalancePickerActive(false);
    setImageRetouchSpotsDraft((spots) => {
      const draft = photoImageRetouchAddSpotDraft(spots, kind);
      setImageRetouchSelectedIndex(draft.selectedIndex);
      return draft.spots;
    });
  }

  function deleteSelectedImageRetouchSpot() {
    setImageRetouchSpotsDraft((spots) => {
      const draft = photoImageRetouchDeleteSpotDraft(spots, imageRetouchSelectedIndex);
      if (draft.closePanel) setImageRetouchOpen(false);
      setImageRetouchSelectedIndex(draft.selectedIndex);
      return draft.spots;
    });
  }

  function updateImageRetouchSpot(patch: Partial<PhotoImageRetouchSpot>) {
    if (patch.kind !== undefined) {
      clearImageRetouchPointerModes();
    }
    setImageRetouchSpotsDraft((spots) => {
      return photoImageRetouchUpdateSpotDraft(spots, imageRetouchSelectedIndex, patch);
    });
  }

  function pickImageRetouchCloneSource(event: ReactPointerEvent<HTMLDivElement>): boolean {
    if (!imageRetouchCloneSourcePickingActive) return false;
    const point = lightboxImageCropPointFromClient(event.clientX, event.clientY);
    if (!point) {
      setMetadataError(uiText("Click directly on the photo to pick a clone source."));
      return true;
    }
    const patch = photoImageRetouchCloneSourcePatch(point, imageRetouchSelectedSpot);
    if (!patch) return true;
    updateImageRetouchSpot(patch);
    setImageRetouchCloneSourcePickerActive(false);
    setMetadataError("");
    return true;
  }

  function appendImageRetouchBrushPoint(point: PhotoManualCropPoint, brush: ImageRetouchBrushState, replaceDefaultOnly = false) {
    setImageRetouchOpen(true);
    setImageRetouchSpotsDraft((spots) => {
      const draft = photoImageRetouchAppendBrushPointDraft(spots, point, brush, replaceDefaultOnly);
      if (draft.limitReached) {
        setMetadataError(uiText("Retouch spot limit reached."));
      }
      if (draft.selectedIndex !== null) {
        setImageRetouchSelectedIndex(draft.selectedIndex);
      }
      return draft.spots;
    });
  }

  function beginImageRetouchBrushDraw(event: ReactPointerEvent<HTMLDivElement>): boolean {
    if (!imageRetouchBrushPlacementActive) return false;
    const point = lightboxImageCropPointFromClient(event.clientX, event.clientY);
    if (!point) {
      setMetadataError(uiText("Drag directly on the photo to retouch."));
      return true;
    }
    const brush = photoImageRetouchBrushStateFromPoint(event.pointerId, point, imageRetouchSelectedSpot);
    if (!brush) return true;
    imageRetouchBrushRef.current = brush;
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
    event.currentTarget.setPointerCapture(event.pointerId);
    setImageRetouchBrushDrawing(true);
    appendImageRetouchBrushPoint(point, brush, true);
    return true;
  }

  function updateImageRetouchBrushDraw(event: ReactPointerEvent<HTMLDivElement>): boolean {
    const brush = imageRetouchBrushRef.current;
    if (!brush || brush.pointerId !== event.pointerId) return false;
    const point = lightboxImageCropPointFromClient(event.clientX, event.clientY);
    if (!point) return true;
    if (Math.hypot(brush.lastPoint.x - point.x, brush.lastPoint.y - point.y) < brush.spacing) return true;
    brush.lastPoint = point;
    appendImageRetouchBrushPoint(point, brush);
    return true;
  }

  function endImageRetouchBrushDraw(event: ReactPointerEvent<HTMLDivElement>): boolean {
    const brush = imageRetouchBrushRef.current;
    if (!brush || brush.pointerId !== event.pointerId) return false;
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
    imageRetouchBrushRef.current = null;
    setImageRetouchBrushDrawing(false);
    return true;
  }

  function toggleImageWhiteBalancePicker() {
    setImageAdjustmentsOpen(true);
    setImageWhiteBalancePickerActive((active) => {
      const next = !active;
      if (next) clearImageRetouchPointerModes();
      setMetadataError(next ? uiText("Click a neutral gray or white point in the photo.") : "");
      return next;
    });
  }

  function currentImageEditOperation(source = "photos-lightbox"): PhotoImageEditOperation | null {
    return photoImageEditOperationDraft({
      rotateDegrees: imageRotateDegrees,
      straightenDegrees: Number(imageStraightenDegrees.toFixed(2)),
      manualCropActive: imageManualCropActive,
      manualCropBox: imageManualCropBox,
      cropAspect: imageCropAspect,
      adjustmentsActive: imageAdjustmentsActive,
      adjustments: imageAdjustments,
      filterActive: imageFilterActive,
      filterPreset: imageFilterPreset,
      filterIntensity: imageFilterIntensity,
      markupActive: imageMarkupActive,
      markup: imageMarkupAnnotations,
      retouchActive: imageRetouchActive,
      retouch: imageRetouchSpots,
      flipHorizontal: imageFlipHorizontal,
      flipVertical: imageFlipVertical,
      source,
    });
  }

  function setImageEditDraftState(draft: PhotoImageEditDefaultDraftState) {
    setImageRotateDegrees(draft.rotateDegrees);
    setImageStraightenDegrees(draft.straightenDegrees);
    setImageCropAspect(draft.cropAspect);
    setImageManualCropEnabled(draft.manualCropEnabled);
    setImageManualCropBox(draft.manualCropBox);
    setImageAdjustmentsOpen(draft.adjustmentsOpen);
    setImageAdjustments(draft.adjustments);
    setImageFilterPreset(draft.filterPreset);
    setImageFilterIntensity(draft.filterIntensity);
    setImageMarkupOpen(draft.markupOpen);
    setImageMarkupAnnotationsDraft(draft.markupAnnotations);
    setImageMarkupSelectedIndex(draft.markupSelectedIndex);
    setImageRetouchOpen(draft.retouchOpen);
    setImageRetouchSpotsDraft(draft.retouchSpots);
    setImageRetouchSelectedIndex(draft.retouchSelectedIndex);
    setImageFlipHorizontal(draft.flipHorizontal);
    setImageFlipVertical(draft.flipVertical);
  }

  function applyImageEditOperationToDraft(operation: Record<string, unknown> | PhotoImageEditOperation | null | undefined): PhotoImageEditOperation | null {
    const draft = photoImageEditDraftStateFromOperation(operation);
    if (!draft) return null;
    setImageEditDraftState(draft);
    imageRetouchBrushRef.current = null;
    setImageRetouchBrushActive(false);
    setImageRetouchBrushDrawing(false);
    setImageRetouchCloneSourcePickerActive(false);
    return draft.operation;
  }

  function resetImageEditDraft() {
    const draft = photoImageEditDefaultDraftState();
    setImageEditDraftState(draft);
    setImageMarkupDrawingActive(false);
    imageMarkupStrokeRef.current = null;
    setImageRetouchBrushActive(false);
    setImageRetouchBrushDrawing(false);
    setImageRetouchCloneSourcePickerActive(false);
    imageRetouchBrushRef.current = null;
  }

  function saveImageEditClipboardHistory(nextHistory: PhotoImageEditClipboardEntry[]) {
    const normalized = normalizePhotoImageEditClipboardHistory(nextHistory);
    setImageEditClipboardHistory(normalized);
    storePhotoImageEditClipboardHistory(PHOTO_IMAGE_EDIT_CLIPBOARD_KEY, normalized);
    return normalized;
  }

  function selectImageEditClipboardHistoryEntry(entryId: string) {
    const draft = photoImageEditClipboardSelectionDraft(imageEditClipboardHistory, entryId);
    setImageEditClipboardId(draft.selectedId);
    setImageEditClipboard(draft.operation);
    if (draft.entry) {
      setMetadataError(`${uiText("Loaded copied edits")}: ${draft.label}`);
    }
  }

  function deleteSelectedImageEditClipboardHistoryEntry() {
    if (!imageEditClipboardId) return;
    const draft = photoImageEditClipboardDeleteDraft(imageEditClipboardHistory, imageEditClipboardId);
    saveImageEditClipboardHistory(draft.history);
    setImageEditClipboardId(draft.selectedId);
    setImageEditClipboard(draft.operation);
    setMetadataError(uiText("Removed copied edit from history."));
  }

  function copyCurrentImageEdit() {
    const operation = currentImageEditOperation("photos-lightbox-copy") || photoEditStackImageOperation;
    const draft = photoImageEditClipboardCopyDraft(operation as Record<string, unknown> | null, imageEditClipboardHistory);
    if (!draft) {
      setMetadataError(uiText("Choose or save image edits before copying."));
      return;
    }
    setImageEditClipboard(draft.operation);
    saveImageEditClipboardHistory(draft.history);
    setImageEditClipboardId(draft.selectedId);
    setMetadataError(`${uiText("Copied edits")}: ${draft.label}`);
  }

  async function reloadActivePhotoPage() {
    await loadPage(currentPageRequest({ offset: 0 }));
  }

  async function saveCurrentVideoEditStack(item: PhotoItem | null) {
    if (!item?.sourcePath || !isVideoMediaKind(item.mediaKind)) {
      setMetadataError(uiText("Video original path is not available."));
      return;
    }
    const endMs = videoTrimEffectiveEndMs;
    const trimChanged = videoTrimRangeValid && (videoTrimStartMs > 0 || (lightboxVideoScrubMaxMs > 0 && endMs < lightboxVideoScrubMaxMs));
    if (!trimChanged && !videoTransformActive) {
      setMetadataError(uiText("Mark a trim range or choose a video transform first."));
      return;
    }
    const operation = {
      kind: "video_trim_transform",
      startMs: trimChanged ? videoTrimStartMs : 0,
      endMs: trimChanged ? endMs : 0,
      rotateDegrees: videoRotateDegrees,
      cropAspect: videoCropAspect,
      ...photoVideoRenderOptionsPayload({
        videoRenderFormat: exportVideoRenderFormat,
        videoRenderQuality: exportVideoRenderQuality,
        renderMaxDimension: effectiveExportRenderMaxDimensionNumber,
      }),
      sourceDurationMs: lightboxVideoScrubMaxMs,
    };
    setPhotoEditStackSaving(true);
    setMetadataError("");
    try {
      const result = await savePhotoEditStack(photoEditStackSavePayload({
        sourcePath: item.sourcePath,
        assetId: item.assetId,
        operations: [operation],
      }));
      setPhotoEditStack(result.value || null);
      await loadFolders();
      await reloadActivePhotoPage();
    } catch (error) {
      setMetadataError(errorMessage(error));
    } finally {
      setPhotoEditStackSaving(false);
    }
  }

  async function saveCurrentImageEditStack(item: PhotoItem | null) {
    if (!item?.sourcePath || isVideoMediaKind(item.mediaKind)) {
      setMetadataError(uiText("Photo original path is not available."));
      return;
    }
    if (!imageTransformActive) {
      setMetadataError(uiText("Choose an image rotation, crop, filter, or adjustment first."));
      return;
    }
    const operation = currentImageEditOperation("photos-lightbox");
    if (!operation) {
      setMetadataError(uiText("Choose an image rotation, crop, filter, or adjustment first."));
      return;
    }
    setPhotoEditStackSaving(true);
    setMetadataError("");
    try {
      const result = await savePhotoEditStack(photoEditStackSavePayload({
        sourcePath: item.sourcePath,
        assetId: item.assetId,
        operations: photoEditOperationsWithGeneratedBase(photoEditStack, operation),
      }));
      setPhotoEditStack(result.value || null);
      await loadFolders();
      await reloadActivePhotoPage();
    } catch (error) {
      setMetadataError(errorMessage(error));
    } finally {
      setPhotoEditStackSaving(false);
    }
  }

  const imagePasteTextOptions = { uiText, formatCount };

  async function confirmImageEditPasteConflicts(conflictCount: number, mode: "edit" | "adjustments", operation: PhotoImageEditOperation | null): Promise<boolean> {
    const draft = photoImagePasteConflictDialogDraft(conflictCount, mode, operation, imagePasteTextOptions);
    if (!draft) return true;
    return confirmPhotoAction({
      title: draft.title,
      message: draft.message,
      confirmLabel: draft.confirmLabel,
      cancelLabel: draft.cancelLabel,
    });
  }

  async function pasteImageEditClipboardToCurrent(item: PhotoItem | null) {
    const operation = photoImageEditClipboardPasteOperation(imageEditClipboard, "photos-lightbox-paste");
    if (!operation) {
      setMetadataError(uiText("Copy image edits first."));
      return;
    }
    if (!item?.sourcePath || item.missingAt || isVideoMediaKind(item.mediaKind)) {
      setMetadataError(uiText("Copied edits can only be pasted to available image photos."));
      return;
    }
    if (!await confirmImageEditPasteConflicts(photoImageEditPasteHasConflict(photoEditStackImageOperation, operation) ? 1 : 0, "edit", operation)) {
      setMetadataError(uiText("Paste canceled."));
      return;
    }
    applyImageEditOperationToDraft(operation);
    setPhotoEditStackSaving(true);
    setMetadataError("");
    try {
      const result = await savePhotoEditStack(photoEditStackSavePayload({
        sourcePath: item.sourcePath,
        assetId: item.assetId,
        operations: photoEditOperationsWithGeneratedBase(photoEditStack, operation),
      }));
      setPhotoEditStack(result.value || null);
      await loadFolders();
      await reloadActivePhotoPage();
    } catch (error) {
      setMetadataError(errorMessage(error));
    } finally {
      setPhotoEditStackSaving(false);
    }
  }

  async function pasteImageAdjustmentClipboardToCurrent(item: PhotoItem | null) {
    if (!item?.sourcePath || item.missingAt || isVideoMediaKind(item.mediaKind)) {
      setMetadataError(uiText("Copied adjustments can only be pasted to available image photos."));
      return;
    }
    const targetOperation = currentImageEditOperation("photos-adjustment-paste-target") || photoEditStackImageOperation;
    const operation = mergePhotoImageAdjustmentPasteOperation(targetOperation, imageEditClipboard, "photos-lightbox-adjustment-paste");
    if (!operation) {
      setMetadataError(uiText("Copied edits do not include adjustments."));
      return;
    }
    if (!await confirmImageEditPasteConflicts(photoImageAdjustmentPasteHasConflict(targetOperation, operation) ? 1 : 0, "adjustments", imageEditClipboard)) {
      setMetadataError(uiText("Paste canceled."));
      return;
    }
    applyImageEditOperationToDraft(operation);
    setPhotoEditStackSaving(true);
    setMetadataError("");
    try {
      const result = await savePhotoEditStack(photoEditStackSavePayload({
        sourcePath: item.sourcePath,
        assetId: item.assetId,
        operations: photoEditOperationsWithGeneratedBase(photoEditStack, operation),
      }));
      setPhotoEditStack(result.value || null);
      const label = operation.adjustments ? photoImageAdjustmentsLabel(operation.adjustments) : uiText("Adjustments");
      setMetadataError(`${uiText("Pasted adjustments")}: ${label}`);
      await loadFolders();
      await reloadActivePhotoPage();
    } catch (error) {
      setMetadataError(errorMessage(error));
    } finally {
      setPhotoEditStackSaving(false);
    }
  }

  async function pasteImageEditClipboardToSelected() {
    const operation = photoImageEditClipboardPasteOperation(imageEditClipboard, "photos-bulk-paste");
    if (!operation) {
      setMetadataError(uiText("Copy image edits first."));
      return;
    }
    if (!selectedImageEditPasteItems.length) {
      setMetadataError(uiText("Select available image photos before pasting edits."));
      return;
    }
    const total = selectedImageEditPasteItems.length;
    setPhotoEditStackSaving(true);
    setMetadataError(photoImagePasteProgressMessage("edits", "checking", 0, total, imagePasteTextOptions));
    const plans: Array<{ item: PhotoItem; conflict: boolean; stack: PhotoEditStackValue | null }> = [];
    let failed = 0;
    try {
      const stackResult = await getPhotoEditStacks({
        items: selectedImageEditPasteItems.map(photoEditStackTargetPayload),
      });
      failed += Math.max(0, Number(stackResult.value?.failed || 0));
      const stackRows = stackResult.value?.items || [];
      for (const row of stackRows) {
        const item = selectedImageEditPasteItems[Math.max(0, Number(row.index || 0))];
        if (!item) continue;
        const existingOperation = photoEditStackImageOperationFromValue(row || null);
        plans.push({ item, conflict: photoImageEditPasteHasConflict(existingOperation, operation), stack: row || null });
      }
      setMetadataError(photoImagePasteProgressMessage("edits", "checking", total, total, imagePasteTextOptions));
    } catch {
      failed += total;
    }
    setPhotoEditStackSaving(false);
    const conflictCount = plans.filter((plan) => plan.conflict).length;
    if (!await confirmImageEditPasteConflicts(conflictCount, "edit", operation)) {
      setMetadataError(uiText("Paste canceled."));
      return;
    }
    if (!plans.length) {
      setMetadataError(photoImagePasteResultMessage("edits", 0, 0, failed || selectedImageEditPasteItems.length, imagePasteTextOptions));
      return;
    }
    setPhotoEditStackSaving(true);
    setMetadataError(photoImagePasteProgressMessage("edits", "pasting", 0, plans.length, imagePasteTextOptions));
    try {
      const result = await savePhotoEditStacks({
        items: plans.map((plan) => photoEditStackSavePayload({
          sourcePath: plan.item.sourcePath,
          assetId: plan.item.assetId,
          operations: photoEditOperationsWithGeneratedBase(plan.stack, operation),
        })),
      });
      failed += Math.max(0, Number(result.value?.failed || 0));
      const savedRows = result.value?.items || [];
      const savedIndexes = new Set<number>();
      savedRows.forEach((row) => {
        const rowIndex = Math.max(0, Number(row.index || 0));
        savedIndexes.add(rowIndex);
        const plan = plans[rowIndex];
        if (plan && lightItem?.sourcePath && plan.item.sourcePath === lightItem.sourcePath) {
          setPhotoEditStack(row || null);
        }
      });
      const pasted = savedRows.length;
      const replaced = plans.reduce((count, plan, index) => count + (plan.conflict && savedIndexes.has(index) ? 1 : 0), 0);
      setMetadataError(photoImagePasteProgressMessage("edits", "pasting", plans.length, plans.length, imagePasteTextOptions));
      setMetadataError(photoImagePasteResultMessage("edits", pasted, replaced, failed, imagePasteTextOptions));
      await loadFolders();
      await reloadActivePhotoPage();
    } catch (error) {
      setMetadataError(errorMessage(error));
    } finally {
      setPhotoEditStackSaving(false);
    }
  }

  async function pasteImageAdjustmentClipboardToSelected() {
    if (!imageEditClipboardHasAdjustments) {
      setMetadataError(uiText("Copied edits do not include adjustments."));
      return;
    }
    if (!selectedImageEditPasteItems.length) {
      setMetadataError(uiText("Select available image photos before pasting adjustments."));
      return;
    }
    const total = selectedImageEditPasteItems.length;
    setPhotoEditStackSaving(true);
    setMetadataError(photoImagePasteProgressMessage("adjustments", "checking", 0, total, imagePasteTextOptions));
    const plans: Array<{ item: PhotoItem; operation: PhotoImageEditOperation; conflict: boolean; stack: PhotoEditStackValue | null }> = [];
    let failed = 0;
    let skipped = 0;
    try {
      const stackResult = await getPhotoEditStacks({
        items: selectedImageEditPasteItems.map(photoEditStackTargetPayload),
      });
      failed += Math.max(0, Number(stackResult.value?.failed || 0));
      const stackRows = stackResult.value?.items || [];
      for (const row of stackRows) {
        const item = selectedImageEditPasteItems[Math.max(0, Number(row.index || 0))];
        if (!item) continue;
        const targetOperation = photoEditStackImageOperationFromValue(row || null);
        const operation = mergePhotoImageAdjustmentPasteOperation(targetOperation, imageEditClipboard, "photos-bulk-adjustment-paste");
        if (!operation) {
          skipped += 1;
          continue;
        }
        plans.push({ item, operation, conflict: photoImageAdjustmentPasteHasConflict(targetOperation, operation), stack: row || null });
      }
      setMetadataError(photoImagePasteProgressMessage("adjustments", "checking", total, total, imagePasteTextOptions));
    } catch {
      failed += total;
    }
    setPhotoEditStackSaving(false);
    const conflictCount = plans.filter((plan) => plan.conflict).length;
    if (!await confirmImageEditPasteConflicts(conflictCount, "adjustments", imageEditClipboard)) {
      setMetadataError(uiText("Paste canceled."));
      return;
    }
    if (!plans.length) {
      setMetadataError(photoImagePasteResultMessage("adjustments", 0, 0, failed + skipped || selectedImageEditPasteItems.length, imagePasteTextOptions));
      return;
    }
    setPhotoEditStackSaving(true);
    setMetadataError(photoImagePasteProgressMessage("adjustments", "pasting", 0, plans.length, imagePasteTextOptions));
    try {
      const result = await savePhotoEditStacks({
        items: plans.map((plan) => photoEditStackSavePayload({
          sourcePath: plan.item.sourcePath,
          assetId: plan.item.assetId,
          operations: photoEditOperationsWithGeneratedBase(plan.stack, plan.operation),
        })),
      });
      failed += Math.max(0, Number(result.value?.failed || 0));
      const savedRows = result.value?.items || [];
      const savedIndexes = new Set<number>();
      savedRows.forEach((row) => {
        const rowIndex = Math.max(0, Number(row.index || 0));
        savedIndexes.add(rowIndex);
        const plan = plans[rowIndex];
        if (plan && lightItem?.sourcePath && plan.item.sourcePath === lightItem.sourcePath) {
          setPhotoEditStack(row || null);
        }
      });
      const pasted = savedRows.length;
      const replaced = plans.reduce((count, plan, index) => count + (plan.conflict && savedIndexes.has(index) ? 1 : 0), 0);
      setMetadataError(photoImagePasteProgressMessage("adjustments", "pasting", plans.length, plans.length, imagePasteTextOptions));
      setMetadataError(photoImagePasteResultMessage("adjustments", pasted, replaced, failed, { ...imagePasteTextOptions, skipped }));
      await loadFolders();
      await reloadActivePhotoPage();
    } catch (error) {
      setMetadataError(errorMessage(error));
    } finally {
      setPhotoEditStackSaving(false);
    }
  }

  async function revertCurrentPhotoEditStack(item: PhotoItem | null) {
    if (!item?.sourcePath && !item?.assetId) {
      setMetadataError(uiText("Photo original path is not available."));
      return;
    }
    setPhotoEditStackSaving(true);
    setMetadataError("");
    try {
      await revertPhotoEditStack(photoEditStackTargetPayload(item));
      setPhotoEditStack(null);
      await loadFolders();
      await reloadActivePhotoPage();
    } catch (error) {
      setMetadataError(errorMessage(error));
    } finally {
      setPhotoEditStackSaving(false);
    }
  }

  async function revertSelectedPhotoEditStacks() {
    if (!selectedEditStackItems.length) {
      setMetadataError(uiText("Select edited photos before reverting edits."));
      return;
    }
    const total = selectedEditStackItems.length;
    const confirmDraft = photoEditStackRevertConfirmDialogDraft(total, imagePasteTextOptions);
    if (!await confirmPhotoAction(confirmDraft)) {
      setMetadataError(uiText("Revert canceled."));
      return;
    }
    setPhotoEditStackSaving(true);
    setMetadataError(photoEditStackRevertProgressMessage(0, total, imagePasteTextOptions));
    let reverted = 0;
    let failed = 0;
    try {
      for (const [index, item] of selectedEditStackItems.entries()) {
        setMetadataError(photoEditStackRevertProgressMessage(index + 1, total, imagePasteTextOptions));
        try {
          await revertPhotoEditStack(photoEditStackTargetPayload(item));
          if (lightItem?.sourcePath && item.sourcePath === lightItem.sourcePath) {
            setPhotoEditStack(null);
          }
          reverted += 1;
        } catch {
          failed += 1;
        }
      }
      setSelectedSources(new Set());
      setMetadataError(photoEditStackRevertResultMessage(reverted, failed, imagePasteTextOptions));
      await loadFolders();
      await reloadActivePhotoPage();
      if (lightItem) {
        await refreshCurrentPhotoEditStackVersions(lightItem);
      }
    } catch (error) {
      setMetadataError(errorMessage(error));
    } finally {
      setPhotoEditStackSaving(false);
    }
  }

  async function snapshotSelectedPhotoEditStackVersions() {
    if (!selectedEditStackItems.length) {
      setMetadataError(uiText("Select edited photos before snapshotting versions."));
      return;
    }
    const total = selectedEditStackItems.length;
    setPhotoEditStackSaving(true);
    setMetadataError(photoEditStackVersionProgressMessage("snapshot", 0, total, imagePasteTextOptions));
    let snapshotted = 0;
    let failed = 0;
    try {
      for (const [index, item] of selectedEditStackItems.entries()) {
        setMetadataError(photoEditStackVersionProgressMessage("snapshot", index + 1, total, imagePasteTextOptions));
        try {
          await createPhotoEditStackVersion(photoEditStackTargetPayload(item));
          snapshotted += 1;
        } catch {
          failed += 1;
        }
      }
      setMetadataError(photoEditStackVersionSnapshotResultMessage(snapshotted, failed, imagePasteTextOptions));
      if (lightItem) {
        await refreshCurrentPhotoEditStackVersions(lightItem);
      }
    } catch (error) {
      setMetadataError(errorMessage(error));
    } finally {
      setPhotoEditStackSaving(false);
    }
  }

  async function restoreLatestSelectedPhotoEditStackVersions() {
    if (!selectedEditStackVersionItems.length) {
      setMetadataError(uiText("Select photos with saved edit versions first."));
      return;
    }
    const total = selectedEditStackVersionItems.length;
    const confirmDraft = photoEditStackVersionConfirmDialogDraft("restore", total, imagePasteTextOptions);
    if (!await confirmPhotoAction(confirmDraft)) {
      setMetadataError(uiText("Restore canceled."));
      return;
    }
    setPhotoEditStackSaving(true);
    setMetadataError(photoEditStackVersionProgressMessage("restore", 0, total, imagePasteTextOptions));
    let restored = 0;
    let skipped = 0;
    let failed = 0;
    try {
      for (const [index, item] of selectedEditStackVersionItems.entries()) {
        setMetadataError(photoEditStackVersionProgressMessage("restore", index + 1, total, imagePasteTextOptions));
        try {
          const versionsResult = await listPhotoEditStackVersions(photoEditStackVersionListPayload({ ...item, limit: 1 }));
          const version = Array.isArray(versionsResult.value?.versions) ? versionsResult.value.versions[0] : null;
          if (!version?.versionId) {
            skipped += 1;
            continue;
          }
          const restoredResult = await restorePhotoEditStackVersion(photoEditStackVersionPayload({
            sourcePath: item.sourcePath,
            assetId: item.assetId,
            versionId: version.versionId,
          }));
          if (lightItem?.sourcePath && item.sourcePath === lightItem.sourcePath) {
            const stack = restoredResult.value.stack || null;
            setPhotoEditStack(stack);
            const operation = photoEditStackImageOperationFromValue(stack);
            if (operation) applyImageEditOperationToDraft(operation);
          }
          restored += 1;
        } catch {
          failed += 1;
        }
      }
      setMetadataError(photoEditStackVersionRestoreResultMessage(restored, skipped, failed, imagePasteTextOptions));
      await loadFolders();
      await reloadActivePhotoPage();
      if (lightItem) {
        await refreshCurrentPhotoEditStackVersions(lightItem);
      }
    } catch (error) {
      setMetadataError(errorMessage(error));
    } finally {
      setPhotoEditStackSaving(false);
    }
  }

  async function deleteSelectedPhotoEditStackVersions() {
    if (!selectedEditStackVersionItems.length) {
      setMetadataError(uiText("Select photos with saved edit versions first."));
      return;
    }
    const total = selectedEditStackVersionItems.length;
    const confirmDraft = photoEditStackVersionConfirmDialogDraft("delete", total, imagePasteTextOptions);
    if (!await confirmPhotoAction(confirmDraft)) {
      setMetadataError(uiText("Delete canceled."));
      return;
    }
    setPhotoEditStackSaving(true);
    setMetadataError(photoEditStackVersionProgressMessage("delete", 0, total, imagePasteTextOptions));
    let deleted = 0;
    let skipped = 0;
    let failed = 0;
    try {
      for (const [index, item] of selectedEditStackVersionItems.entries()) {
        setMetadataError(photoEditStackVersionProgressMessage("delete", index + 1, total, imagePasteTextOptions));
        try {
          const versionsResult = await listPhotoEditStackVersions(photoEditStackVersionListPayload({ ...item, limit: 100 }));
          const versions = Array.isArray(versionsResult.value?.versions) ? versionsResult.value.versions : [];
          if (!versions.length) {
            skipped += 1;
            continue;
          }
          for (const version of versions) {
            if (!version.versionId) continue;
            await deletePhotoEditStackVersion(photoEditStackVersionPayload({
              sourcePath: item.sourcePath,
              assetId: item.assetId,
              versionId: version.versionId,
            }));
            deleted += 1;
          }
        } catch {
          failed += 1;
        }
      }
      setMetadataError(photoEditStackVersionDeleteResultMessage(deleted, skipped, failed, imagePasteTextOptions));
      await loadFolders();
      await reloadActivePhotoPage();
      if (lightItem) {
        await refreshCurrentPhotoEditStackVersions(lightItem);
      }
    } catch (error) {
      setMetadataError(errorMessage(error));
    } finally {
      setPhotoEditStackSaving(false);
    }
  }

  async function refreshCurrentPhotoEditStackVersions(item: PhotoItem | null) {
    if (!item?.sourcePath && !item?.assetId) {
      setPhotoEditStackVersions([]);
      setPhotoEditStackVersionId("");
      return;
    }
    const result = await listPhotoEditStackVersions(photoEditStackVersionListPayload(item));
    const versions = Array.isArray(result.value?.versions) ? result.value.versions : [];
    setPhotoEditStackVersions(versions);
    setPhotoEditStackVersionId((current) => versions.some((version) => version.versionId === current) ? current : versions[0]?.versionId || "");
  }

  async function duplicateCurrentPhotoEditStackVersion(item: PhotoItem | null) {
    if (!item?.sourcePath && !item?.assetId) {
      setMetadataError(uiText("Photo original path is not available."));
      return;
    }
    if (!photoEditStack) {
      setMetadataError(uiText("Save an edit stack before duplicating a version."));
      return;
    }
    setPhotoEditStackSaving(true);
    setMetadataError("");
    try {
      const result = await createPhotoEditStackVersion(photoEditStackTargetPayload(item));
      const version = result.value;
      setPhotoEditStackVersions((current) => [version, ...current.filter((entry) => entry.versionId !== version.versionId)]);
      setPhotoEditStackVersionId(version.versionId);
      setMetadataError(photoEditStackVersionSingleResultMessage("duplicate", version.label, imagePasteTextOptions));
    } catch (error) {
      setMetadataError(errorMessage(error));
    } finally {
      setPhotoEditStackSaving(false);
    }
  }

  async function restoreSelectedPhotoEditStackVersion(item: PhotoItem | null) {
    if (!item?.sourcePath && !item?.assetId) {
      setMetadataError(uiText("Photo original path is not available."));
      return;
    }
    if (!selectedPhotoEditStackVersion) {
      setMetadataError(uiText("Choose an edit version first."));
      return;
    }
    const confirmDraft = photoEditStackVersionSingleConfirmDialogDraft("restore", selectedPhotoEditStackVersion.label, imagePasteTextOptions);
    if (!await confirmPhotoAction(confirmDraft)) {
      setMetadataError(uiText("Restore canceled."));
      return;
    }
    setPhotoEditStackSaving(true);
    setMetadataError("");
    try {
      const result = await restorePhotoEditStackVersion(photoEditStackVersionPayload({
        sourcePath: item.sourcePath,
        assetId: item.assetId,
        versionId: selectedPhotoEditStackVersion.versionId,
      }));
      const stack = result.value.stack || null;
      setPhotoEditStack(stack);
      const operation = photoEditStackImageOperationFromValue(stack);
      if (operation) applyImageEditOperationToDraft(operation);
      setMetadataError(photoEditStackVersionSingleResultMessage("restore", selectedPhotoEditStackVersion.label, imagePasteTextOptions));
      await refreshCurrentPhotoEditStackVersions(item);
      await loadFolders();
      await reloadActivePhotoPage();
    } catch (error) {
      setMetadataError(errorMessage(error));
    } finally {
      setPhotoEditStackSaving(false);
    }
  }

