  async function runSemanticPhotoSearch(query: string) {
    const trimmed = query.trim();
    if (trimmed.length < 2) {
      setSemanticError(uiText("Type at least 2 characters to search by meaning."));
      return;
    }
    setSemanticBusy(true);
    setSemanticError("");
    try {
      const result = await semanticSearchPhotos({ query: trimmed, limit: 60 });
      setSemanticResults(result);
      if (result && !result.available) {
        setSemanticError(semanticSearchUnavailableMessage(result.reason, uiText));
      } else if (result && result.results.length === 0 && (result.missingEmbeddings || 0) > 0) {
        setSemanticError(
          result.queued
            ? uiText("Semantic indexing is queued. Try this search again after the background job finishes.")
            : uiText("Semantic indexing has not finished for this library yet.")
        );
      } else if (result && result.results.length === 0) {
        setSemanticError(uiText("No semantic matches in this library yet."));
      }
    } catch (error) {
      setSemanticResults(null);
      setSemanticError(errorMessage(error));
    } finally {
      setSemanticBusy(false);
    }
  }

  async function openSemanticResult(sourcePath: string, timestampMs?: number) {
    if (Number.isFinite(timestampMs)) {
      pendingLightboxVideoSeekRef.current = {
        sourcePath,
        timestampMs: Math.max(0, Math.round(Number(timestampMs) || 0)),
      };
    } else pendingLightboxVideoSeekRef.current = null;
    const index = items.findIndex((entry) => entry.sourcePath === sourcePath);
    if (index >= 0) {
      setLightbox(index);
      return;
    }
    setSemanticError("");
    try {
      const page = await itemsFnRef.current({
        folderId: "all",
        offset: 0,
        limit: 1,
        previewBudget: 1,
        sort: "filename",
        sourcePaths: [sourcePath],
        detectMissingOriginals: true,
      });
      const match = (page.items || []).find((entry) => entry.sourcePath === sourcePath);
      if (match) {
        setItems((current) => [match, ...current.filter((entry) => entry.sourcePath !== sourcePath)]);
        setLightbox(0);
        return;
      }
    } catch (error) {
      setSemanticError(errorMessage(error));
    }
    if (pendingLightboxVideoSeekRef.current?.sourcePath === sourcePath) {
      pendingLightboxVideoSeekRef.current = null;
    }
    void window.crossAge.revealPath(sourcePath).catch(() => undefined);
  }

  function startSubjectCutoutFileDrag(event: ReactDragEvent<HTMLElement>, target: PhotoSubjectCutoutExportValue | null) {
    const targetPath = target?.targetPath || "";
    if (!targetPath) {
      event.preventDefault();
      setVideoFrameExportError(uiText("Export a subject PNG before dragging it."));
      return;
    }
    event.dataTransfer.effectAllowed = "copy";
    event.dataTransfer.setData("text/plain", targetPath);
    event.dataTransfer.setData("DownloadURL", `image/png:${fileName(targetPath)}:${targetPath}`);
    void startFileDrag(targetPath).then((result) => {
      if (result && !result.ok) {
        setVideoFrameExportError(result.error || uiText("Could not start dragging this subject PNG."));
      }
    });
  }

