  function onLightboxWheel(event: ReactWheelEvent<HTMLDivElement>) {
    event.preventDefault();
    event.stopPropagation();
    setLightboxZoomLevel((value) => value + (event.deltaY < 0 ? 0.18 : -0.18));
  }

  function onLightboxPointerDown(event: ReactPointerEvent<HTMLDivElement>) {
    event.preventDefault();
    event.stopPropagation();
    if (imageWhiteBalancePickerActive) {
      sampleLightboxWhiteBalance(event);
      return;
    }
    if (pickImageRetouchCloneSource(event)) return;
    if (beginImageRetouchBrushDraw(event)) return;
    if (beginImageMarkupStrokeDraw(event)) return;
    if (beginImageManualCropOverlayDrag(event)) return;
    if (beginImageMarkupOverlayDrag(event)) return;
    event.currentTarget.setPointerCapture(event.pointerId);
    lightboxPointersRef.current.set(event.pointerId, { x: event.clientX, y: event.clientY });
    if (lightboxPointersRef.current.size >= 2) {
      beginLightboxPinch();
      return;
    }
    if (lightboxZoom <= 1) return;
    lightboxDragRef.current = {
      pointerId: event.pointerId,
      startX: event.clientX,
      startY: event.clientY,
      originX: lightboxPan.x,
      originY: lightboxPan.y,
    };
    setLightboxDragging(true);
  }

  function onLightboxPointerMove(event: ReactPointerEvent<HTMLDivElement>) {
    if (updateImageRetouchBrushDraw(event)) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }
    if (updateImageMarkupStrokeDraw(event)) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }
    if (updateImageManualCropOverlayDrag(event)) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }
    if (updateImageMarkupOverlayDrag(event)) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }
    if (lightboxPointersRef.current.has(event.pointerId)) {
      lightboxPointersRef.current.set(event.pointerId, { x: event.clientX, y: event.clientY });
    }
    const pinch = lightboxPinchRef.current;
    if (pinch && lightboxPointersRef.current.size >= 2) {
      const transform = lightboxPinchTransform(pinch, lightboxGesturePoints(lightboxPointersRef.current.values()));
      if (!transform) return;
      event.preventDefault();
      event.stopPropagation();
      setLightboxZoom(transform.zoom);
      setLightboxPan(transform.pan);
      return;
    }
    const drag = lightboxDragRef.current;
    if (!drag || drag.pointerId !== event.pointerId) return;
    event.preventDefault();
    event.stopPropagation();
    setLightboxPan(lightboxDragPan(drag, { x: event.clientX, y: event.clientY }));
  }

  function endLightboxPointer(event: ReactPointerEvent<HTMLDivElement>) {
    if (endImageRetouchBrushDraw(event)) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }
    if (endImageMarkupStrokeDraw(event)) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }
    if (endImageManualCropOverlayDrag(event)) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }
    if (endImageMarkupOverlayDrag(event)) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }
    const drag = lightboxDragRef.current;
    if (drag && drag.pointerId === event.pointerId && event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
    lightboxPointersRef.current.delete(event.pointerId);
    if (lightboxPointersRef.current.size < 2) lightboxPinchRef.current = null;
    if (!drag || drag.pointerId === event.pointerId) {
      lightboxDragRef.current = null;
      setLightboxDragging(false);
    }
  }

  async function finishImport(result: PhotoImportResult | null, preferredActiveId = "") {
    if (!result) return;
    setImportError("");
    const importWarningRows = [...(result.warnings || [])];
    if (result.keepFolderOrganizationSource === "root-default" && result.keepFolderOrganization) {
      importWarningRows.unshift({
        code: "managed-folders-kept-by-default",
        message: "Source folder structure was kept using this managed library's default policy.",
      });
    }
    setImportWarnings(importWarningRows);
    setImportFailureDetails(result.failures || []);
    setSelectedSources(new Set());
    await loadFolders();
    await loadSuggestions();
    if (preferredActiveId) {
      setPhotoDateViewMode("all");
      setActiveDateBucketKey("");
      setActiveId(preferredActiveId);
      return;
    }
    if (result.importId) {
      setPhotoDateViewMode("all");
      setActiveDateBucketKey("");
      setActiveId(`import:${result.importId}`);
      return;
    }
    loadPage(currentPageRequest({ offset: 0 }));
  }

  async function addPendingImportToAlbum(result: PhotoImportResult | null): Promise<string> {
    const albumDraft = photoImportAlbumAttachDraft({
      result,
      targetId: pendingImportAlbumTargetId,
      newAlbumName: pendingImportAlbumName,
    });
    if (!albumDraft) return "";
    let albumId = albumDraft.albumId;
    if (albumDraft.createAlbum) {
      const savedAlbum = await savePhotoAlbum(albumDraft.createAlbum);
      const value = savedAlbum.value && typeof savedAlbum.value === "object" ? savedAlbum.value as { albumId?: unknown } : {};
      albumId = String(value.albumId || "").trim();
    }
    if (!albumId) throw new Error(uiText("Album was not created"));
    await addPhotoAlbumItems({ albumId, sourcePaths: albumDraft.sourcePaths });
    return albumId;
  }

  function removeRecoveredFailureFromState(failureId: string) {
    setRecoveredFailures((current) => current.filter((item) => item.failureId !== failureId));
    setPhotoRepairRecoveredCount((count) => Math.max(0, count - 1));
  }

  async function dismissRecoveredFailure(failure: PhotoImportFailure) {
    const failureId = String(failure.failureId || "");
    if (!failureId) return;
    setDismissingRecoveredFailureId(failureId);
    setRecoveredFailuresError("");
    try {
      await props.dismissPhotoImportFailure({ failureId });
      removeRecoveredFailureFromState(failureId);
      await loadFolders();
    } catch (error) {
      setRecoveredFailuresError(errorMessage(error));
    } finally {
      setDismissingRecoveredFailureId("");
    }
  }

  async function retryRecoveredFailure(failure: PhotoImportFailure) {
    const failureId = String(failure.failureId || "");
    if (!failureId) return;
    setRetryingRecoveredFailureId(failureId);
    setRecoveredFailuresError("");
    try {
      const result = await retryPhotoImportFailure({ failureId });
      removeRecoveredFailureFromState(failureId);
      const importResult = result.value?.importResult || null;
      if (importResult) {
        await finishImport(importResult);
      } else {
        await loadFolders();
        await loadRecoveredFailures();
      }
    } catch (error) {
      setRecoveredFailuresError(errorMessage(error));
    } finally {
      setRetryingRecoveredFailureId("");
    }
  }

  async function saveRecoveredFailure(failure: PhotoImportFailure) {
    const failureId = String(failure.failureId || "");
    if (!failureId) return;
    setSavingRecoveredFailureId(failureId);
    setRecoveredFailuresError("");
    try {
      const result = await saveRecoveredPhotoImportFailure({ failureId, storageMode: "managed" });
      removeRecoveredFailureFromState(failureId);
      const importResult = result.value?.importResult || null;
      if (importResult) {
        await finishImport(importResult);
      } else {
        await loadFolders();
        await loadRecoveredFailures();
      }
    } catch (error) {
      setRecoveredFailuresError(errorMessage(error));
    } finally {
      setSavingRecoveredFailureId("");
    }
  }

  async function deleteRecoveredFailure(failure: PhotoImportFailure) {
    const failureId = String(failure.failureId || "");
    if (!failureId) return;
    if (!await confirmPhotoAction({
      title: uiText("Delete recovered file"),
      message: uiText("Delete this recovered file from disk? This cannot be undone."),
      confirmLabel: uiText("Delete file"),
    })) return;
    setDeletingRecoveredFailureId(failureId);
    setRecoveredFailuresError("");
    try {
      await deleteRecoveredPhotoImportFailure({ failureId });
      removeRecoveredFailureFromState(failureId);
      await loadFolders();
    } catch (error) {
      setRecoveredFailuresError(errorMessage(error));
    } finally {
      setDeletingRecoveredFailureId("");
    }
  }

  async function scanRecoveredOrphans(options: { dryRun?: boolean } = {}) {
    const dryRun = Boolean(options.dryRun);
    const libraryRoot = activeLibraryRootRef.current;
    const libraryRootProfileId = activeLibraryRootProfileIdRef.current;
    setRecoveredOrphanScanning(true);
    setRecoveredOrphanScanMode(dryRun ? "preview" : "record");
    setRecoveredFailuresError("");
    setRecoveredOrphanScanStatus("");
    try {
      const result = await scanPhotoRecoveredOrphans({ limit: 500, dryRun, libraryRoot, libraryRootProfileId });
      const value = result.value;
      const recorded = Number(value?.recorded || 0);
      const candidates = Number(value?.orphanCandidates || 0);
      const scanned = Number(value?.scannedFiles || 0);
      if (dryRun) {
        setRecoveredOrphanScanStatus(candidates > 0
          ? `${uiText("Preview found")} ${candidates} ${candidates === 1 ? uiText("recovered file") : uiText("recovered files")}. ${uiText("Scan orphans to add them to Recovered.")}`
          : `${uiText("Preview found no orphan files.")} ${scanned ? `(${scanned} ${uiText("scanned")})` : ""}`.trim()
        );
      } else {
        setRecoveredOrphanScanStatus(recorded > 0
          ? `${uiText("Found")} ${recorded} ${recorded === 1 ? uiText("recovered file") : uiText("recovered files")}.`
          : `${uiText("No orphan files found.")} ${scanned ? `(${scanned} ${uiText("scanned")})` : ""}`.trim()
        );
        await loadRecoveredFailures();
        await loadFolders();
      }
    } catch (error) {
      setRecoveredFailuresError(errorMessage(error));
    } finally {
      setRecoveredOrphanScanning(false);
      setRecoveredOrphanScanMode("");
    }
  }

  async function cleanupRecoveredOrphans(apply = false, deleteRecoveredFiles = false) {
    const libraryRoot = activeLibraryRootRef.current;
    const libraryRootProfileId = activeLibraryRootProfileIdRef.current;
    if (apply && !(await confirmPhotoAction({
      title: deleteRecoveredFiles ? uiText("Purge old recovered files") : uiText("Clean Recovered"),
      message: deleteRecoveredFiles
        ? uiText("Dismiss stale orphan rows, purge old dismissed orphan records, and delete old recovered files eligible for cleanup? This cannot be undone.")
        : uiText("Dismiss stale orphan rows whose files are gone or already saved, and purge old dismissed orphan records? Recovered files will stay on disk."),
      confirmLabel: deleteRecoveredFiles ? uiText("Purge old files") : uiText("Clean Recovered"),
      danger: deleteRecoveredFiles,
    }))) return;
    setRecoveredCleanupRunning(true);
    setRecoveredFailuresError("");
    setRecoveredCleanupStatus("");
    try {
      const result = await photoRecoveredCleanup({
        apply,
        retentionDays: 30,
        deleteRecoveredFiles,
        sampleLimit: 8,
        libraryRoot,
        libraryRootProfileId,
      });
      const counts = result.value?.counts || {};
      const candidates = Number(counts.cleanupCandidates || 0);
      const fileDeleteCandidates = Number(counts.fileDeleteCandidates || 0);
      const dismissed = Number(counts.rowsDismissed || 0);
      const purged = Number(counts.rowsDeleted || 0);
      const filesDeleted = Number(counts.filesDeleted || 0);
      const fileDeleteFailures = Number(counts.fileDeleteFailures || 0);
      setRecoveredCleanupStatus(apply
        ? deleteRecoveredFiles
          ? `${uiText("Recovered cleanup")} ${uiText("dismissed")} ${dismissed}, ${uiText("purged")} ${purged}, ${uiText("deleted")} ${filesDeleted} ${filesDeleted === 1 ? uiText("file") : uiText("files")}.${fileDeleteFailures ? ` ${fileDeleteFailures} ${uiText("file delete failures")}.` : ""}`
          : `${uiText("Recovered cleanup")} ${uiText("dismissed")} ${dismissed}, ${uiText("purged")} ${purged}.`
        : candidates > 0
          ? `${uiText("Cleanup preview found")} ${candidates} ${candidates === 1 ? uiText("stale row") : uiText("stale rows")}.${fileDeleteCandidates ? ` ${fileDeleteCandidates} ${fileDeleteCandidates === 1 ? uiText("old recovered file") : uiText("old recovered files")} ${uiText("eligible for deletion")}.` : ""}`
          : uiText("Cleanup preview found no stale Recovered rows.")
      );
      await loadPhotoRepairHistory();
      if (apply) {
        await loadRecoveredFailures();
        await loadFolders();
      }
    } catch (error) {
      setRecoveredFailuresError(errorMessage(error));
    } finally {
      setRecoveredCleanupRunning(false);
    }
  }

