  function activeLibraryScopeMatches(rootPath: string, profileId = "") {
    const nextRoot = String(rootPath || "").trim();
    const nextProfileId = String(profileId || "").trim();
    return Boolean(nextProfileId && activeLibraryRootProfileId === nextProfileId)
      || Boolean(nextRoot && activeLibraryRoot === nextRoot)
      || (!nextRoot && !activeLibraryRoot);
  }

  function applyPhotoLibraryScopeState(rootPath: string, profileId = "") {
    const nextRoot = String(rootPath || "").trim();
    const nextProfileId = String(profileId || "").trim();
    activeLibraryRootRef.current = nextRoot;
    activeLibraryRootProfileIdRef.current = nextProfileId;
    setActiveLibraryRoot(nextRoot);
    setActiveLibraryRootProfileId(nextProfileId);
    setLightboxVideoMuted(shouldMuteAutoplayPhotoVideo(photoEffectiveMediaSettings(photoSettingsRef.current, nextRoot)));
    setSelectedSources(new Set());
    setLightbox(null);
    setActiveDateBucketKey("");
    setDateBucketRefreshToken((token) => token + 1);
    setLibrarySearchResult(null);
    setLibrarySearchError("");
    void loadFolders();
    if (peopleManagementOpen) void loadPeopleManagementFolders({ full: true });
  }

  function setPhotoLibraryScope(rootPath: string, profileId = "") {
    const nextRoot = String(rootPath || "").trim();
    const nextProfileId = String(profileId || "").trim();
    applyPhotoLibraryScopeState(nextRoot, nextProfileId);
    setPhotoLibraryProfileError("");
    void savePhotoLibrarySettings({ activeLibraryRoot: nextRoot, activeLibraryRootProfileId: nextProfileId })
      .then((result) => setPhotoLibraryProfile(result.value || null))
      .catch((error) => setPhotoLibraryProfileError(errorMessage(error)));
  }

