  async function persistPhotoCurationPreferences(next: PhotoCurationPreferencesValue) {
    const normalized = normalizePhotoCurationPreferences(next);
    setPhotoCurationSaving(true);
    setPhotoCurationError("");
    try {
      const result = await savePhotoCurationPreferences({
        ...(normalized as unknown as Record<string, unknown>),
        libraryRoot: activeLibraryRootRef.current,
        libraryRootProfileId: activeLibraryRootProfileIdRef.current,
      });
      const savedPreferences = normalizePhotoCurationPreferences(result.value || normalized);
      setPhotoCurationPreferencesValue(savedPreferences);
      const favoriteMemoryIds = new Set(savedPreferences.favoriteMemories);
      const hiddenMemoryIds = new Set(savedPreferences.hiddenMemories);
      setFolders((current) => current
        .filter((folder) => {
          if (folder.kind !== "memory") return true;
          const memoryId = folder.memoryId || folder.memory?.memoryId || "";
          return !memoryId || !hiddenMemoryIds.has(memoryId);
        })
        .map((folder) => {
          if (folder.kind !== "memory" || !folder.memory) return folder;
          const memoryId = folder.memoryId || folder.memory?.memoryId || "";
          return {
            ...folder,
            memory: {
              ...(folder.memory || {}),
              favorite: Boolean(memoryId && favoriteMemoryIds.has(memoryId)),
            },
          };
        }));
      setDateBucketRefreshToken((token) => token + 1);
      // Partial interactive catalogs intentionally omit expensive generated
      // collections and would preserve stale Memory cards. The saved preference
      // set drives the immediate surface; full enrichment reconciles composition.
      void ensureFolderEnrichment();
    } catch (error) {
      setPhotoCurationError(errorMessage(error));
    } finally {
      setPhotoCurationSaving(false);
    }
  }

  async function togglePhotoFeatureLessSuggestion(suggestion: PhotoFeatureLessSuggestion) {
    const next = suggestion.active
      ? removePhotoCurationPreference(photoCurationPreferencesValue, suggestion.kind, suggestion.value)
      : addPhotoCurationPreference(photoCurationPreferencesValue, suggestion.kind, suggestion.value);
    await persistPhotoCurationPreferences(next);
  }

  async function toggleMemoryFeatureLessSuggestion(suggestion: PhotoFeatureLessSuggestion, folder: PhotoFolder | null = activeMemory) {
    await togglePhotoFeatureLessSuggestion(suggestion);
    const memoryId = folder?.memoryId || folder?.memory?.memoryId || "";
    if (!suggestion.active && memoryId && (activeId === folder?.id || activeMemoryId === memoryId)) {
      setActiveId("memories");
      refreshCurrentPhotoPage("memories");
    }
  }

