  async function toggleMemoryFavorite(folder: PhotoFolder | null = activeMemory) {
    const memoryId = folder?.memoryId || folder?.memory?.memoryId || "";
    if (!memoryId) return;
    const currentFavorite = photoMemoryPreferenceActive(photoCurationPreferencesValue, "favoriteMemories", memoryId) || Boolean(folder?.memory?.favorite);
    const nextFavorite = !currentFavorite;
    await persistPhotoCurationPreferences(setPhotoMemoryPreference(photoCurationPreferencesValue, "favoriteMemories", memoryId, nextFavorite));
  }

