    const memoryId = folder?.memoryId || folder?.memory?.memoryId || "";
    if (!memoryId) return;
    await persistPhotoCurationPreferences(setPhotoMemoryPreference(photoCurationPreferencesValue, "hiddenMemories", memoryId, true));
    if (activeId === folder?.id) setActiveId("memories");
