  async function createUserMemoryFromCurrentView() {
    setUserMemorySaving(true);
    setUserMemoryError("");
    try {
      const queueSourceItems = selectedSources.size ? items : await loadCurrentSlideshowItems();
      const sourcePaths = photoSlideshowProjectSourcePaths(queueSourceItems, selectedSources.size ? selectedSources : undefined);
      const memoryDraft = photoUserMemoryCreateDraft({
        sourcePaths,
        nameDraft: userMemoryNameDraft,
        defaultName: userMemorySource.defaultName,
        activeName: active?.name,
        sourceLabel: userMemorySource.sourceLabel,
        selected: selectedSources.size > 0,
        labels: {
          memory: uiText("Memory"),
          selection: uiText("Selection"),
          currentView: uiText("Current view"),
        },
      });
      if (!memoryDraft) {
        setUserMemoryError(uiText("Choose at least two visible photos for a memory."));
        return;
      }
      const result = await savePhotoUserMemory({
        ...memoryDraft,
        libraryRoot: activeLibraryRootRef.current,
        libraryRootProfileId: activeLibraryRootProfileIdRef.current,
      });
      const savedMemoryId = result.value?.memoryId || "";
      await photoUserMemories({});
      await loadFolders();
      setUserMemoryNameDraft("");
      setSelectedSources(new Set());
      if (savedMemoryId) {
        setActiveId(`memory:${savedMemoryId}`);
        refreshCurrentPhotoPage(`memory:${savedMemoryId}`);
      }
    } catch (error) {
      setUserMemoryError(errorMessage(error));
    } finally {
      setUserMemorySaving(false);
    }
  }

