  async function stagePendingImport(paths: string[], label: string, options: { sourceKind?: PhotoImportSourceKind; sourceDetail?: string; sourceLabelExplicit?: boolean } = {}) {
    if (!paths.length) return;
    setImportingPhotos(true);
    setImportError("");
    setImportWarnings([]);
    setImportFailureDetails([]);
    try {
      const prepared = await prepareImportPaths(paths);
      const entries = prepared
        .map((entry) => ({
          path: String(entry.path || ""),
          isDir: Boolean(entry.isDir),
          sourceKind: entry.sourceKind ? normalizeExternalPhotoImportSourceKind(entry.sourceKind) : undefined,
          sourceLabel: typeof entry.sourceLabel === "string" ? entry.sourceLabel : undefined,
          sourceDetail: typeof entry.sourceDetail === "string" ? entry.sourceDetail : undefined,
        }))
        .filter((entry) => entry.path);
      const deduped = [...new Map(entries.map((entry) => [entry.path, entry])).values()];
      const reviewLabel = label === "Dropped files" && deduped.some((entry) => entry.isDir) ? "Dropped files/folders" : label;
      const reviewSummary = buildPhotoImportReviewSummary(deduped, reviewLabel);
      const attributionSummary = buildPhotoImportAttributionSummary(deduped, reviewLabel);
      const attributionSourceKind = attributionSummary.sourceKind !== "folder" ? photoImportSourceKindFromInference(attributionSummary.sourceKind) : "folder";
      const inferredSourceKind = attributionSourceKind !== "folder" ? attributionSourceKind : photoImportSourceKindFromInference(reviewSummary.inferredSourceKind);
      const requestedSourceKind = options.sourceKind || importSourceKind;
      const nextSourceKind = requestedSourceKind === "folder" && inferredSourceKind !== "folder" ? inferredSourceKind : requestedSourceKind;
      const nextSourceLabel = options.sourceLabelExplicit
        ? reviewLabel
        : nextSourceKind !== "folder"
          ? (attributionSummary.sourceLabel || reviewSummary.sourceLabel || reviewLabel)
          : reviewLabel;
      setImportSourceKind(nextSourceKind);
      setPendingImportEntries(deduped);
      setPendingImportLabel(nextSourceLabel);
      setPendingImportSourceLabelExplicit(Boolean(options.sourceLabelExplicit && nextSourceLabel.trim()));
      if (options.sourceDetail !== undefined) {
        setImportSourceDetail(options.sourceDetail);
      } else if (!(pendingImportEntries.length ? "" : importSourceDetail).trim() && attributionSummary.sourceDetail) {
        setImportSourceDetail(attributionSummary.sourceDetail);
      } else if (pendingImportEntries.length && !attributionSummary.sourceDetail) {
        setImportSourceDetail("");
      }
    } catch (error) {
      setImportError(error instanceof Error ? error.message : String(error || "Import review failed."));
    } finally {
      setImportingPhotos(false);
    }
  }

  async function confirmPendingImport() {
    const sourcePaths = pendingImportEntries.map((entry) => entry.path).filter(Boolean);
    if (!sourcePaths.length) return;
    setImportingPhotos(true);
    setImportError("");
    setImportWarnings([]);
    setImportFailureDetails([]);
    try {
      const hasFolder = pendingImportEntries.some((entry) => entry.isDir);
      const inferredSourceKind = photoImportSourceKindFromInference(pendingImportReviewSummary.inferredSourceKind);
      const effectiveSourceKind = importSourceKind === "folder" && inferredSourceKind !== "folder" ? inferredSourceKind : importSourceKind;
      const effectiveSourceLabel = pendingImportLabel || pendingImportReviewSummary.sourceLabel || (hasFolder ? "Imported folder" : "Imported files");
      const resolvedSourceLabel = photoImportSourceLabel(effectiveSourceKind, effectiveSourceLabel, pendingImportSourceLabelExplicit);
      const result = await importPhotos({
        sourcePaths,
        storageMode: importStorageMode,
        ...managedImportParams(),
        sourceKind: effectiveSourceKind,
        sourceLabel: resolvedSourceLabel,
        sourceDetail: importSourceDetail.trim(),
        keepFolderOrganization: importStorageMode === "managed" && importKeepFolderOrganization,
        deleteFromSourceAfterImport: false,
      });
      let targetAlbumId = "";
      let targetAlbumError = "";
      try {
        targetAlbumId = await addPendingImportToAlbum(result);
      } catch (albumError) {
        targetAlbumError = errorMessage(albumError);
      }
      setPendingImportEntries([]);
      setPendingImportLabel("");
      setPendingImportSourceLabelExplicit(false);
      setImportSourceDetail("");
      setPendingImportAlbumTargetId("");
      setPendingImportAlbumName("");
      await finishImport(result, targetAlbumId ? `album:${targetAlbumId}` : "");
      if (targetAlbumError) {
        setImportError(`${uiText("Imported, but album update failed")}: ${targetAlbumError}`);
      }
    } catch (error) {
      setImportError(error instanceof Error ? error.message : String(error || "Import failed."));
    } finally {
      setImportingPhotos(false);
    }
  }

  function removePendingImportEntry(path: string) {
    setPendingImportEntries((current) => current.filter((entry) => entry.path !== path));
  }

  function cancelPendingImport() {
    setPendingImportEntries([]);
    setPendingImportLabel("");
    setPendingImportSourceLabelExplicit(false);
    setImportSourceDetail("");
    setPendingImportAlbumTargetId("");
    setPendingImportAlbumName("");
  }

  async function importPickedFiles() {
    const paths = await chooseImportFiles();
    await stagePendingImport(paths, "Imported files");
  }

  async function importPickedFolder() {
    const folder = await chooseImportFolder();
    await stagePendingImport(folder ? [folder] : [], "Imported folder");
  }

  async function importSuggestedPhotoSource(source: SystemPhotoSource) {
    if (!source.available || !source.path) {
      setImportError(`${source.label || uiText("Photo source")} ${uiText("is not available on this computer.")}`);
      return;
    }
    // The whole-computer source opens a scope-consent sheet instead of the
    // per-folder staging review (the crawl is broad and needs explicit opt-in).
    if (source.kind === "this-computer") {
      setImportError("");
      setIndexEverythingSource(source);
      return;
    }
    const sourceKind = photoImportSourceKindForSystemSource(source) as PhotoImportSourceKind;
    const detail = [source.label, source.detail, source.path].filter(Boolean).join(" · ");
    await stagePendingImport([source.path], source.label || uiText("Photo source"), {
      sourceKind,
      sourceDetail: detail,
    });
  }

  // Run the whole-computer crawl: index every photo under the Home folder in
  // reference mode (originals stay put), pruning caches / app data / system files.
  async function runIndexEverything(source: SystemPhotoSource | null) {
    if (!source?.path) return;
    const sourcePaths = Array.from(new Set([source.path, ...indexEverythingExtraPaths].filter(Boolean)));
    setIndexEverythingRunning(true);
    setImportError("");
    try {
      const result = await importPhotos({
        sourcePaths,
        storageMode: "referenced",
        applyBroadExcludes: true,
        sourceKind: "folder",
        sourceLabel: sourcePaths.length > 1 ? uiText("This computer + folders") : uiText("This computer"),
        sourceDetail: sourcePaths.join(" · "),
      });
      // Auto-hide the noise a whole-computer crawl surfaces so the Library leads
      // with real photos; the rail toggles let the user bring them back.
      if (indexEverythingHideNoise) {
        setPhotoRailDisplayPreference("showScreenshotCollections", false);
        setPhotoRailDisplayPreference("showUtilityCollections", false);
        setPhotoRailDisplayPreference("showLowValueCollections", false);
      }
      setIndexEverythingSource(null);
      setIndexEverythingExtraPaths([]);
      await finishImport(result);
      if (result) {
        const added = result.importedCount;
        notifyToast(
          added > 0
            ? { tone: "ok", message: `${uiText("Added photos from this computer")}: ${formatCount(added)}.` }
            : { tone: "ok", message: uiText("No new photos found on this computer.") }
        );
      }
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      setImportError(message);
      notifyToast({ tone: "error", message: `${uiText("Couldn’t index this computer")}: ${message}` });
    } finally {
      setIndexEverythingRunning(false);
    }
  }

  // Open the scope-consent sheet from a CTA. If the Home source isn't detected
  // yet, ask the detector to refresh and open once it surfaces.
  function openIndexEverything() {
    setImportError("");
    setIndexEverythingExtraPaths([]);
    if (indexEverythingCandidate) {
      setIndexEverythingSource(indexEverythingCandidate);
      return;
    }
    setPendingIndexEverything(true);
    if (refreshPhotoSources) void refreshPhotoSources();
  }

  // Add another folder or drive to the whole-computer crawl scope.
  async function addIndexEverythingFolder() {
    const folder = await chooseImportFolder();
    const clean = String(folder || "").trim();
    if (!clean) return;
    setIndexEverythingExtraPaths((current) => {
      const home = indexEverythingSource?.path || "";
      if (clean === home || current.includes(clean)) return current;
      return [...current, clean];
    });
  }

  async function importDroppedFiles(files: File[]) {
    const paths = files.map((file) => getPathForFile(file)).filter(Boolean);
    if (!paths.length) return;
    await stagePendingImport(paths, "Dropped files");
  }

  async function copySelected() {
    const folder = await chooseDestinationFolder();
    if (!folder) return;
    const result = await exportPhotoSelection(selectedSourcePaths, "copy", folder);
    if (result) {
      setLastPhotoSelectionExport(result);
      rememberPhotoExportDestination(folder);
      await loadFolders();
    }
  }

  function photoExportColorProfileStatusParams() {
    return photoExportColorProfilePayload(exportTargetColorProfile, exportTargetColorProfilePath, exportPreserveColorProfile);
  }

  async function refreshPhotoExportColorProfileStatus() {
    setExportColorProfileStatusLoading(true);
    setExportColorProfileStatusError("");
    try {
      const result = await getPhotoColorProfileStatus(photoExportColorProfileStatusParams());
      const value = result.value || null;
      setExportColorProfileStatus(value);
      return value;
    } catch (error) {
      const message = errorMessage(error);
      setExportColorProfileStatus(null);
      setExportColorProfileStatusError(message);
      throw error;
    } finally {
      setExportColorProfileStatusLoading(false);
    }
  }

  async function ensurePhotoExportColorProfileAvailable(renderedExport: boolean) {
    if (!renderedExport) return true;
    if (exportTargetColorProfile === "custom-icc" && !exportTargetColorProfilePath.trim()) {
      setMetadataError(uiText("Choose an ICC profile before exporting."));
      return false;
    }
    if (
      exportTargetColorProfile === "custom-icc"
      && (!exportTargetColorProfileValidation || exportTargetColorProfileValidationError)
    ) {
      const valid = await validatePhotoExportColorProfilePath(exportTargetColorProfilePath);
      if (!valid) return false;
    }
    try {
      const status = await refreshPhotoExportColorProfileStatus();
      const selected = photoExportSelectedColorProfileStatus(status, exportTargetColorProfile);
      if (!selected?.available) {
        const label = selected?.label || exportTargetColorProfile;
        const reason = selected?.error || uiText("Choose another target profile before exporting.");
        setMetadataError(`${label} ${uiText("is unavailable")}: ${reason}`);
        return false;
      }
      return true;
    } catch (error) {
      setMetadataError(`${uiText("Profile availability check failed")}: ${errorMessage(error)}`);
      return false;
    }
  }

  function currentPhotoSelectionExportOptions() {
    return photoSelectionExportOptionsPayload({
      includeMetadata: exportIncludeMetadata,
      includeXmp: exportIncludeXmp,
      includeExistingSidecars: exportIncludeExistingSidecars,
      stripLocation: exportStripLocation,
      preserveColorProfile: exportPreserveColorProfile,
      targetColorProfile: exportTargetColorProfile,
      targetColorProfilePath: exportTargetColorProfilePath,
      layout: exportLayout,
      filenameMode: exportFilenameMode,
      filenameTemplate: exportFilenameTemplate,
      subfolderTemplate: exportSubfolderTemplate,
      exportVariant,
      renderFormat: exportRenderFormat,
      renderQuality: exportRenderQuality,
      renderMaxDimension: effectiveExportRenderMaxDimensionNumber,
      videoRenderFormat: exportVideoRenderFormat,
      videoRenderQuality: exportVideoRenderQuality,
    });
  }

  async function exportSelected(folder = "") {
    if (!(await ensurePhotoExportColorProfileAvailable(exportVariant === "rendered"))) return;
    const result = await exportPhotoSelection(selectedSourcePaths, "export", folder || undefined, currentPhotoSelectionExportOptions());
    if (result && exportShareAfterExport) {
      const targetPaths = photoSelectionExportTargetPaths(result);
      if (targetPaths.length) await sharePaths(targetPaths);
    }
    if (result) {
      setLastPhotoSelectionExport(result);
      if (folder) rememberPhotoExportDestination(folder);
      await loadFolders();
      // P1 toast-notice: a transient confirmation for a completed export (the
      // lastPhotoSelectionExport panel is the persistent detail summary).
      const exportedCount = result.items?.length ?? 0;
      notifyToast({ tone: "ok", message: `${uiText("Exported photos")}: ${formatCount(exportedCount)}.` });
    }
  }

  async function validatePhotoExportColorProfilePath(profilePath: string) {
    const cleanPath = profilePath.trim();
    setExportTargetColorProfileValidation(null);
    setExportTargetColorProfileValidationError("");
    if (!cleanPath) {
      setMetadataError(uiText("Choose an ICC profile before exporting."));
      return false;
    }
    try {
      const validation = await validatePhotoColorProfile({ path: cleanPath });
      setExportTargetColorProfileValidation(validation.value || null);
      setMetadataError("");
      return true;
    } catch (error) {
      const message = errorMessage(error);
      setExportTargetColorProfileValidation(null);
      setExportTargetColorProfileValidationError(message);
      setMetadataError(message);
      return false;
    }
  }

  async function choosePhotoExportColorProfileFile() {
    try {
      const picked = await chooseColorProfileFile();
      if (!picked?.path) return;
      setExportTargetColorProfilePath(picked.path);
      setExportTargetColorProfile("custom-icc");
      setExportPreserveColorProfile(true);
      setMetadataError("");
      await validatePhotoExportColorProfilePath(picked.path);
    } catch (error) {
      const message = errorMessage(error);
      setExportTargetColorProfileValidation(null);
      setExportTargetColorProfileValidationError(message);
      setMetadataError(message);
    }
  }

  async function copySelectedToPhotoExportDestination() {
    if (!photoExportDestinationPath) return;
    const result = await exportPhotoSelection(selectedSourcePaths, "copy", photoExportDestinationPath);
    if (result) {
      setLastPhotoSelectionExport(result);
      rememberPhotoExportDestination(photoExportDestinationPath);
      await loadFolders();
    }
  }

  function rememberPhotoExportDestination(folder: string) {
    const pathText = String(folder || "").trim();
    if (!pathText) return;
    const next = normalizePhotoExportDestinations([pathText, ...photoExportDestinations]);
    setPhotoExportDestinations(next);
    setPhotoExportDestinationPath(pathText);
    storePhotoExportDestinations(PHOTO_EXPORT_DESTINATIONS_KEY, next);
  }

  function forgetPhotoExportDestination(folder: string) {
    const pathText = String(folder || "").trim();
    if (!pathText) return;
    const next = normalizePhotoExportDestinations(photoExportDestinations.filter((item) => item !== pathText));
    setPhotoExportDestinations(next);
    setPhotoExportDestinationPath((current) => current === pathText ? next[0] || "" : current);
    storePhotoExportDestinations(PHOTO_EXPORT_DESTINATIONS_KEY, next);
  }

  function applyPhotoExportPresetSettings(settings: PhotoExportPresetSettings) {
    const next = normalizePhotoExportPresetSettings(settings);
    setExportIncludeMetadata(next.includeMetadata);
    setExportIncludeXmp(next.includeXmp);
    setExportIncludeExistingSidecars(next.includeExistingSidecars);
    setExportStripLocation(next.stripLocation);
    setExportPreserveColorProfile(next.preserveColorProfile);
    setExportTargetColorProfile(next.targetColorProfile);
    setExportTargetColorProfilePath(next.targetColorProfile === "custom-icc" ? next.targetColorProfilePath : "");
    setExportTargetColorProfileValidation(null);
    setExportTargetColorProfileValidationError("");
    setExportShareAfterExport(next.shareAfterExport);
    setExportLayout(next.layout);
    setExportFilenameMode(next.filenameMode);
    setExportFilenameTemplate(next.filenameTemplate);
    setExportSubfolderTemplate(next.subfolderTemplate);
    setExportVariant(next.exportVariant);
    setExportRenderFormat(next.renderFormat);
    setExportRenderQuality(next.renderQuality);
    setExportRenderSizePreset(next.renderSizePreset);
    setExportRenderMaxDimension(next.renderMaxDimension);
    setExportVideoRenderFormat(next.videoRenderFormat);
    setExportVideoRenderQuality(next.videoRenderQuality);
    setContactSheetFormat(next.contactSheetFormat);
    setContactSheetTitle(next.contactSheetTitle);
    setContactSheetCaptionPreset(next.contactSheetCaptionPreset);
    setContactSheetPageSize(next.contactSheetPageSize);
    setContactSheetLayout(next.contactSheetLayout);
    setContactSheetColumns(next.contactSheetColumns);
    setContactSheetThumbnailSize(next.contactSheetThumbnailSize);
    setContactSheetIncludeCaptions(next.contactSheetIncludeCaptions);
  }

  function applyPhotoProjectBundlePreset() {
    applyPhotoExportPresetSettings(photoProjectBundlePresetSettings());
    setPhotoExportPresetId("");
    setPhotoExportPresetName(uiText("Project bundle"));
  }

  function applyPhotoCreationExportPreset(kind: PhotoCreationExportPresetKind) {
    const preset = PHOTO_CREATION_EXPORT_PRESETS.find((item) => item.kind === kind);
    applyPhotoExportPresetSettings(photoCreationExportPresetSettings(kind));
    setPhotoExportPresetId("");
    setPhotoExportPresetName(uiText(preset?.label || "Creation preset"));
  }

  function applyPhotoCreationExportSuggestion(suggestion: PhotoCreationExportSuggestion) {
    applyPhotoExportPresetSettings(suggestion.settings);
    setPhotoExportPresetId("");
    setPhotoExportPresetName(uiText(suggestion.label));
    setSelectedSources(new Set(suggestion.sourcePaths));
  }

  function persistPhotoExportPresets(next: PhotoExportPreset[]) {
    const normalized = normalizePhotoExportPresetList(next);
    setPhotoExportPresets(normalized);
    storePhotoExportPresets(PHOTO_EXPORT_PRESETS_KEY, normalized);
    return normalized;
  }

  function saveCurrentPhotoExportPreset() {
    const name = photoExportPresetName.trim() || selectedPhotoExportPreset?.name || "";
    if (!name) return;
    const next = persistPhotoExportPresets(upsertPhotoExportPreset(photoExportPresets, {
      id: selectedPhotoExportPreset?.id,
      name,
      settings: currentPhotoExportPresetSettings,
    }));
    const saved = next.find((preset) => preset.name.toLocaleLowerCase() === name.toLocaleLowerCase()) || next[0];
    setPhotoExportPresetId(saved?.id || "");
    setPhotoExportPresetName(saved?.name || name);
  }

  function applySelectedPhotoExportPreset() {
    if (!selectedPhotoExportPreset) return;
    applyPhotoExportPresetSettings(selectedPhotoExportPreset.settings);
    setPhotoExportPresetName(selectedPhotoExportPreset.name);
  }

  function deleteSelectedPhotoExportPreset() {
    if (!selectedPhotoExportPreset) return;
    persistPhotoExportPresets(deletePhotoExportPreset(photoExportPresets, selectedPhotoExportPreset.id));
    setPhotoExportPresetId("");
    setPhotoExportPresetName("");
  }

  function commitPhotoSlideshowThemeTemplates(next: PhotoSlideshowThemeTemplate[]) {
    const normalized = normalizePhotoSlideshowThemeTemplateList(next);
    setPhotoSlideshowThemeTemplates(normalized);
    storePhotoSlideshowThemeTemplates(PHOTO_SLIDESHOW_THEME_TEMPLATES_KEY, normalized);
    return normalized;
  }

  function applyPhotoSlideshowThemeTemplate(template: PhotoSlideshowThemeTemplate | null = selectedPhotoSlideshowThemeTemplate) {
    if (!template) return;
    applyPhotoSlideshowThemeSettings(photoSlideshowThemeTemplateSettings(template));
    setPhotoSlideshowThemeTemplateId(template.id);
    setPhotoSlideshowProjectTransitionEffect(template.transitionEffect || "auto");
    setPhotoSlideshowProjectTransitionDurationMs(template.transitionEffect === "cut" ? 0 : Math.max(0, Math.min(3000, template.transitionDurationMs ?? 650)));
    setPhotoSlideshowProjectIncludeTitleCard(Boolean(template.includeTitleCard));
    setPhotoSlideshowProjectTitleCardPalette(template.titleCardPalette || "auto");
    setPhotoSlideshowProjectTitleCardLayout(template.titleCardLayout || "center");
    setPhotoSlideshowProjectTitleCardFontScale(template.titleCardFontScale || "regular");
    setPhotoSlideshowProjectTitleCardShowFooter(template.titleCardShowFooter !== false);
  }

  async function saveCurrentPhotoSlideshowThemeTemplate() {
    const name = photoSlideshowProjectThemeTemplateName.trim() || selectedPhotoSlideshowThemeTemplate?.name || photoSlideshowProjectTitle.trim() || uiText("Template");
    if (!name) return;
    const draft = {
      id: selectedPhotoSlideshowThemeTemplate?.id,
      name,
      ...cleanPhotoSlideshowThemeSettings({
        ...currentPhotoSlideshowThemeSettings(),
        themeTemplateName: name,
      }),
      transitionEffect: photoSlideshowProjectTransitionEffect,
      transitionDurationMs: photoSlideshowProjectTransitionEffect === "cut" ? 0 : Math.max(0, Math.min(3000, photoSlideshowProjectTransitionDurationMs)),
      includeTitleCard: photoSlideshowProjectIncludeTitleCard,
      titleCardPalette: photoSlideshowProjectTitleCardPalette,
      titleCardLayout: photoSlideshowProjectTitleCardLayout,
      titleCardFontScale: photoSlideshowProjectTitleCardFontScale,
      titleCardShowFooter: photoSlideshowProjectTitleCardShowFooter,
    };
    setSlideshowLoading(true);
    setSlideshowError("");
    setSlideshowTemplateTransferMessage("");
    try {
      const result = await savePhotoSlideshowThemeTemplateFnRef.current(draft);
      const saved = normalizePhotoSlideshowThemeTemplate(result.value) || upsertPhotoSlideshowThemeTemplate(photoSlideshowThemeTemplates, draft)[0];
      const next = commitPhotoSlideshowThemeTemplates([
        saved,
        ...photoSlideshowThemeTemplates.filter((template) => template.id !== saved.id && template.name.toLocaleLowerCase() !== saved.name.toLocaleLowerCase()),
      ]);
      const selected = next.find((template) => template.id === saved.id) || saved;
      applyPhotoSlideshowThemeTemplate(selected);
    } catch (error) {
      setSlideshowError(errorMessage(error));
    } finally {
      setSlideshowLoading(false);
    }
  }

  async function deleteSelectedPhotoSlideshowThemeTemplate() {
    if (!selectedPhotoSlideshowThemeTemplate) return;
    const previous = photoSlideshowThemeTemplates;
    setSlideshowTemplateTransferMessage("");
    commitPhotoSlideshowThemeTemplates(deletePhotoSlideshowThemeTemplate(photoSlideshowThemeTemplates, selectedPhotoSlideshowThemeTemplate.id));
    setPhotoSlideshowThemeTemplateId("");
    try {
      await deletePhotoSlideshowThemeTemplateFnRef.current({ id: selectedPhotoSlideshowThemeTemplate.id });
    } catch (error) {
      commitPhotoSlideshowThemeTemplates(previous);
      setPhotoSlideshowThemeTemplateId(selectedPhotoSlideshowThemeTemplate.id);
      setSlideshowError(errorMessage(error));
    }
  }

  async function exportPhotoSlideshowThemeTemplateLibrary() {
    setSlideshowLoading(true);
    setSlideshowError("");
    setSlideshowTemplateTransferMessage("");
    try {
      const result = await exportPhotoSlideshowThemeTemplatesFnRef.current({});
      const value = result.value || {};
      const exported = value.exported ?? value.templateCount ?? value.templates?.length ?? 0;
      const targetPath = value.path || value.targetPath || "";
      setSlideshowTemplateTransferMessage(`${uiText("Exported templates")}: ${formatCount(exported)}`);
      if (targetPath) {
        await revealPath(targetPath);
      }
    } catch (error) {
      setSlideshowError(errorMessage(error));
    } finally {
      setSlideshowLoading(false);
    }
  }

  async function importPhotoSlideshowThemeTemplateLibrary() {
    setSlideshowError("");
    setSlideshowTemplateTransferMessage("");
    try {
      const picked = await props.chooseSlideshowTemplateLibraryFile();
      if (!picked?.path) return;
      setSlideshowLoading(true);
      const result = await importPhotoSlideshowThemeTemplatesFnRef.current({ path: picked.path });
      const value = result.value || {};
      const templates = normalizePhotoSlideshowThemeTemplateList(value.templates || []);
      if (templates.length || value.imported !== undefined) {
        commitPhotoSlideshowThemeTemplates(templates);
        if (photoSlideshowThemeTemplateId && !templates.some((template) => template.id === photoSlideshowThemeTemplateId)) {
          setPhotoSlideshowThemeTemplateId("");
        }
      } else {
        await loadPhotoSlideshowThemeTemplates();
      }
      setSlideshowTemplateTransferMessage(
        `${uiText("Imported templates")}: ${formatCount(value.imported || 0)} · `
        + `${uiText("Created")} ${formatCount(value.created || 0)} · `
        + `${uiText("Updated")} ${formatCount(value.updated || 0)} · `
        + `${uiText("Skipped")} ${formatCount(value.skipped || 0)}`
      );
    } catch (error) {
      setSlideshowError(errorMessage(error));
    } finally {
      setSlideshowLoading(false);
    }
  }

  function commitPhotoSlideshowProjects(next: PhotoSlideshowProject[]) {
    const normalized = normalizePhotoSlideshowProjectList(next);
    setPhotoSlideshowProjects(normalized);
    storePhotoSlideshowProjects(PHOTO_SLIDESHOW_PROJECTS_KEY, normalized);
    return normalized;
  }

