    setPhotoSlideshowProjectAudioFadeMs(projectDraft.audioFadeMs);
    setPhotoSlideshowProjectAudioStartMs(projectDraft.audioStartMs);
    setPhotoSlideshowProjectAudioEndMs(projectDraft.audioEndMs);
    setPhotoSlideshowProjectAudioPlacementStartSourcePath(projectDraft.audioPlacementStartSourcePath);
    setPhotoSlideshowProjectAudioPlacementEndSourcePath(projectDraft.audioPlacementEndSourcePath);
    setPhotoSlideshowProjectIncludeTitleCard(projectDraft.includeTitleCard);
    setPhotoSlideshowProjectTitleCardTitle(projectDraft.titleCardTitle);
    setPhotoSlideshowProjectTitleCardSubtitle(projectDraft.titleCardSubtitle);
