    setPhotoSlideshowProjectSlideMotion(projectDraft.slideMotion);
    setPhotoSlideshowProjectFocalX(projectDraft.focalX);
    setPhotoSlideshowProjectFocalY(projectDraft.focalY);
    setPhotoSlideshowProjectCropZoom(projectDraft.cropZoom);
    setPhotoSlideshowProjectCaptionLayer(projectDraft.captionLayer);
    resetPhotoSlideshowCaptionDraft(projectDraft.captionDraft);
    setPhotoSlideshowProjectSlideTransitionEffect(projectDraft.slideTransitionEffect);
    setPhotoSlideshowProjectSlideTransitionDurationMs(projectDraft.slideTransitionDurationMs);
    const keyframeDraft = projectDraft.keyframeDraft;
    setPhotoSlideshowProjectKeyframeStartX(keyframeDraft.startX);
    setPhotoSlideshowProjectKeyframeStartY(keyframeDraft.startY);
    setPhotoSlideshowProjectKeyframeQuarterX(keyframeDraft.quarterX);
    setPhotoSlideshowProjectKeyframeQuarterY(keyframeDraft.quarterY);
    setPhotoSlideshowProjectKeyframeMidX(keyframeDraft.midX);
    setPhotoSlideshowProjectKeyframeMidY(keyframeDraft.midY);
    setPhotoSlideshowProjectKeyframeThreeQuarterX(keyframeDraft.threeQuarterX);
