    setPhotoSlideshowProjectKeyframeQuarterZoom(keyframeDraft.quarterZoom);
    setPhotoSlideshowProjectKeyframeMidZoom(keyframeDraft.midZoom);
    setPhotoSlideshowProjectKeyframeThreeQuarterZoom(keyframeDraft.threeQuarterZoom);
    setPhotoSlideshowProjectKeyframeEndZoom(keyframeDraft.endZoom);
