    setPhotoSlideshowProjectBezierControl1X(keyframeDraft.bezierControl1X);
    setPhotoSlideshowProjectBezierControl1Y(keyframeDraft.bezierControl1Y);
    setPhotoSlideshowProjectBezierControl2X(keyframeDraft.bezierControl2X);
