  function commitPhotoSlideshowProjectSourceOrder(nextSourcePaths: string[]) {
    const cleanSourcePaths = cleanPhotoSlideshowSourcePaths(nextSourcePaths);
    if (!cleanSourcePaths.length) return;
    setPhotoSlideshowProjectOrderedSourcePaths(cleanSourcePaths);
    setPhotoSlideshowProjectTimelineItems((current) => cleanPhotoSlideshowTimelineItems(current, cleanSourcePaths, slideshowIntervalMs));
    setPhotoSlideshowProjectAudioPlacementStartSourcePath((sourcePath) => cleanSourcePaths.includes(sourcePath) ? sourcePath : "");
    setPhotoSlideshowProjectAudioPlacementEndSourcePath((sourcePath) => cleanSourcePaths.includes(sourcePath) ? sourcePath : "");
  }

  function resetPhotoSlideshowCaptionDraft(item?: PhotoSlideshowCaptionDraftLike | null) {
    setPhotoSlideshowProjectCaptionText(cleanPhotoSlideshowCaptionText(item?.captionText || ""));
    setPhotoSlideshowProjectCaptionPlacement(cleanPhotoSlideshowCaptionPlacement(item?.captionPlacement || "auto"));
    setPhotoSlideshowProjectCaptionRegionX(cleanPhotoSlideshowCaptionPercent(item?.captionRegion?.x, 6));
    setPhotoSlideshowProjectCaptionRegionY(cleanPhotoSlideshowCaptionPercent(item?.captionRegion?.y, 72));
    setPhotoSlideshowProjectCaptionRegionWidth(cleanPhotoSlideshowCaptionSizePercent(item?.captionRegion?.width, 42));
    setPhotoSlideshowProjectCaptionRegionHeight(cleanPhotoSlideshowCaptionSizePercent(item?.captionRegion?.height, 12));
    setPhotoSlideshowProjectCaptionTypography(cleanPhotoSlideshowCaptionTypography(item?.captionTypography || "auto"));
    setPhotoSlideshowProjectCaptionWrap(cleanPhotoSlideshowCaptionWrap(item?.captionWrap || "auto"));
    photoSlideshowCaptionRegionDragRef.current = null;
    setPhotoSlideshowCaptionRegionDragMode("");
  }

  function selectPhotoSlideshowProject(nextId: string) {
    const project = photoSlideshowProjects.find((item) => item.id === nextId) || null;
    setPhotoSlideshowProjectId(nextId);
    if (project) {
      applyPhotoSlideshowProject(project);
      return;
    }
    setPhotoSlideshowProjectOrderedSourcePaths([]);
    setPhotoSlideshowProjectTimelineItems([]);
    setPhotoSlideshowProjectSlideMotion("auto");
    setPhotoSlideshowProjectSlideTransitionEffect("auto");
    setPhotoSlideshowProjectSlideTransitionDurationMs(650);
    setPhotoSlideshowProjectFocalX(50);
    setPhotoSlideshowProjectFocalY(50);
    setPhotoSlideshowProjectCropZoom(1);
    resetPhotoSlideshowCaptionDraft(null);
  }

  function selectPhotoSlideshowCaptionLayer(layer: PhotoSlideshowCaptionLayerChoice) {
    setPhotoSlideshowProjectCaptionLayer(layer);
    const selectedSet = new Set([...selectedSources].map((sourcePath) => String(sourcePath || "").trim()).filter(Boolean));
    const selectedItem = photoSlideshowProjectTimelineItems.find((item) => selectedSet.has(item.sourcePath)) || null;
    resetPhotoSlideshowCaptionDraft(selectedItem ? photoSlideshowCaptionDraftForLayer(selectedItem, layer) : null);
  }

