    setPhotoSlideshowProjectAudioPlacementStartSourcePath(movieDraft.audioPlacementStartSourcePath);
    setPhotoSlideshowProjectAudioPlacementEndSourcePath(movieDraft.audioPlacementEndSourcePath);
    setPhotoSlideshowProjectIncludeTitleCard(movieDraft.includeTitleCard);
    setPhotoSlideshowProjectTitleCardTitle(movieDraft.titleCardTitle);
    setPhotoSlideshowProjectTitleCardSubtitle(movieDraft.titleCardSubtitle);
    setPhotoSlideshowProjectTitleCardDurationMs(movieDraft.titleCardDurationMs);
    setPhotoSlideshowProjectTitleCardPalette(movieDraft.titleCardPalette);
    setPhotoSlideshowProjectTitleCardLayout(movieDraft.titleCardLayout);
    setPhotoSlideshowProjectTitleCardFontScale(movieDraft.titleCardFontScale);
    setPhotoSlideshowProjectTitleCardShowFooter(movieDraft.titleCardShowFooter);
