  function recordOpenWithHandoff(sourcePath: string, surface: string, result: OpenPathWithResult | null, repeatEditor = false) {
    if (!result?.opened || !sourcePath) return;
    void recordPhotoAssetEvent({
      eventType: "shared",
      sourcePaths: [sourcePath],
      metadata: { surface, action: repeatEditor ? "open_with_last_external_editor" : "open_with_external_editor" },
    }).then(() => {
      void loadFolders();
    }).catch(() => {
      // External editor handoff should still succeed if the local event log is unavailable.
    });
  }

  async function openOriginalWithEditor(sourcePath: string, surface: string, editorPath = "") {
    if (!sourcePath) return;
    const result = await openPathWith(sourcePath, editorPath || undefined);
    recordOpenWithHandoff(sourcePath, surface, result, Boolean(editorPath));
  }

