  async function addSelectedToManualAlbum() {
    if (!selectedSourcePaths.length) return;
    setAlbumItemSaving(true);
    setAlbumItemError("");
    try {
      const albumDraft = photoManualAlbumAddDraft({
        sourcePaths: selectedSourcePaths,
        targetAlbumId: manualAlbumTargetId,
        newAlbumName: manualAlbumName,
      });
      if (!albumDraft) return;
      let albumId = albumDraft.albumId;
      if (albumDraft.createAlbum) {
        const result = await savePhotoAlbum(albumDraft.createAlbum);
        const value = result.value && typeof result.value === "object" ? result.value as { albumId?: unknown } : {};
        albumId = String(value.albumId || "");
        setManualAlbumTargetId(albumId);
        setManualAlbumName("");
      }
      if (!albumId) throw new Error(uiText("Album was not created"));
      await addPhotoAlbumItems({ albumId, sourcePaths: albumDraft.sourcePaths });
      setSelectedSources(new Set());
      await loadFolders();
      await loadSuggestions();
      await loadPhotoOperations();
      setActiveId(`album:${albumId}`);
    } catch (error) {
      setAlbumItemError(error instanceof Error ? error.message : String(error));
    } finally {
      setAlbumItemSaving(false);
    }
  }

