  async function loadSortedFolderSourceOrder(folderId: string, orderSort: PhotoSort, missingMessage: string) {
    const sourcePaths: string[] = [];
    let offset = 0;
    let expectedTotal = 0;
    while (expectedTotal === 0 || sourcePaths.length < expectedTotal) {
      const page = await itemsFnRef.current({
        folderId,
        offset,
        limit: SORTED_SOURCE_ORDER_PAGE_LIMIT,
        previewBudget: 0,
        sort: orderSort,
      });
      if (offset === 0) expectedTotal = Math.max(0, Number(page.total || 0));
      const pageSources = (page.items || []).map((item) => item.sourcePath).filter(Boolean);
      if (!pageSources.length) break;
      sourcePaths.push(...pageSources);
      offset += pageSources.length;
    }
    if (expectedTotal > 0 && sourcePaths.length < expectedTotal) {
      throw new Error(missingMessage);
    }
    return sourcePaths;
  }

  async function loadAlbumSourceOrderById(albumId: string, orderSort: PhotoSort = "manual") {
    const cleanAlbumId = String(albumId || "").trim();
    if (!cleanAlbumId) return [];
    if (orderSort === "manual") {
      const result = await photoAlbumSourceOrder({ albumId: cleanAlbumId });
      return (result.value?.sourcePaths || []).map((path) => String(path || "")).filter(Boolean);
    }
    return loadSortedFolderSourceOrder(
      `album:${cleanAlbumId}`,
      orderSort,
      uiText("Could not load the full album order.")
    );
  }

  async function loadManualAlbumSourceOrder(orderSort: PhotoSort = "manual") {
    if (!activeAlbum?.albumId) return items.map((item) => item.sourcePath);
    if (orderSort !== "manual" && total > 0 && items.length >= total && sort === orderSort) return items.map((item) => item.sourcePath);
    return loadAlbumSourceOrderById(activeAlbum.albumId, orderSort);
  }

  async function loadUserMemorySourceOrder(orderSort: PhotoSort = "manual") {
    if (!activeMemoryId) return items.map((item) => item.sourcePath);
    if (orderSort === "manual") {
      const result = await photoUserMemorySourceOrder({ memoryId: activeMemoryId });
      return (result.value?.sourcePaths || []).map((path) => String(path || "")).filter(Boolean);
    }
    if (total > 0 && items.length >= total && sort === orderSort) return items.map((item) => item.sourcePath);
    return loadSortedFolderSourceOrder(activeId, orderSort, uiText("Could not load the full memory order."));
  }

  async function saveUserMemorySourceOrder(sourcePaths: string[]) {
    if (!activeMemoryUserCreated || !activeMemoryId || sourcePaths.length < 2) return;
    await savePhotoUserMemory({
      memoryId: activeMemoryId,
      name: activeMemory?.name || activeMemory?.memory?.name || uiText("Memory"),
      subtitle: activeMemory?.memory?.subtitle || "",
      sourcePaths,
      coverSourcePath: activeMemory?.memory?.coverSourcePath || sourcePaths[0] || "",
      libraryRoot: activeLibraryRootRef.current,
      libraryRootProfileId: activeLibraryRootProfileIdRef.current,
    });
    await photoUserMemories({});
    await loadFolders();
  }

  function albumReorderResultValue(result: unknown): PhotoAlbumReorderResult | null {
    const value = result && typeof result === "object" && "value" in result
      ? (result as { value?: unknown }).value
      : result;
    return value && typeof value === "object" ? value as PhotoAlbumReorderResult : null;
  }

  function recordManualAlbumReorderResult(result: unknown) {
    const message = photoAlbumReorderNotice(albumReorderResultValue(result));
    if (message) notifyToast({ tone: "ok", message });
  }

  async function saveCurrentSortAsManualAlbumOrder() {
    if (!activeAlbum?.albumId) return;
    setAlbumItemError("");
    setAlbumOrderNotice("");
    if (!manualAlbumOrderScopeIsWhole) {
      setAlbumItemError(uiText("Clear search and filters before changing custom order."));
      return;
    }
    if (sort === "manual") {
      setAlbumItemError(uiText("Choose a different sort before saving a custom order."));
      return;
    }
    setAlbumItemSaving(true);
    try {
      const nextOrder = await loadManualAlbumSourceOrder(sort);
      if (nextOrder.length < 2) return;
      const result = await reorderPhotoAlbumItems({ albumId: activeAlbum.albumId, sourcePaths: nextOrder });
      recordManualAlbumReorderResult(result);
      await loadFolders();
      await loadPhotoOperations();
      setSort("manual");
      loadPage(currentPageRequest({ offset: 0, sort: "manual" }));
    } catch (error) {
      setAlbumItemError(error instanceof Error ? error.message : String(error));
    } finally {
      setAlbumItemSaving(false);
    }
  }

