  async function reorderSelectedManualAlbum(direction: PhotoAlbumMoveDirection) {
    if (!activeAlbum?.albumId || !selectedSourcePaths.length) return;
    setAlbumItemError("");
    setAlbumOrderNotice("");
    if (sort !== "manual") {
      setAlbumItemError(uiText("Switch to Custom order before reordering this album."));
      return;
    }
    if (!manualAlbumOrderScopeIsWhole) {
      setAlbumItemError(uiText("Clear search and filters before changing custom order."));
      return;
    }
    setAlbumItemSaving(true);
    try {
      const currentOrder = await loadManualAlbumSourceOrder();
      const nextOrder = reorderSelectedPhotoSources(currentOrder, selectedSources, direction);
      if (nextOrder.join("\n") === currentOrder.join("\n")) return;
      const result = await reorderPhotoAlbumItems({ albumId: activeAlbum.albumId, sourcePaths: nextOrder });
      recordManualAlbumReorderResult(result);
      await loadFolders();
      await loadPhotoOperations();
      loadPage(currentPageRequest({ offset: 0, sort: "manual" }));
    } catch (error) {
      setAlbumItemError(error instanceof Error ? error.message : String(error));
    } finally {
      setAlbumItemSaving(false);
    }
  }

